def _spot_src(ticker, leg):
    """Which price the leg's Spot actually is: Live / AH / PM / EOD.

    Legs carry BOTH `spot` (live-or-AH) and `eod_spot` (confirmed close), so the source is
    derived from the leg itself rather than re-deciding it here — if they match, no extended
    price was applied and it is the EOD close. Only when they differ do we ask _get_ah_price
    (20s cache) for the session label. Without this column "price hasn't moved" and "we are
    not showing you a live price" look identical on screen.
    """
    try:
        _s = float(leg.get("spot") or 0)
        _e = float(leg.get("eod_spot") or 0)
    except (TypeError, ValueError):
        return "EOD"
    if _s <= 0 or _e <= 0 or abs(_s - _e) < 1e-9:
        return "EOD"
    try:
        return (_get_ah_price(ticker) or {}).get("label") or "Live"
    except Exception:
        return "Live"


def _si_cells(ticker):
    """(SI %, DTC, Shorts) display cells — '—' when the ticker has no short-interest feed.

    DTC is always a STRING (never a bare float/None) — mixing float DTC values for some
    tickers with None/'' for others in the same dataframe column crashed Streamlit's Arrow
    conversion outright (pyarrow.lib.ArrowInvalid: "Could not convert '' with type str: tried
    to convert to double"), which silently halted the WHOLE page mid-render with no visible
    error banner -- everything after that table (including Closed Positions) never rendered.
    Verified via server log, not just browser inspection -- that's what actually caught this."""
    r = _si_for(ticker)
    if not r:
        return "—", "—", "—"
    arrow = {"BUILDING": "🔺", "COVERING": "🔻", "STABLE": "▪"}.get(r["state"], "")
    chg = f" {r['chg'] * 100:+.0f}%" if r.get("chg") is not None else ""
    return (f"{r['pct_float']:.1f}%", f"{r['dtc']:.1f}",
            f"{arrow} {r['state'].title()}{chg}")


def _keyvault_key(salt):
    """Derive a 64-byte key, machine/user-bound (or KEYVAULT_PASSPHRASE if set)."""
    import hashlib, getpass, platform
    secret = os.environ.get("KEYVAULT_PASSPHRASE") or f"{getpass.getuser()}|{platform.node()}|nyse-data-keyvault-v1"
    return hashlib.pbkdf2_hmac("sha256", secret.encode("utf-8"), salt, 200000, dklen=64)


def _keyvault_encrypt(plaintext):
    """Encrypt with an HMAC-SHA256 keystream (CTR) + encrypt-then-MAC. Stdlib only."""
    import hmac, hashlib, base64
    salt = os.urandom(16); nonce = os.urandom(16)
    k = _keyvault_key(salt); enc_key, mac_key = k[:32], k[32:]
    data = plaintext.encode("utf-8")
    ks = bytearray(); ctr = 0
    while len(ks) < len(data):
        ks.extend(hmac.new(enc_key, nonce + ctr.to_bytes(8, "big"), hashlib.sha256).digest()); ctr += 1
    ct = bytes(a ^ b for a, b in zip(data, ks[:len(data)]))
    tag = hmac.new(mac_key, salt + nonce + ct, hashlib.sha256).digest()
    return base64.b64encode(b"NVK1" + salt + nonce + ct + tag).decode("ascii")


def _keyvault_decrypt(blob):
    import hmac, hashlib, base64
    raw = base64.b64decode(blob)
    if raw[:4] != b"NVK1":
        raise ValueError("bad vault format")
    salt, nonce, tag, ct = raw[4:20], raw[20:36], raw[-32:], raw[36:-32]
    k = _keyvault_key(salt); enc_key, mac_key = k[:32], k[32:]
    if not hmac.compare_digest(tag, hmac.new(mac_key, salt + nonce + ct, hashlib.sha256).digest()):
        raise ValueError("vault integrity check failed (wrong machine/passphrase?)")
    ks = bytearray(); ctr = 0
    while len(ks) < len(ct):
        ks.extend(hmac.new(enc_key, nonce + ctr.to_bytes(8, "big"), hashlib.sha256).digest()); ctr += 1
    return bytes(a ^ b for a, b in zip(ct, ks[:len(ct)])).decode("utf-8")


def _load_api_keys():
    """Load API keys into os.environ from the encrypted vault api_keys.enc (machine-bound).
    If only the plaintext api_keys.env exists, load it, encrypt it to api_keys.enc, and delete
    the plaintext — so keys live encrypted at rest."""
    try:
        _dir = os.path.dirname(os.path.abspath(__file__))
        _enc = os.path.join(_dir, "api_keys.enc")
        _plain = os.path.join(_dir, "api_keys.env")
        text = None
        if os.path.exists(_enc):
            try:
                text = _keyvault_decrypt(open(_enc, encoding="utf-8").read())
            except Exception:
                text = None
        if text is None and os.path.exists(_plain):
            text = open(_plain, encoding="utf-8").read()
            try:
                with open(_enc, "w", encoding="utf-8") as _f:
                    _f.write(_keyvault_encrypt(text))
                os.remove(_plain)
            except Exception:
                pass
        if not text:
            return
        for _ln in text.splitlines():
            _ln = _ln.strip()
            if not _ln or _ln.startswith("#") or "=" not in _ln:
                continue
            _k, _v = _ln.split("=", 1)
            _k, _v = _k.strip(), _v.strip().strip('"').strip("'")
            if _k and _v and not os.environ.get(_k):
                os.environ[_k] = _v
    except Exception:
        pass


_load_api_keys()


def compute_walls(df, spot=None):
    """Identify the call wall (max call-OI strike = resistance) and put wall
    (max put-OI strike = support), with each wall's OI and strength (OI / mean OI).
    Input df needs columns: strike, openInt_Call_now, openInt_Put_now.
    (Inlined here — kept in the single main file, no separate module.)"""
    out = {
        "call_wall": None, "put_wall": None,
        "call_wall_oi": 0.0, "put_wall_oi": 0.0,
        "call_wall_strength": 0.0, "put_wall_strength": 0.0,
    }
    if df is None or len(df) == 0:
        return out
    try:
        d = df.copy()
        for col in ("strike", "openInt_Call_now", "openInt_Put_now"):
            if col in d.columns:
                d[col] = pd.to_numeric(d[col], errors="coerce")
        d = d.dropna(subset=["strike"])
        if d.empty:
            return out
        # Clamp to ±35% of spot — stale deep-OTM positions (e.g. $200 puts when spot=$420)
        # dominate idxmax() and produce nonsense walls; real support/resistance lives near price.
        if spot and spot > 0:
            d = d[(d["strike"] >= spot * 0.65) & (d["strike"] <= spot * 1.35)]
            if d.empty:
                return out
        c = d["openInt_Call_now"].fillna(0.0) if "openInt_Call_now" in d.columns else pd.Series(0.0, index=d.index)
        p = d["openInt_Put_now"].fillna(0.0) if "openInt_Put_now" in d.columns else pd.Series(0.0, index=d.index)
        mean_c = float(c[c > 0].mean()) if (c > 0).any() else 0.0
        mean_p = float(p[p > 0].mean()) if (p > 0).any() else 0.0
        if (c > 0).any():
            ci = c.idxmax()
            out["call_wall"] = float(d.loc[ci, "strike"])
            out["call_wall_oi"] = float(c.loc[ci])
            out["call_wall_strength"] = (out["call_wall_oi"] / mean_c) if mean_c > 0 else 0.0
        if (p > 0).any():
            pi = p.idxmax()
            out["put_wall"] = float(d.loc[pi, "strike"])
            out["put_wall_oi"] = float(p.loc[pi])
            out["put_wall_strength"] = (out["put_wall_oi"] / mean_p) if mean_p > 0 else 0.0
    except Exception:
        return out
    return out


def _kf(k):
    """Format an option strike without rounding away half-dollar (or finer) strikes:
    385.0 → '385', 617.5 → '617.5', 62.5 → '62.5'."""
    try:
        k = float(k)
    except Exception:
        return str(k)
    return f"{k:.0f}" if k == int(k) else (f"{k:.2f}".rstrip("0").rstrip("."))


import re

# Sanitize strings passed to Streamlit `markdown`/`write` to strip , style, and class
# attributes so any HTML produced here is safe for downstream use (e.g., Telegram messages).
def _sanitize_text(s):
    if not isinstance(s, str):
        return s
    s = re.sub(r'</?span[^>]*>', '', s)
    s = re.sub(r"\s*(style|class)=(\".*?\"|'.*?')", '', s)
    return s

def _esc_md_dollars(s):
    """Escape literal $ so Streamlit's markdown does NOT parse '$…$' as LaTeX math and
    scramble dollar amounts (fix 2026-07-20). Skips already-escaped \\$ (no double-up).
    Applied only in MARKDOWN mode — never to unsafe_allow_html HTML, where $ is literal."""
    if not isinstance(s, str):
        return s
    return re.sub(r'(?<!\\)\$', r'\\$', s)

# GUARD (fix 2026-07-20): Streamlit re-executes this whole file on every rerun, but `st` is a
# persistent module — so recapturing `st.markdown` on the 2nd run grabbed the ALREADY-patched
# wrapper, making _st_markdown call itself forever (RecursionError, dashboard dead). Only wrap
# the genuine original, once, and skip if already wrapped.
if not getattr(st.markdown, "_sanitized_wrapper", False):
    _original_st_markdown = st.markdown
    _original_st_write = st.write
    _original_st_caption = st.caption
    def _prep(text, kwargs):
        t = _sanitize_text(text)
        if not kwargs.get("unsafe_allow_html"):     # markdown mode -> protect $ from LaTeX
            t = _esc_md_dollars(t)
        return t
    def _st_markdown(text, *args, **kwargs):
        return _original_st_markdown(_prep(text, kwargs), *args, **kwargs)
    def _st_write(text, *args, **kwargs):
        return _original_st_write(_prep(text, kwargs), *args, **kwargs)
    def _st_caption(text, *args, **kwargs):
        return _original_st_caption(_prep(text, kwargs), *args, **kwargs)
    _st_markdown._sanitized_wrapper = True
    _st_write._sanitized_wrapper = True
    _st_caption._sanitized_wrapper = True
    st.markdown = _st_markdown
    st.write = _st_write
    st.caption = _st_caption

# One-time in-place cleanup: remove remaining  tags and inline style/class
# attributes from the source file so the dashboard source is safe for reuse.
def _cleanup_dashboard_source():
    try:
        path = __file__
        with open(path, 'r', encoding='utf-8') as f:
            src = f.read()
        cleaned = re.sub(r'</?span[^>]*>', '', src)
        cleaned = re.sub(r"\s*(style|class)=(\".*?\"|'.*?')", '', cleaned)
        if cleaned != src:
            with open(path, 'w', encoding='utf-8') as f:
                f.write(cleaned)
            # Log to stdout so developers notice the cleanup
            print("[dashboard] cleaned /style/class from source")
    except Exception:
        pass

# Run the cleanup during import (safe and idempotent).
_cleanup_dashboard_source()

