# OI Intent Algorithm (hedge-aware) — used across all OI analysis sections
# ---------------------------------------------------------------------------
def _oi_signal_light(call_chg, put_chg, pcr=1.0):
    """Aggregate-level hedge-aware OI signal. Returns (label, hex_color)."""
    c, p = float(call_chg or 0), float(put_chg or 0)
    pcr  = float(pcr or 1.0)
    if c > abs(p) * 1.2 and c > 0:
        return ("BULLISH", "#2E7D32")
    if p > abs(c) * 1.2 and p > 0:
        if pcr > 1.5 and c >= -200:
            return ("HEDGE", "#1565C0")
        return ("BEARISH", "#C62828")
    if c > 200 and p > 200:
        if c > p * 1.4:  return ("BULL+HEDGE", "#388E3C")
        return ("STRADDLE", "#6A1B9A")
    if c < 0 and p < 0:
        return ("UNWIND", "#757575")
    return ("NEUTRAL", "#455A64")


def _oi_intent_algo(df, spot):
    """
    Per-strike hedge-aware OI intent classification.
    Expects df with 'strike', 'call_oi_change', 'put_oi_change' columns.
    Returns (enriched_df, signal, color, description, details_dict).

    Zones: ATM (+-3%), NEAR_PUT (3-10% below), DEEP_PUT (>10% below = hedge),
           NEAR_CALL (3-7% above), FAR_CALL (>7% = covered call).
    Deep OTM puts get 70% discount in score -- they are protective hedges, not directional.
    """
    df = df.copy()
    df["_pct"] = (df["strike"] - spot) / spot
    ATM_BAND, NEAR_BAND, FAR_CALL = 0.03, 0.10, 0.07
    _COLORS = {
        "BULLISH": "#2E7D32", "BEARISH": "#C62828", "STRADDLE": "#6A1B9A",
        "NEAR_BEARISH": "#BF360C", "HEDGE": "#1565C0", "HEDGE_UNWIND": "#42A5F5",
        "BULLISH_BREAK": "#388E3C", "COVERED_CALL": "#F57F17",
        "UNWIND": "#757575", "NEUTRAL": "#90A4AE",
    }
    def _cls(row):
        pct, cd, pd_ = row["_pct"], float(row.get("call_oi_change", 0)), float(row.get("put_oi_change", 0))
        z = ("ATM" if abs(pct) <= ATM_BAND else
             "NEAR_PUT" if pct < -ATM_BAND and pct >= -NEAR_BAND else
             "DEEP_PUT" if pct < -NEAR_BAND else
             "NEAR_CALL" if pct > ATM_BAND and pct <= FAR_CALL else "FAR_CALL")
        if z == "ATM":
            if cd>0 and pd_>0 and min(cd,pd_)/(abs(cd)+abs(pd_)+1)>0.25: return "STRADDLE"
            if cd>0: return "BULLISH"
            if pd_>0: return "BEARISH"
            if cd<0 and pd_<0: return "UNWIND"
        elif z == "NEAR_PUT":
            if pd_>0: return "NEAR_BEARISH"
            if cd>0: return "BULLISH_BREAK"
        elif z == "DEEP_PUT":
            if pd_>0: return "HEDGE"
            if pd_<0: return "HEDGE_UNWIND"
            if cd>0: return "BULLISH_BREAK"
        elif z == "NEAR_CALL":
            if cd>0: return "BULLISH_BREAK"
            if pd_>0: return "NEAR_BEARISH"
        elif z == "FAR_CALL":
            if cd>0: return "COVERED_CALL"
        return "NEUTRAL"
    df["intent"]  = df.apply(_cls, axis=1)
    df["bar_col"] = df["intent"].map(_COLORS).fillna("#90A4AE")
    m_atm = abs(df["_pct"]) <= ATM_BAND
    m_np  = (df["_pct"] < -ATM_BAND) & (df["_pct"] >= -NEAR_BAND)
    m_dp  = df["_pct"] < -NEAR_BAND
    m_oc  = df["_pct"] > ATM_BAND
    atm_cd = float(df.loc[m_atm,"call_oi_change"].sum()); atm_pd = float(df.loc[m_atm,"put_oi_change"].sum())
    nput_pd = float(df.loc[m_np,"put_oi_change"].sum());  dput_pd = float(df.loc[m_dp,"put_oi_change"].sum())
    otm_cd  = float(df.loc[m_oc,"call_oi_change"].sum())
    score  = atm_cd*2.0 - atm_pd*2.0 - nput_pd*1.5 - dput_pd*0.3 + otm_cd*0.8
    total  = abs(atm_cd)+abs(atm_pd)+abs(nput_pd)+abs(dput_pd)+abs(otm_cd)
    thresh = max(total*0.25, 500)
    h_ratio = dput_pd / (abs(dput_pd)+abs(nput_pd)+abs(atm_pd)+1)
    if dput_pd>0 and h_ratio>0.5 and atm_cd>=0:
        sig,sc,desc = "HEDGED BULL","#1B5E20","Institutions hedging longs — call side accumulating"
    elif score>thresh:  sig,sc,desc = "BULLISH","#2E7D32","Net call build at ATM — buyers entering"
    elif score>0:       sig,sc,desc = "MILD BULL","#558B2F","Slight call bias — watch for follow-through"
    elif score<-thresh: sig,sc,desc = "BEARISH","#B71C1C","Net put build at ATM — directional shorts"
    elif score<0:       sig,sc,desc = "MILD BEAR","#BF360C","Slight put bias — monitor for acceleration"
    elif atm_cd>0 and atm_pd>0: sig,sc,desc = "STRADDLE","#6A1B9A","Both sides at ATM — vol/event play"
    elif total<200:     sig,sc,desc = "QUIET","#455A64","Low OI change — no conviction"
    else:               sig,sc,desc = "NEUTRAL","#455A64","Balanced activity — no edge"
    return df, sig, sc, desc, dict(atm_cd=atm_cd,atm_pd=atm_pd,nput_pd=nput_pd,
                                    dput_pd=dput_pd,otm_cd=otm_cd,score=score,hedge_pct=h_ratio*100)

# ---------------------------------------------------------------------------
def get_conn():
    c = sqlite3.connect(DB_PATH)
    try:                                             # faster reads on the larger BB DB (every page)
        c.execute("PRAGMA mmap_size=268435456")      # 256MB memory-mapped reads
        c.execute("PRAGMA cache_size=-64000")        # 64MB page cache
        c.execute("PRAGMA temp_store=MEMORY")
    except Exception:
        pass
    return c

def q(sql, params=None):
    """Quick query → DataFrame"""
    with get_conn() as c:
        return pd.read_sql(sql, c, params=params or [])

@st.cache_data(ttl=300, show_spinner=False)
def _cached_history(ticker: str, period: str = "5d", interval: str = "1d"):
    """yfinance history — cached 5 min to avoid hammering the API on every rerender
    (use the page's Refresh button to force-refresh)."""
    try:
        return yf.Ticker(ticker).history(period=period, interval=interval)
    except Exception:
        return pd.DataFrame()

@st.cache_data(ttl=300, show_spinner=False)
def _dma_status(ticker: str, spot: float):
    """50/200-day SMA trend read (user 2026-07-18: add to Portfolio tabs).
    50DMA = short/medium trend filter; 200DMA = the standard bull/bear line;
    50 crossing above 200 = Golden Cross (bullish), below = Death Cross (bearish).
    Returns None if <200d of history (recent IPO)."""
    try:
        h = _cached_history(ticker, period="14mo", interval="1d")["Close"].dropna()
        if len(h) < 200:
            return None
        dma50  = float(h.tail(50).mean())
        dma200 = float(h.tail(200).mean())
        golden = dma50 > dma200
        above50  = spot > dma50
        above200 = spot > dma200
        if above50 and above200:
            em, lbl = "🟢", "above both — uptrend"
        elif not above50 and not above200:
            em, lbl = "🔴", "below both — downtrend"
        else:
            em, lbl = "🟡", "mixed"
        return {"dma50": dma50, "dma200": dma200, "golden": golden,
                "above50": above50, "above200": above200, "em": em, "lbl": lbl}
    except Exception:
        return None


@st.cache_data(ttl=300, show_spinner=False)
def _db_spot(ticker: str) -> float:
    """Confirmed EOD close from stock_daily DB (MM-DD-YYYY sorted). Primary source for portfolio calcs."""
    try:
        with get_conn() as _c:
            row = pd.read_sql(
                "SELECT close FROM stock_daily WHERE ticker=? "
                "ORDER BY trade_date DESC LIMIT 1",
                _c, params=[ticker]
            )
        if not row.empty:
            return float(row["close"].iloc[0])
    except Exception:
        pass
    return 0.0


def _db_spot_date(ticker: str) -> str:
    """trade_date (MM-DD) of the stock_daily row `_db_spot` uses — lets the UI show HOW
    fresh 'EOD' is (the nightly pipeline can lag a session, e.g. mid-run in the evening)."""
    try:
        with get_conn() as _c:
            row = _c.execute("SELECT MAX(trade_date) FROM stock_daily WHERE ticker=?",
                             (ticker,)).fetchone()
        return str(row[0] or "")[5:]
    except Exception:
        return ""

@st.cache_data(ttl=60, show_spinner=False)
def _cached_price(ticker: str) -> float:
    """LIVE last price (yfinance fast_info, 60s cache) — after hours this equals the
    official close. DB stock_daily close, then history, as fallbacks.
    (Live-everywhere during market hours, user ask 2026-07-17.)"""
    try:
        fi = yf.Ticker(ticker).fast_info
        px = float(fi.get("lastPrice") or fi.get("regularMarketPrice") or 0)
        if px > 0:
            return px
    except Exception:
        pass
    db = _db_spot(ticker)
    if db > 0:
        return db
    # Bare foreign symbol (MOTHERSON -> MOTHERSON.NS), via the SAME resolver the bot uses.
    # Only reached once every US lane is empty, so no US ticker pays for it. Without this
    # the grid fell back to the ENTRY price and the position looked flat forever.
    try:
        alt = _TB_ENGINE._yf_alias(ticker) if _TB_ENGINE else None
        if alt:
            _px = float(yf.Ticker(alt).fast_info.get("lastPrice") or 0)
            if _px > 0:
                return _px
            _h = _cached_history(alt, period="5d")
            if len(_h) >= 1:
                return float(_h["Close"].iloc[-1])
    except Exception:
        pass
    try:
        h = _cached_history(ticker, period="5d")
        return float(h["Close"].iloc[-1]) if len(h) >= 1 else 0.0
    except Exception:
        return 0.0

@st.cache_data(ttl=900, show_spinner=False)
def _cached_info(ticker: str) -> dict:
    """yfinance .info (15-min cache) with a DB write-through + fallback (2026-07-21): every
    successful pull is snapshotted to fundamentals_cache, so a yahoo .info outage doesn't blank
    the dashboard — it serves the last good snapshot (marked _snapshot_stale) instead. The cache
    self-populates as the dashboard is used; no separate pipeline job needed."""
    import json as _json
    from datetime import datetime as _dtm
    info = {}
    try:
        info = dict(yf.Ticker(ticker).info or {})
    except Exception:
        info = {}
    if info and len(info) > 5:                    # good live pull -> write through
        try:
            with get_conn() as _c:
                # separate table (NOT the curated fundamentals_cache, which stores different keys)
                _c.execute("CREATE TABLE IF NOT EXISTS yf_info_cache "
                           "(ticker TEXT PRIMARY KEY, asof TEXT, info_json TEXT)")
                _c.execute("INSERT OR REPLACE INTO yf_info_cache VALUES (?,?,?)",
                           (ticker.upper(), _dtm.now().strftime("%Y-%m-%d %H:%M"),
                            _json.dumps(info, default=str)))
        except Exception:
            pass
        return info
    # yahoo .info failed/empty -> serve the last good snapshot so the page still renders
    try:
        with get_conn() as _c:
            _c.execute("CREATE TABLE IF NOT EXISTS yf_info_cache "
                       "(ticker TEXT PRIMARY KEY, asof TEXT, info_json TEXT)")
            _row = _c.execute("SELECT asof, info_json FROM yf_info_cache WHERE ticker=?",
                              (ticker.upper(),)).fetchone()
        if _row and _row[1]:
            _d = _json.loads(_row[1])
            _d["_snapshot_stale"] = True
            _d["_snapshot_asof"] = _row[0]
            return _d
    except Exception:
        pass
    return {}


@st.cache_data(ttl=21600, show_spinner=False)
def _next_events(ticker: str):
    """(next earnings date, next ex-dividend date) as YYYY-MM-DD strings ('—' if unknown).
    Cached 6h — used to annotate position/leg tables. Earnings via the bot helper, ex-div via .info."""
    earn = div = "—"
    try:
        import telegram_bot_optimized as _tb
        ne = _tb._next_earnings(ticker)
        if ne and ne.get("date"):
            earn = str(ne["date"])[:10]
    except Exception:
        pass
    try:
        ed = (_cached_info(ticker) or {}).get("exDividendDate")
        if ed:
            import datetime as _dt
            div = (_dt.datetime.utcfromtimestamp(int(ed)).strftime("%Y-%m-%d")
                   if isinstance(ed, (int, float)) else str(ed)[:10])
    except Exception:
        pass
    return earn, div

@st.cache_data(ttl=300, show_spinner=False)
def _cached_option_chain(ticker: str, expiry: str):
    """yfinance option_chain — cached 5 min. Returns an object with .calls/.puts (or None),
    so existing call sites keep working unchanged."""
    from types import SimpleNamespace
    try:
        oc = yf.Ticker(ticker).option_chain(expiry)
        return SimpleNamespace(calls=oc.calls, puts=oc.puts)
    except Exception:
        return None

@st.cache_data(ttl=3600, show_spinner=False)
def _historical_vol(ticker: str, window: int = 30) -> float:
    """Annualised 30-day realised volatility from daily log-returns. Fallback 0.30."""
    try:
        h = _cached_history(ticker, period="90d")
        if len(h) < 10:
            return 0.30
        lr = np.log(h["Close"] / h["Close"].shift(1)).dropna()
        hv = float(lr.tail(window).std() * np.sqrt(252))
        return max(0.05, min(4.0, hv))
    except Exception:
        return 0.30

# ── Reusable time-range picker for time-series charts ─────────────────────────
# Brokerage-style ranges. Intraday (DB has no intraday) → yfinance; the rest are
# DB-first (stock_daily) with a yfinance fallback. Use _chart_range_picker() to
# render the control and _history_for_range()/_ohlc_for_range() to fetch bars.
_CHART_RANGES = ["1D", "1W", "1M", "MTD", "YTD", "1Y", "5Y", "ALL"]


def _chart_range_picker(key: str, default: str = "1M", options=None, label="Range"):
    """Render a compact per-chart range selector; return the chosen range key.
    Selection is remembered per `key` across reruns."""
    opts = list(options or _CHART_RANGES)
    cur = st.session_state.get(key, default)
    if cur not in opts:
        cur = default if default in opts else opts[0]
    try:
        sel = st.segmented_control(label, opts, default=cur, key=f"{key}_sc",
                                   label_visibility="collapsed")
    except Exception:
        sel = st.radio(label, opts, index=opts.index(cur), horizontal=True,
                       key=f"{key}_rd", label_visibility="collapsed")
    sel = sel or cur
    st.session_state[key] = sel
    return sel


def _range_start(rng: str):
    """Pandas Timestamp for the start of a range, or None for 1D/ALL (no lower bound)."""
    today = pd.Timestamp(pd.Timestamp.today().date())
    return {
        "1W":  today - pd.Timedelta(days=7),
        "1M":  today - pd.Timedelta(days=31),
        "MTD": today.replace(day=1),
        "YTD": today.replace(month=1, day=1),
        "1Y":  today - pd.Timedelta(days=366),
        "5Y":  today - pd.Timedelta(days=366 * 5),
    }.get((rng or "").upper())


@st.cache_data(ttl=120, show_spinner=False)
def _db_close_history(ticker: str) -> pd.DataFrame:
    """Full daily Close history from stock_daily — chronological, tz-naive DatetimeIndex."""
    try:
        df = _q("SELECT trade_date, close FROM stock_daily WHERE ticker=?", [ticker.upper()])
    except Exception:
        return pd.DataFrame()
    if df is None or df.empty:
        return pd.DataFrame()
    df["dt"] = pd.to_datetime(df["trade_date"], format="%Y-%m-%d", errors="coerce")
    df = df.dropna(subset=["dt"]).sort_values("dt").set_index("dt")
    return df[["close"]].rename(columns={"close": "Close"})


def _history_for_range(ticker: str, rng: str) -> pd.DataFrame:
    """Close-history (tz-naive DatetimeIndex, 'Close' column) for a range key.
    Intraday (1D/1W) → yfinance; daily ranges are DB-first with a yfinance fallback."""
    rng = (rng or "1M").upper()
    if rng in ("1D", "1W"):
        per, itv = ("1d", "5m") if rng == "1D" else ("5d", "30m")
        h = _cached_history(ticker, period=per, interval=itv)
        return h[["Close"]].dropna() if h is not None and not h.empty else pd.DataFrame()

    start = _range_start(rng)
    db = _db_close_history(ticker)
    if not db.empty:
        out = db if start is None else db[db.index >= start]
        if len(out) >= 2:
            return out
    # Fallback / supplement from yfinance when the DB lacks this ticker or range
    yf_period = {"1M": "1mo", "MTD": "2mo", "YTD": "1y",
                 "1Y": "1y", "5Y": "5y", "ALL": "max"}.get(rng, "1y")
    h = _cached_history(ticker, period=yf_period, interval="1d")
    if h is None or h.empty:
        return db if not db.empty else pd.DataFrame()
    h = h[["Close"]].dropna()
    if getattr(h.index, "tz", None) is not None:
        h.index = h.index.tz_localize(None)
    if start is not None:
        h = h[h.index >= start]
    return h


def _ohlc_for_range(ticker: str, rng: str) -> pd.DataFrame:
    """OHLC bars for a range key (yfinance — stock_daily stores close only, so candles
    always come from yfinance). tz-naive DatetimeIndex; MTD/YTD are sliced to the range."""
    rng = (rng or "1M").upper()
    per, itv = {
        "1D": ("1d", "5m"), "1W": ("5d", "30m"), "1M": ("1mo", "1d"),
        "MTD": ("3mo", "1d"), "YTD": ("1y", "1d"), "1Y": ("1y", "1d"),
        "5Y": ("5y", "1wk"), "ALL": ("max", "1wk"),
    }.get(rng, ("3mo", "1d"))
    h = _cached_history(ticker, period=per, interval=itv)
    if h is None or h.empty:
        return h if h is not None else pd.DataFrame()
    if getattr(h.index, "tz", None) is not None:
        h = h.copy()
        h.index = h.index.tz_localize(None)
    if rng in ("MTD", "YTD"):
        start = _range_start(rng)
        if start is not None:
            h = h[h.index >= start]
    return h

@st.cache_data(ttl=120, show_spinner=False)
def _smart_close_limit(side, cur, bid=None, ask=None, buf=None):
    """Limit price to CLOSE a position, biased toward keeping edge instead of conceding
    it away (PLAN.md A3, 2026-07-24). The old behavior always priced ~3% through the
    current mid/last — a real trader posts near the ask (selling) or bid (buying) first
    and only concedes if unfilled, not the other way around.

    With a real bid/ask: start 1/3 of the spread in from the best price (ask when
    selling, bid when buying), never worse than the mid — i.e. the order asks for MORE
    than a marketable limit would, while still inside the spread so it's plausible to fill.
    Without a live bid/ask (market closed, no quote): fall back to the old buffer-off-cur
    heuristic, which is the best available anchor at that point.
    Returns (price: float, from_quote: bool)."""
    closing_sell = (side == "long")   # long position closes by selling; short closes by buying
    if bid and ask and ask > bid > 0:
        spread = ask - bid
        mid = (bid + ask) / 2
        if closing_sell:
            px = max(ask - spread / 3, mid)
        else:
            px = min(bid + spread / 3, mid)
        return round(px, 2), True
    _buf = buf if buf is not None else max(0.05, round(float(cur or 0) * 0.03, 2))
    px = (max(cur - _buf, 0.01) if closing_sell else cur + _buf)
    return round(px, 2), False


def _scenario_liquidity_gate(conn, tk, strike, expiry_iso, typ, bid=None, ask=None):
    """Liquidity gate for the Day L-H / scenario-pricing recipe (validated 2026-07-14,
    docs/PLAN.md: 1.2M contract-days, time-split — liquid 22-45 DTE legs hit 3.6-5.3%
    median error; thin legs were NOT part of that validated sample and should not be
    shown with the same implied confidence).

    Gate: volume >= 100 (from the latest captured options_change row for this leg) AND
    bid/ask spread <= 8% of mid (only checked when a live bid/ask is actually available —
    absence of a live quote, e.g. after-hours, is NOT treated as a liquidity failure).
    Returns True (liquid / gate passes or inconclusive) or False (flag as thin).
    """
    row = None
    try:
        row = conn.execute(
            "SELECT vol_Call_now, vol_Put_now FROM options_change "
            "WHERE ticker=? AND strike=? AND expiry_date=? "
            "ORDER BY trade_date_now DESC LIMIT 1",
            (tk, float(strike), expiry_iso[:10])).fetchone()
        vol = float((row[0] if typ == "call" else row[1]) or 0) if row else 0.0
    except Exception:
        vol = 0.0
    if row is not None and vol < 100:
        return False
    if bid and ask and ask > bid > 0:
        mid = (bid + ask) / 2
        if mid > 0 and (ask - bid) / mid > 0.08:
            return False
    return True


def _fetch_option_quote(ticker: str, expiry_str: str, strike: float, opt_type: str
                        ) -> tuple:
    """Fetch real option bid/ask/mid/IV from yfinance options chain.
    Returns (mid, iv, bid, ask) — mid/iv/bid/ask all None when unavailable (market
    closed or expiry not listed). Superset of _fetch_option_mid (which wraps this for
    older callers that only want mid+iv); added 2026-07-24 (PLAN.md A3) so callers can
    build a real bid/ask-anchored closing limit instead of a flat % concession off mid."""
    try:
        if _market_state() == "CLOSED":
            return None, None, None, None
    except Exception:
        pass
    try:
        chain = yf.Ticker(ticker).option_chain(expiry_str)
        df = chain.calls if opt_type.upper() == "CALL" else chain.puts
        row = df[df["strike"] == float(strike)]
        if row.empty:
            near = df.iloc[(df["strike"] - strike).abs().argsort().iloc[:1]]
            if abs(float(near["strike"].iloc[0]) - strike) <= 2.5:
                row = near
        if row.empty:
            return None, None, None, None
        r = row.iloc[0]
        bid  = float(r.get("bid", 0) or 0)
        ask  = float(r.get("ask", 0) or 0)
        iv   = float(r.get("impliedVolatility", 0) or 0)
        # Only use real prices when market is live (bid+ask both non-zero)
        # Stale lastPrice during closed hours can be badly wrong
        if bid > 0 and ask > 0:
            mid = (bid + ask) / 2
        else:
            mid = None   # market closed → caller uses HV-based BS
            bid = ask = None
        return mid, (iv if iv > 0.02 else None), bid, ask
    except Exception:
        return None, None, None, None


def _fetch_option_mid(ticker: str, expiry_str: str, strike: float, opt_type: str
                      ) -> tuple:
    """Fetch real option mid-price and IV from yfinance options chain.
    Returns (mid_price, implied_vol) — both None when unavailable (market closed
    or expiry not listed). Thin wrapper over _fetch_option_quote for callers that
    don't need bid/ask."""
    mid, iv, _bid, _ask = _fetch_option_quote(ticker, expiry_str, strike, opt_type)
    return mid, iv


def _cusip_batch_to_ticker(cusips):
    """CUSIP -> US ticker via OpenFIGI's free mapping API (no key needed). Batches up to
    20 per request with a short pause between batches to stay under the unauthenticated
    rate limit. Returns {cusip: ticker or None}."""
    import requests as _rq
    import time as _time
    out = {}
    for i in range(0, len(cusips), 20):
        chunk = cusips[i:i + 20]
        try:
            resp = _rq.post(
                "https://api.openfigi.com/v3/mapping",
                json=[{"idType": "ID_CUSIP", "idValue": c, "exchCode": "US"} for c in chunk],
                headers={"Content-Type": "application/json"}, timeout=20)
            results = resp.json()
            for c, r in zip(chunk, results):
                data = r.get("data") or []
                out[c] = data[0].get("ticker") if data else None
        except Exception:
            for c in chunk:
                out.setdefault(c, None)
        _time.sleep(1)   # unauthenticated OpenFIGI limit is modest — stay well under it
    return out


def _cusip_sector_map(cusips):
    """CUSIP -> GICS-style sector string (or 'Unmapped'), for the Star Investors Sector
    Breakdown (PLAN.md, user 2026-07-24: 'sector breakdown, how money flowing to which
    sectors' was asked but never built — CUSIP->ticker was the missing step, resolved via
    OpenFIGI; ticker->sector reuses the existing fundamentals cache). Persists the CUSIP->
    ticker half PERMANENTLY (that mapping never changes) so repeat runs cost nothing."""
    with get_conn() as _c:
        _c.execute("CREATE TABLE IF NOT EXISTS cusip_ticker_map "
                   "(cusip TEXT PRIMARY KEY, ticker TEXT, asof TEXT)")
        _have = dict(pd.read_sql("SELECT cusip, ticker FROM cusip_ticker_map "
                                 "WHERE cusip IN ({})".format(",".join("?" * len(cusips))),
                                 _c, params=cusips).values.tolist()) if cusips else {}
    _missing = [c for c in cusips if c not in _have]
    if _missing:
        _resolved = _cusip_batch_to_ticker(_missing)
        with get_conn() as _c:
            _c.executemany(
                "INSERT OR REPLACE INTO cusip_ticker_map VALUES (?,?,?)",
                [(c, t, datetime.now().strftime("%Y-%m-%d")) for c, t in _resolved.items()])
            _c.commit()
        _have.update(_resolved)
    out = {}
    for cusip, ticker in _have.items():
        if not ticker:
            out[cusip] = "Unmapped"
            continue
        try:
            sec = (_cached_info(ticker) or {}).get("sector")
            out[cusip] = sec or "Unmapped"
        except Exception:
            out[cusip] = "Unmapped"
    return out


def _exp_to_date(d):
    """Any stored expiry/date string -> datetime.date. ISO YYYY-MM-DD first (all DB date
    cols are ISO since the 07-2026 census), legacy MM-DD-YYYY fallback. None if unparseable.
    Use this instead of positional split('-') hacks — those parsed ISO as month=2026 and
    silently produced DTE=-1 / wrong sort orders."""
    s = str(d)[:10]
    for _fmt in ("%Y-%m-%d", "%m-%d-%Y"):
        try:
            return datetime.strptime(s, _fmt).date()
        except Exception:
            continue
    return None


@st.cache_data(ttl=300, show_spinner=False)
def _db_option_price(ticker: str, expiry_iso: str, strike: float, opt_type: str) -> float | None:
    """EOD option last-price from options_change DB (most recent trade_date_now).
    expiry_date in the DB is ISO — query it directly (the old ISO->MM-DD-YYYY
    conversion matched nothing once the DB went ISO, so this always returned None).
    Returns float price or None if not found."""
    try:
        col = "lastPrice_Call_now" if opt_type.upper() == "CALL" else "lastPrice_Put_now"
        with get_conn() as _c:
            row = pd.read_sql(
                f"SELECT {col} AS price, trade_date_now FROM options_change "
                "WHERE ticker=? AND strike=? AND expiry_date=? "
                "ORDER BY trade_date_now DESC LIMIT 1",
                _c, params=[ticker, float(strike), str(expiry_iso)[:10]]
            )
        if not row.empty and row["price"].iloc[0] is not None:
            return float(row["price"].iloc[0])
    except Exception:
        pass
    return None

@st.cache_data(ttl=30, show_spinner=False)
def _get_ah_price(ticker: str) -> dict:
    """Fetch after-hours / pre-market / live price via yfinance fast_info. Returns dict with
    spot_reg, spot_ah, ah_chg_pct, is_extended, label ('AH'/'PM'/'Live'/'EOD').
    Cached 20s so a page with many legs hits yfinance once per ticker, not once per leg."""
    result = {"spot_reg": 0.0, "spot_ah": 0.0, "ah_chg_pct": 0.0, "is_extended": False, "label": "EOD"}
    try:
        fi = yf.Ticker(ticker).fast_info
        # Use DB stock_daily as primary for spot_reg (confirmed EOD close, no pre-market contamination)
        reg = _db_spot(ticker)
        if reg <= 0:
            reg = float(getattr(fi, "regular_market_previous_close", 0) or 0)
        result["spot_reg"] = reg

        post = 0.0; pre = 0.0
        # When the market is OPEN, fast_info.last_price IS the live price — skip the slow .info.
        # Otherwise fetch .info for the pre/post-market print. yfinance keeps serving the last
        # postMarketPrice well past the official 20:00 close, and an earnings move that lands at
        # 4:05pm must stay visible at 11pm — so fetch anytime OUTSIDE 09:30-16:00 RTH on a
        # weekday, not just the 16:00-20:00 AFTER window (fix 2026-07-22: matches the bot's
        # _get_spot_with_ah; the dashboard reverted to the stale EOD close all evening).
        from datetime import datetime as _dt2
        try:
            from zoneinfo import ZoneInfo as _ZI
            _nyt = _dt2.now(_ZI("America/New_York"))
        except Exception:
            _nyt = _dt2.now()
        _tmin = _nyt.hour * 60 + _nyt.minute
        if _nyt.weekday() < 5 and not (9 * 60 + 30 <= _tmin < 16 * 60):
            try:
                _di = _cached_info(ticker)
                post = float(_di.get("postMarketPrice") or 0)
                pre  = float(_di.get("preMarketPrice") or 0)
            except Exception:
                pass
        last = float(getattr(fi, "last_price", 0) or 0)

        if post > 0:
            result["spot_ah"]     = post
            result["is_extended"] = True
            result["label"]       = "AH"
        elif pre > 0:
            result["spot_ah"]     = pre
            result["is_extended"] = True
            result["label"]       = "PM"
        elif last > 0 and reg > 0 and abs(last - reg) / reg > 0.0005:
            result["spot_ah"]     = last
            result["is_extended"] = True
            result["label"]       = "Live"
        else:
            result["spot_ah"]     = reg

        if reg > 0:
            result["ah_chg_pct"] = (result["spot_ah"] - reg) / reg * 100
    except Exception:
        result["spot_ah"] = result["spot_reg"]
    return result

def _spot(ticker: str) -> float:
    """Live / after-hours price by DEFAULT; only returns the EOD close if the user explicitly
    turns the 'Live prices' toggle off (use_ah=False). Use this everywhere instead of _cached_price()."""
    if st.session_state.get("use_ah", True):
        d = _get_ah_price(ticker)
        return d["spot_ah"] if d["spot_ah"] > 0 else d["spot_reg"]
    return _cached_price(ticker)

# ═══════════════════════════════════════════════════════════════════
# ── MARKET WRAP — "what just happened" narrator (data-driven, offline)
#    Same engine as the Telegram bots. Only ever states numbers the system
#    actually computes — it never invents figures.
# ═══════════════════════════════════════════════════════════════════
_WRAP_IDX = [("^GSPC", "S&P 500", 52e12), ("^NDX", "Nasdaq 100", 32e12),
             ("^IXIC", "Nasdaq Comp", None), ("^DJI", "Dow", None), ("^RUT", "Russell 2000", None)]
_WRAP_CROSS = [("BTC-USD", "Bitcoin", "crypto"), ("ETH-USD", "Ethereum", "crypto"),
               ("GC=F", "Gold", "metal"), ("CL=F", "Crude oil", "energy"),
               ("DX-Y.NYB", "US Dollar", "fx"), ("^TNX", "10Y yield", "rates")]
_WRAP_LEV = [("TQQQ", "3x Nasdaq", 3), ("SOXL", "3x Semis", 3), ("SPXL", "3x S&P", 3),
             ("TSLL", "2x Tesla", 2), ("SOXS", "-3x Semis", -3), ("SQQQ", "-3x Nasdaq", -3)]


def _wrap_hist(sym, period="6d", interval="1d"):
    try:
        h = yf.Ticker(sym).history(period=period, interval=interval)
        return h if h is not None and not h.empty else None
    except Exception:
        return None


def _wrap_quote(sym):
    h = _wrap_hist(sym, "6d", "1d")
    if h is None or len(h) < 2:
        return None
    c = h["Close"].dropna()
    if len(c) < 2:
        return None
    last, prev = float(c.iloc[-1]), float(c.iloc[-2])
    if prev == 0:
        return None
    return {"last": last, "prev": prev, "pct": (last / prev - 1) * 100, "pts": last - prev}


def _wrap_intraday_shape(sym):
    h = _wrap_hist(sym, "1d", "5m")
    if h is None or len(h) < 3:
        return None
    highs = h["High"].cummax()
    dd = (h["Low"] - highs) / highs
    i_tr = dd.idxmin()
    i_pk = h.loc[:i_tr, "High"].idxmax()
    mins = max(int((i_tr - i_pk).total_seconds() // 60), 0)
    return {"open": float(h["Open"].iloc[0]), "cur": float(h["Close"].iloc[-1]),
            "hi": float(h["High"].max()), "lo": float(h["Low"].min()),
            "dd_pct": float(dd.min()) * 100, "dd_mins": mins,
            "peak": float(highs.loc[i_tr]), "trough": float(h["Low"].loc[i_tr]),
            "t_peak": i_pk, "t_trough": i_tr}


def _wrap_fmt_t(ts):
    try:
        return ts.strftime("%I:%M %p ET").lstrip("0")
    except Exception:
        return str(ts)


def _wrap_money(x):
    a = abs(x)
    if a >= 1e12:
        return f"${x/1e12:.2f}T"
    if a >= 1e9:
        return f"${x/1e9:.1f}B"
    if a >= 1e6:
        return f"${x/1e6:.0f}M"
    return f"${x:,.0f}"


def _wrap_pick(seed, opts):
    return opts[int(seed) % len(opts)]


_WRAP_BLS = {"CUUR0000SA0": "CPI", "CUUR0000SA0L1E": "Core CPI"}
_WRAP_MACRO_CACHE = {"ts": 0.0, "data": None}


def _wrap_macro():
    """Latest CPI / Core CPI YoY from the BLS public API (keyless, free, cached 6h).
    Returns {label: {yoy, month}} or None — the macro print line, no fabrication."""
    import time as _t, json as _json, urllib.request as _ur, datetime as _dtm
    now = _t.time()
    if _WRAP_MACRO_CACHE["data"] is not None and now - _WRAP_MACRO_CACHE["ts"] < 21600:
        return _WRAP_MACRO_CACHE["data"]
    try:
        yr = _dtm.datetime.now().year
        body = _json.dumps({"seriesid": list(_WRAP_BLS), "startyear": str(yr - 2),
                            "endyear": str(yr)}).encode()
        req = _ur.Request("https://api.bls.gov/publicAPI/v1/timeseries/data/", data=body,
                          headers={"Content-Type": "application/json", "User-Agent": "nyse-data/1.0"})
        j = _json.load(_ur.urlopen(req, timeout=15))
        out = {}
        for s in j.get("Results", {}).get("series", []):
            sid = s.get("seriesID")
            pts = []
            for d in s.get("data", []):
                if not str(d.get("period", "")).startswith("M"):
                    continue
                try:
                    pts.append((d["year"], d["period"], float(d["value"])))
                except Exception:
                    pass
            if len(pts) < 13:
                continue
            latest = pts[0]
            prior = next((p for p in pts if p[1] == latest[1] and int(p[0]) == int(latest[0]) - 1), None)
            if not prior or prior[2] == 0:
                continue
            mname = _dtm.date(2000, int(latest[1][1:]), 1).strftime("%b")
            out[_WRAP_BLS[sid]] = {"yoy": (latest[2] / prior[2] - 1) * 100, "month": f"{mname} {latest[0]}"}
        if out:  # only cache on success so transient failures retry next call
            _WRAP_MACRO_CACHE["ts"] = now
            _WRAP_MACRO_CACHE["data"] = out
        return out or None
    except Exception:
        return None


def _wrap_regime(F):
    """One-line macro regime: yield curve (2s10s) + Fed liquidity + inflation. Keyless."""
    import urllib.request as _u, json as _j, csv as _csv, io as _io, datetime as _dt
    bits = []
    try:
        yr = _dt.datetime.now().year
        url = (f"https://home.treasury.gov/resource-center/data-chart-center/interest-rates/"
               f"daily-treasury-rates.csv/{yr}/all?type=daily_treasury_yield_curve&field_tdr_date_value={yr}&page&_format=csv")
        rows = list(_csv.DictReader(_io.StringIO(_u.urlopen(_u.Request(url, headers={"User-Agent": "Mozilla/5.0"}),
                                                            timeout=12).read().decode("utf-8", "ignore"))))
        if rows:
            s2 = (float(rows[0]["10 Yr"]) - float(rows[0]["2 Yr"])) * 100
            bits.append("curve " + ("inverted 🔴" if s2 < 0 else "flat 🟡" if s2 < 25 else "steep 🟢") + f" (2s10s {s2:+.0f}bp)")
    except Exception:
        pass
    try:
        s = _j.loads(_u.urlopen(_u.Request("https://markets.newyorkfed.org/api/soma/summary.json",
                                           headers={"User-Agent": "nyse-data/1.0"}), timeout=12).read().decode())
        rws = s["soma"]["summary"]
        chg = float(rws[-1]["total"]) - float(rws[-14]["total"]) if len(rws) > 14 else 0
        bits.append("Fed " + ("adding liquidity 🟢" if chg > 25e9 else "in QT 🔴" if chg < -50e9 else "on hold 🟡"))
    except Exception:
        pass
    m = F.get("macro") or {}
    if "CPI" in m:
        bits.append(f"CPI {m['CPI']['yoy']:.1f}% YoY")
    return " · ".join(bits) if bits else None


def wrap_facts(conn, universe_cap=120):
    F = {"ts": datetime.now(), "indices": [], "lead": None, "shape": None,
         "vix": None, "cross": [], "lev": [], "movers_up": [], "movers_dn": [],
         "breadth": None, "options": None, "book": None, "catalyst": None, "macro": None, "regime": None}

    for sym, name, cap in _WRAP_IDX:
        q = _wrap_quote(sym)
        if not q:
            continue
        d = {"sym": sym, "name": name, "cap": cap, **q}
        if cap:
            d["dollars"] = cap * (q["pct"] / 100.0)
        F["indices"].append(d)
    if F["indices"]:
        F["lead"] = max(F["indices"], key=lambda d: abs(d["pct"]))
        F["shape"] = _wrap_intraday_shape(F["lead"]["sym"])

    vq = _wrap_quote("^VIX")
    if vq:
        F["vix"] = vq

    F["macro"] = _wrap_macro()
    F["regime"] = _wrap_regime(F)

    for sym, name, kind in _WRAP_CROSS:
        q = _wrap_quote(sym)
        if q:
            F["cross"].append({"name": name, "kind": kind, **q})

    for sym, name, mult in _WRAP_LEV:
        q = _wrap_quote(sym)
        if q:
            F["lev"].append({"sym": sym, "name": name, "mult": mult, **q})

    try:
        tks = [r[0] for r in conn.execute("SELECT DISTINCT ticker FROM stock_daily").fetchall()][:universe_cap]
    except Exception:
        tks = []
    rows = []
    if tks:
        try:
            data = yf.download(tks, period="6d", interval="1d", group_by="ticker",
                               threads=True, progress=False)
            for t in tks:
                try:
                    c = data[t]["Close"].dropna() if len(tks) > 1 else data["Close"].dropna()
                    if len(c) >= 2 and float(c.iloc[-2]) > 0:
                        rows.append({"t": t, "pct": (float(c.iloc[-1]) / float(c.iloc[-2]) - 1) * 100,
                                     "last": float(c.iloc[-1])})
                except Exception:
                    continue
        except Exception:
            rows = []
    if not rows:
        sk = "trade_date"
        for t in tks:
            try:
                c = pd.read_sql(f"SELECT close FROM stock_daily WHERE ticker=? ORDER BY {sk} DESC LIMIT 2",
                                conn, params=(t,))
                v = pd.to_numeric(c["close"], errors="coerce").dropna().tolist()
                if len(v) >= 2 and v[1] > 0:
                    rows.append({"t": t, "pct": (v[0] / v[1] - 1) * 100, "last": v[0]})
            except Exception:
                continue
    if rows:
        up = sum(1 for r in rows if r["pct"] > 0); dn = sum(1 for r in rows if r["pct"] < 0)
        F["breadth"] = {"up": up, "dn": dn, "n": len(rows)}
        rows.sort(key=lambda r: r["pct"])
        F["movers_dn"] = rows[:5]
        F["movers_up"] = rows[-5:][::-1]

    cand = None
    if F["movers_dn"] or F["movers_up"]:
        cand = max(F["movers_dn"] + F["movers_up"], key=lambda r: abs(r["pct"]))["t"]
    if cand:
        try:
            for n in (yf.Ticker(cand).news or []):
                title = (n.get("content", {}) or {}).get("title") or n.get("title")
                if title:
                    F["catalyst"] = {"ticker": cand, "title": title}
                    break
        except Exception:
            pass

    try:
        _dts = available_trade_dates()
        d0 = _dts[0] if _dts else None
        if d0:
            summ = load_ticker_summary(d0)   # serving layer: ~15ms vs a live GROUP BY scan
            agg = (summ.rename(columns={"call_oi_chg": "cc", "put_oi_chg": "cp",
                                        "call_oi": "oc", "put_oi": "op"})
                   if not summ.empty else summ)
            if not agg.empty:
                agg = agg[~agg["ticker"].astype(str).str.startswith("^")]
                tc = float(agg["cc"].sum()); tp = float(agg["cp"].sum())
                oc = float(agg["oc"].sum()); op = float(agg["op"].sum())
                agg["net"] = agg["cp"].fillna(0) - agg["cc"].fillna(0)
                put_heavy = agg.reindex(agg["net"].sort_values(ascending=False).index).head(3)
                F["options"] = {"date": d0, "call_chg": tc, "put_chg": tp,
                                "pcr": (op / oc) if oc else None,
                                "put_heavy": list(put_heavy["ticker"])}
    except Exception:
        pass

    try:
        tr = pd.read_sql("SELECT ticker,option_type,quantity FROM trades WHERE status='OPEN'", conn)
        if not tr.empty:
            mv = {r["t"]: r["pct"] for r in rows}
            bt = {}
            for _, t in tr.iterrows():
                tk = str(t["ticker"]).upper()
                pc = mv.get(tk)
                if pc is None:
                    q = _wrap_quote(tk); pc = q["pct"] if q else 0.0
                typ = "call" if str(t["option_type"]).lower().startswith("c") else "put"
                qty = int(t["quantity"] or 0)
                bt.setdefault(tk, {"pct": pc, "dir": 0})
                bt[tk]["dir"] += (1 if (typ == "call") == (qty > 0) else -1)
            F["book"] = {"tickers": [{"tk": k, "pct": v["pct"], "dir": v["dir"]} for k, v in bt.items()]}
    except Exception:
        pass

    return F


def wrap_narrative(F, html=False):
    b = (lambda s: f"<b>{s}</b>") if html else (lambda s: f"**{s}**")
    esc = (lambda s: str(s).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")) if html else (lambda s: s)
    L = []
    lead = F["lead"]; shape = F["shape"]
    seed = int(F["ts"].strftime("%Y%m%d"))

    if lead:
        d = lead["pct"]
        big_swing = bool(shape and abs(shape["dd_pct"]) >= 1.2 and shape["dd_mins"] > 0)
        if big_swing:
            op = (shape["open"] / lead["prev"] - 1) * 100
            dollar = f" — an estimated {_wrap_money(abs(lead['dollars']))} in value" if lead.get("dollars") else ""
            hooks = [
                f"In just {shape['dd_mins']} minutes, the {lead['name']} cratered {shape['dd_pct']:.1f}% from its "
                f"intraday peak{dollar}. It opened {op:+.1f}% and is now {d:+.1f}% — a violent round trip on the day.",
                f"A textbook volatility shock: the {lead['name']} ran to {op:+.1f}% at the open, then dumped "
                f"{shape['dd_pct']:.1f}% in {shape['dd_mins']} minutes{dollar}, settling {d:+.1f}% on the day."]
            L.append("⚡ " + b("WHAT JUST HAPPENED") + "\n\n" + _wrap_pick(seed, hooks))
        elif lead.get("dollars"):
            verb = "erased" if d < 0 else "added"
            hooks = [
                f"The {lead['name']} {verb} an estimated {_wrap_money(abs(lead['dollars']))} in market value today, "
                f"moving {d:+.1f}% ({lead['pts']:+,.0f} pts).",
                f"An estimated {_wrap_money(abs(lead['dollars']))} {('vanished from' if d<0 else 'flowed into')} the "
                f"{lead['name']} today as it moved {d:+.1f}% ({lead['pts']:+,.0f} pts)."]
            L.append("⚡ " + b("WHAT JUST HAPPENED") + "\n\n" + _wrap_pick(seed, hooks))
        else:
            risk = "sell-off" if d < 0 else "rally"
            L.append("⚡ " + b("WHAT JUST HAPPENED") + "\n\n"
                     f"The {lead['name']} is {('down' if d<0 else 'up')} {abs(d):.1f}% "
                     f"({lead['pts']:+,.0f} pts) in a session {risk}.")

    if shape and lead:
        op = (shape["open"] / lead["prev"] - 1) * 100
        L.append("🕘 " + b("THE TIMELINE") + "\n\n"
                 f"The {lead['name']} opened {op:+.1f}% vs the prior close, peaked near {shape['peak']:,.0f} at "
                 f"{_wrap_fmt_t(shape['t_peak'])}, then slid to {shape['trough']:,.0f} by {_wrap_fmt_t(shape['t_trough'])} "
                 f"({shape['dd_pct']:+.1f}%). It now trades at {shape['cur']:,.0f}.")

    if F["catalyst"]:
        big = next((m for m in (F["movers_dn"] + F["movers_up"]) if m["t"] == F["catalyst"]["ticker"]), None)
        if big:
            line = (f"{big['t']} moved {big['pct']:+.1f}% — the session's standout — on the headline: "
                    f"“{esc(F['catalyst']['title'])}”.")
        else:
            line = f"A key catalyst: {F['catalyst']['ticker']} — “{esc(F['catalyst']['title'])}”."
        L.append("📰 " + b("THE CATALYST") + "\n\n" + line)

    if F["vix"]:
        v = F["vix"]
        tone = "spiking — fear is back" if v["pct"] > 8 else "rising" if v["pct"] > 0 else "easing"
        L.append("🌪 " + b("VOLATILITY") + "\n\n"
                 f"The VIX is at {v['last']:.1f} ({v['pct']:+.1f}%), {tone}. "
                 + ("Above 20 signals real stress." if v["last"] >= 20 else "Still contained below 20."))

    if F.get("macro"):
        m = F["macro"]
        bits = [f"{k} {m[k]['yoy']:.1f}% YoY ({m[k]['month']})" for k in ("CPI", "Core CPI") if k in m]
        if bits:
            hot = m.get("CPI", {}).get("yoy", 0)
            vs = "well above" if hot >= 3 else "above" if hot > 2.3 else "near"
            L.append("📅 " + b("MACRO BACKDROP") + "\n\n"
                     f"Inflation backdrop: {', '.join(bits)} — {vs} the Fed's 2% target.")

    if F.get("regime"):
        L.append("🧭 " + b("MACRO REGIME") + "\n\n" + F["regime"] + ".")

    if F["cross"]:
        parts = []
        for c in F["cross"]:
            if c["kind"] == "rates":
                parts.append(f"the 10Y yield {('rose' if c['pct']>0 else 'fell')} to {c['last']:.2f}%")
            else:
                parts.append(f"{c['name']} {c['pct']:+.1f}%")
        L.append("🌐 " + b("CROSS-ASSET") + "\n\nContagion check — " + "; ".join(parts) + ".")

    lev_lines = []
    if F["lev"]:
        worst = max(F["lev"], key=lambda x: abs(x["pct"]))
        lev_lines.append(f"Leveraged ETFs are amplifying the move: {worst['name']} ({worst['sym']}) "
                         f"{worst['pct']:+.1f}%. 3x funds magnify every swing — and the crowd is in them.")
    if F["options"]:
        o = F["options"]
        flow = ("put-heavy (hedging/bearish)" if (o["put_chg"] or 0) > (o["call_chg"] or 0)
                else "call-heavy (bullish/chasing)")
        pcr = f", market PCR {o['pcr']:.2f}" if o.get("pcr") else ""
        ph = ", ".join(o["put_heavy"]) if o.get("put_heavy") else "—"
        lev_lines.append(f"Options flow is {flow}: net ΔOI calls {o['call_chg']:+,.0f} / puts {o['put_chg']:+,.0f}{pcr}. "
                         f"Heaviest put builds: {ph}.")
    if lev_lines:
        L.append("🎰 " + b("LEVERAGE & POSITIONING") + "\n\n" + " ".join(lev_lines))

    if F["breadth"]:
        br = F["breadth"]
        tilt = "risk-off" if br["dn"] > br["up"] else "risk-on" if br["up"] > br["dn"] else "mixed"
        ups = ", ".join(f"{m['t']} {m['pct']:+.1f}%" for m in F["movers_up"][:3])
        dns = ", ".join(f"{m['t']} {m['pct']:+.1f}%" for m in F["movers_dn"][:3])
        L.append("📊 " + b("BREADTH & MOVERS") + "\n\n"
                 f"{br['up']}/{br['n']} names green, {br['dn']} red — a {tilt} tape. "
                 f"Leaders: {ups}. Laggards: {dns}.")

    if F["book"] and F["book"]["tickers"]:
        bl = []
        helped_n = 0
        for t in F["book"]["tickers"]:
            helped = (t["pct"] > 0) == (t["dir"] >= 0)
            helped_n += helped
            bl.append(f"{t['tk']} {t['pct']:+.1f}% ({'tailwind' if helped else 'headwind'})")
        L.append("💼 " + b("YOUR BOOK") + "\n\n"
                 f"Your open names today: {', '.join(bl)}. Net directional exposure is being "
                 + ("helped" if helped_n >= len(F["book"]["tickers"]) / 2 else "pressured") + " by the move.")

    closers = ["Volatility always comes with change.",
               "Record leverage + rising uncertainty = swings are here to stay.",
               "When everyone is positioned one way, the exit gets narrow.",
               "Opportunity lives in the broadening swings — if you respect the risk."]
    L.append("— *" + _wrap_pick(seed + 2, closers) + "*")
    return "\n\n".join(L)


@st.cache_data(ttl=60, show_spinner=False)
def _wrap_facts_cached(nonce=0):
    # `nonce` is intentionally hashed (no leading underscore) so the Refresh
    # button can bust the 60s cache on demand.
    conn = get_conn()
    try:
        return wrap_facts(conn)
    finally:
        conn.close()


def _market_state():
    """US market session by Eastern time: 'OPEN' (RTH), 'PRE', 'AFTER', or 'CLOSED'."""
    try:
        from zoneinfo import ZoneInfo
        now = datetime.now(ZoneInfo("America/New_York"))
    except Exception:
        return "UNKNOWN"
    if now.weekday() >= 5:
        return "CLOSED"
    t = now.hour * 60 + now.minute
    if 4 * 60 <= t < 9 * 60 + 30:
        return "PRE"
    if 9 * 60 + 30 <= t < 16 * 60:
        return "OPEN"
    if 16 * 60 <= t < 20 * 60:
        return "AFTER"
    return "CLOSED"


def _ah_quote(info=None, fast_info=None, spot=None, session=None):
    """THE extended-hours resolver (ID 278). Returns dict:
        {price, chg_pct, source, session, label}  -- price/chg_pct None when there is none.

    One place for this, because each card was deciding for itself and getting it wrong.

    THE BUG THIS REPLACES: the exit planner only accepted an after-hours price when it
    differed from the regular close by more than **$0.50 absolute**. GOOGL closed 340.67 and
    traded 340.94 after the bell -- a real 27-cent move -- so the quote was discarded and the
    card printed "N/A / Market open" while the market was shut. An absolute cut-off is also
    scale-blind: $0.50 is 0.15% of a $340 stock and 2.5% of a $20 one.

    Yahoo only populates postMarketPrice/preMarketPrice when that session actually traded, so
    presence IS the signal. The only thing worth filtering is a literal echo of the close,
    which a tiny relative epsilon catches without discarding genuine small moves.

    `label` is derived from the REAL session (`_market_state`), never hardcoded -- the old
    card said "Market open" whenever the price was missing, which was the one time it was
    most likely to be false.
    """
    EPS_PCT = 0.02          # 0.02% -> a literal echo of the close, not a move
    sess = session or _market_state()
    out = {"price": None, "chg_pct": None, "source": "", "session": sess,
           "label": {"OPEN": "Market open", "PRE": "Pre-market",
                     "AFTER": "After-hours", "CLOSED": "Market closed"}.get(sess, "—")}
    try:
        spot = float(spot or 0)
    except (TypeError, ValueError):
        spot = 0.0
    if spot <= 0:
        return out

    def _take(px, src):
        try:
            px = float(px or 0)
        except (TypeError, ValueError):
            return False
        if px <= 0 or abs(px - spot) / spot * 100 < EPS_PCT:
            return False
        out["price"], out["source"] = px, src
        out["chg_pct"] = (px - spot) / spot * 100
        return True

    info = info or {}
    # Prefer the session we are actually IN, rather than always preferring pre-market.
    order = ([("preMarketPrice", "Pre-Market"), ("postMarketPrice", "After-Hours")]
             if sess == "PRE" else
             [("postMarketPrice", "After-Hours"), ("preMarketPrice", "Pre-Market")])
    for k, src in order:
        if _take(info.get(k), src):
            return out
    if fast_info is not None:
        _take(getattr(fast_info, "last_price", 0), "Last Tick")
    return out


@st.fragment(run_every=5)
def _gp_live_strip():
    """THE live-values block — a RENDERING fragment, which is what makes the page behave like a
    broker screen instead of freezing.

    Why this exists (profiled 2026-07-22): the old design used a heartbeat fragment that called
    `st.rerun(scope="app")`. That is a FULL SCRIPT rerun — it re-executes this entire ~20k-line
    module: every DB read, every yfinance call, every table rebuild. The positions card alone
    measured 14s. So "refresh" meant a multi-second freeze, which is exactly the symptom.

    A fragment that RENDERS instead only re-executes itself and patches its own DOM subtree.
    The numbers tick, nothing else on the page moves, scroll position is kept, and no heavy
    work is repeated. That is the broker feel: quotes update, the page does not reload.
    """
    if not st.session_state.get("use_ah", True):
        return                                    # EOD / frozen mode — nothing live to show
    _tks = st.session_state.get("_live_tickers") or []
    if not _tks:
        return
    _prev = st.session_state.get("_live_last_px") or {}
    _now = {}
    _cols = st.columns(min(len(_tks), 6))
    for _i, _tk in enumerate(_tks[:6]):
        try:
            _d = _get_ah_price(_tk) or {}
            # contract: spot_reg = confirmed EOD close, spot_ah = extended-hours print,
            # ah_chg_pct = AH move vs that close. There is NO prev_close key.
            _base = float(_d.get("spot_reg") or 0.0)
            _px = float(_d.get("spot_ah") or 0.0) or _base
        except Exception:
            continue
        if _px <= 0:
            continue
        _now[_tk] = _px
        _chg = (_px - _base) if (_base > 0 and abs(_px - _base) > 1e-9) else None
        _pct = float(_d.get("ah_chg_pct") or 0.0) or (
            (_chg / _base * 100.0) if (_chg is not None and _base > 0) else None)
        # delta vs the LAST TICK, so you can see which quote just moved
        _tick = _px - float(_prev.get(_tk, _px))
        # Ticker FIRST, then a tick glyph (user 2026-08-12: the strip read "up GOOG" —
        # the placeholder words "up"/"dn"/"flat" were shipping as the visible label, which
        # also buried the identity of the quote behind a direction word).
        _arrow = "▲" if _tick > 0 else ("▼" if _tick < 0 else "")
        _cols[_i].metric(f"{_tk} {_arrow}".strip(), f"${_px:,.2f}",
                         (f"{_chg:+.2f} ({_pct:+.2f}%)" if _pct is not None else None))
    st.session_state["_live_last_px"] = _now
    st.caption(f"live · {datetime.now().strftime('%H:%M:%S')} — quotes update in place; "
               "tables below refresh on the slower interval")


@st.fragment(run_every=5)
def _gp_live_tick():
    """Slow heartbeat for the HEAVY page content only.

    Live quotes are handled by `_gp_live_strip` above without touching the rest of the page.
    A full-app rerun is only worth its cost for the expensive tables/analysis, so this now
    fires on a much longer cadence (>=5x the quote interval, floor 5 min) instead of on every
    price move. Previously any tick past the interval triggered a whole-script rerun, which
    is what made the page freeze.
    """
    import time as _t
    if not st.session_state.get("use_ah", True):
        return
    interval = int(st.session_state.get("global_refresh_int",
                                        st.session_state.get("gp_refresh_int", 60)))
    heavy = max(interval * 5, 300)               # heavy refresh cadence, never tighter than 5 min
    if _t.time() - st.session_state.get("_app_run_ts", 0.0) < heavy:
        return
    _tks = st.session_state.get("_live_tickers") or []
    if _tks:
        try:
            _sig = tuple((_t2, round(float((_get_ah_price(_t2) or {}).get("spot_ah")
                                           or (_get_ah_price(_t2) or {}).get("spot_reg") or 0.0), 2))
                         for _t2 in _tks)
        except Exception:
            _sig = None
        if _sig is not None:
            if _sig == st.session_state.get("_live_sig_live"):
                st.session_state["_app_run_ts"] = _t.time()   # unchanged → skip the rerun
                return
            st.session_state["_live_sig_live"] = _sig
    st.rerun(scope="app")


def _auto_refresh(seconds: int):
    """Arm the in-place live refresh: records this run's timestamp and renders the heartbeat
    fragment. The fragment quietly checks the clock every 5s and reruns the app only when the
    interval elapses (so no tight loop on first render)."""
    import time as _t
    st.session_state["_app_run_ts"] = _t.time()
    try:
        _gp_live_tick()
    except Exception:
        pass


def _spot_label(ticker: str) -> str:
    """Short label showing EOD and AH price, e.g. 'EOD $248.50 → AH $251.20 (+1.1%)'."""
    d = _get_ah_price(ticker)
    reg = d["spot_reg"]
    ah  = d["spot_ah"]
    chg = d["ah_chg_pct"]
    lbl = d["label"]
    if d["is_extended"]:
        return f"EOD ${reg:.2f}  →  {lbl} <b>${ah:.2f}</b> ({chg:+.1f}%)"
    return f"EOD ${reg:.2f}"

@st.cache_data(ttl=120, show_spinner=False)
def _cached_trades(status: str = None):
    """Load trades from DB — cached 30 s."""
    sql = "SELECT * FROM trades" + (" WHERE status=?" if status else "")
    params = [status] if status else []
    return q(sql, params)

@st.cache_data(ttl=3600, show_spinner=False)
def _iv_rank_pct(ticker: str):
    """52-week IV rank and IV percentile using 20-day HV as IV proxy. Returns (rank, pct, cur_hv)."""
    try:
        h = yf.Ticker(ticker).history(period="1y")
        if len(h) < 60:
            return None, None, None
        lr = np.log(h["Close"] / h["Close"].shift(1)).dropna()
        hv = lr.rolling(20).std() * np.sqrt(252)
        cur = float(hv.iloc[-1]) if not np.isnan(hv.iloc[-1]) else None
        if cur is None:
            return None, None, None
        hv_clean = hv.dropna()
        mn, mx = float(hv_clean.min()), float(hv_clean.max())
        rank = round((cur - mn) / (mx - mn) * 100, 1) if mx > mn else 50.0
        pct  = round(float((hv_clean <= cur).sum() / len(hv_clean) * 100), 1)
        return rank, pct, round(cur * 100, 1)
    except Exception:
        return None, None, None

@st.cache_data(ttl=3600, show_spinner=False)
def _days_to_earnings(ticker: str):
    """Days to next earnings. Returns int or None."""
    try:
        cal = yf.Ticker(ticker).calendar
        if cal is None:
            return None
        if isinstance(cal, dict):
            ed = cal.get("Earnings Date")
            if ed:
                ed = pd.to_datetime(ed[0] if isinstance(ed, list) else ed)
                days = (ed.date() - datetime.now().date()).days
                return days if days >= 0 else None
        elif hasattr(cal, "loc") and "Earnings Date" in cal.index:
            ed = pd.to_datetime(cal.loc["Earnings Date"].iloc[0])
            days = (ed.date() - datetime.now().date()).days
            return days if days >= 0 else None
    except Exception:
        pass
    return None

@st.cache_data(ttl=14400, show_spinner=False)
def _get_short_data_dash(ticker: str) -> dict:
    """Fetch short interest & float from yfinance info. Cached 4h."""
    empty = {"float_shares": None, "shares_short": None, "short_pct_float": None,
             "short_ratio": None, "shares_short_prior": None,
             "shares_outstanding": None, "squeeze_score": 0, "squeeze_label": "N/A"}
    try:
        info = yf.Ticker(ticker).info
        float_s  = info.get("floatShares")
        ss       = info.get("sharesShort")
        spf      = info.get("shortPercentOfFloat")
        sr       = info.get("shortRatio")
        ss_prior = info.get("sharesShortPriorMonth")
        sout     = info.get("sharesOutstanding")
        if spf and spf < 1:
            spf = spf * 100
        if spf is None and float_s and ss:
            spf = ss / float_s * 100
        score = 0
        if spf:
            if spf >= 30: score += 4
            elif spf >= 20: score += 3
            elif spf >= 10: score += 2
            elif spf >= 5: score += 1
        if sr:
            if sr >= 10: score += 3
            elif sr >= 5: score += 2
            elif sr >= 3: score += 1
        if ss and ss_prior and ss > ss_prior * 1.10: score += 2
        elif ss and ss_prior and ss < ss_prior * 0.90: score -= 1
        score = max(0, min(10, score))
        return {
            "float_shares": float_s, "shares_short": ss,
            "short_pct_float": spf, "short_ratio": sr,
            "shares_short_prior": ss_prior, "shares_outstanding": sout,
            "squeeze_score": score,
            "squeeze_label": "HIGH SQUEEZE RISK" if score >= 7 else ("MODERATE" if score >= 4 else "LOW"),
        }
    except Exception:
        return empty


def _roll_suggestion(leg: dict, spot: float) -> str:
    """Generate a specific roll recommendation for a losing/expiring leg."""
    dte = leg.get("DTE", 99)
    pnl_pct = leg.get("PnL%", 0)
    opt_type = leg.get("Type", "CALL")
    strike = leg.get("Strike", 0)
    qty = leg.get("Qty", 1)
    side = "BUY" if qty > 0 else "SELL"

    if dte > 21 and pnl_pct > -30:
        return ""  # No roll needed yet

    today = datetime.now().date()
    # Target roll: next monthly expiry 30-45 days out
    roll_dte = 35
    target_month = today + timedelta(days=roll_dte)
    # Find 3rd Friday of that month
    first_day = target_month.replace(day=1)
    fridays = [first_day + timedelta(days=d) for d in range(31) if (first_day + timedelta(days=d)).weekday() == 4]
    roll_exp = fridays[2].strftime("%Y-%m-%d") if len(fridays) >= 3 else target_month.strftime("%Y-%m-%d")

    # Suggest roll strike: ATM for losing positions, same strike for mild loss
    if pnl_pct < -40:
        roll_strike = round(spot / 5) * 5  # Round to nearest $5 = ATM
        reason = "roll to ATM (stop digging deeper)"
    elif pnl_pct < -20:
        roll_strike = strike
        reason = "roll same strike, extend time"
    else:
        roll_strike = strike
        reason = "roll before theta accelerates"

    action = "ROLL" if side == "BUY" else "ROLL SHORT"
    return (f"🔄 {action} suggestion: Close {side} {opt_type} ${strike:.0f} exp now → "
            f"Open {side} {opt_type} ${roll_strike:.0f} exp ~{roll_exp} ({reason})")

