@st.cache_data(ttl=60)          # 300s made the 60s auto-refresh show stale quotes 4/5 times
def fetch_market_snapshot():
    rows = []
    tickers_str = " ".join(GLOBAL_SYMBOLS.values())
    try:
        data = yf.download(tickers_str, period="5d", group_by="ticker", progress=False, threads=True)
    except Exception:
        data = pd.DataFrame()
    # Live layer: last 1-minute bar (incl. pre/post). Daily bars lag the live tick by
    # minutes during trading, which is why cards drifted from Google's live quotes.
    try:
        live = yf.download(tickers_str, period="1d", interval="1m", prepost=True,
                           group_by="ticker", progress=False, threads=True)
    except Exception:
        live = pd.DataFrame()
    for name, sym in GLOBAL_SYMBOLS.items():
        try:
            hist = pd.DataFrame()
            # Try bulk data first
            if not data.empty and sym in data.columns.get_level_values(0):
                sub = data[sym]["Close"].dropna()
                if len(sub) >= 2:
                    hist = data[sym].loc[sub.index]
            # Fallback to individual fetch
            if hist.empty or len(hist) < 2:
                t = yf.Ticker(sym)
                hist = t.history(period="5d")
            if len(hist) >= 2:
                close_col = hist["Close"].dropna()
                if len(close_col) < 2:
                    continue
                cur = float(close_col.iloc[-1])
                prev = float(close_col.iloc[-2])
                # overlay the fresher 1-minute price when available
                try:
                    if not live.empty and sym in live.columns.get_level_values(0):
                        lc = live[sym]["Close"].dropna()
                        if len(lc) and float(lc.iloc[-1]) > 0:
                            # if the live bar is a NEWER session than the last daily bar
                            # (e.g. pre-market), yesterday's close is the daily LAST bar
                            if lc.index[-1].date() > close_col.index[-1].date():
                                prev = float(close_col.iloc[-1])
                            cur = float(lc.iloc[-1])
                except Exception:
                    pass
                chg = cur - prev
                pct = chg / prev * 100 if prev else 0
                rows.append(dict(Name=name, Symbol=sym, Price=cur, Change=chg, Pct=pct))
        except Exception:
            pass
    result = pd.DataFrame(rows)
    # Persist to DB for historical charts
    if not result.empty:
        _save_market_snapshot(result)
    return result


# ===================================================================
# ──  OI  HELPERS
# ===================================================================
def _sort_dates_chrono(dates_list, descending=True):
    """Sort MM-DD-YYYY date strings chronologically."""
    parsed = []
    for d in dates_list:
        try:
            parsed.append((d, pd.to_datetime(d, format="%Y-%m-%d")))
        except Exception:
            pass
    parsed.sort(key=lambda x: x[1], reverse=descending)
    return [p[0] for p in parsed]


@st.cache_data(ttl=3600, show_spinner=False)
def available_trade_dates():
    raw = q("SELECT DISTINCT trade_date_now FROM options_change")["trade_date_now"].tolist()
    return _sort_dates_chrono(raw, descending=True)


@st.cache_data(ttl=1800, show_spinner=False)
def load_oi_for_date(td):
    return q("SELECT * FROM options_change WHERE trade_date_now=?", [td])


@st.cache_data(ttl=1800, show_spinner=False)
def load_oi_for_ticker_date(ticker, td):
    """One ticker's option chain for a date (~1ms, uses the ticker index) — for pages that only
    need a single selected ticker, instead of scanning the whole ~150k-row date snapshot."""
    return q("SELECT * FROM options_change WHERE ticker=? AND trade_date_now=?", [str(ticker).upper(), td])


# ── TIER 3: RAM-resident serving layer (shared across sessions/reruns, ~µs reads) ──
@st.cache_resource(ttl=1800, show_spinner=False)
def _serving_ram():
    """The whole `daily_ticker_summary` held ONCE in process RAM, shared across every session and
    rerun (no per-call DB read). {trade_date: DataFrame}. READ-ONLY — callers .copy() before
    mutating. Refreshes every 30 min (nightly rebuild appears on the next refresh)."""
    try:
        df = q("SELECT * FROM daily_ticker_summary")
    except Exception:
        return {}
    if df.empty:
        return {}
    return {d: g.reset_index(drop=True) for d, g in df.groupby("trade_date")}


@st.cache_resource(ttl=1800, show_spinner=False)
def _serving_index():
    """{trade_date: {TICKER: metrics-dict}} for O(1) per-ticker lookups (instant, no filtering)."""
    return {d: {str(r["ticker"]).upper(): r.to_dict() for _, r in df.iterrows()}
            for d, df in _serving_ram().items()}


def ticker_metrics(ticker, td):
    """Instant per-ticker summary dict from RAM (O(1)), or None."""
    return _serving_index().get(td, {}).get(str(ticker).upper())


def tickers_for_date(td):
    """Ticker list for a date — instant from the RAM serving layer, else DISTINCT scan."""
    ram = _serving_ram().get(td)
    if ram is not None and not ram.empty:
        return ram["ticker"].astype(str).tolist()
    d = q("SELECT DISTINCT ticker FROM options_change WHERE trade_date_now=? ORDER BY ticker", [td])
    return d["ticker"].astype(str).tolist() if not d.empty else []


def load_ticker_summary(td=None):
    """SERVING LAYER (Tier 3, RAM-resident): per-ticker daily aggregates in ~microseconds from the
    shared in-RAM store; falls back to a live GROUP BY if the table is absent (Yahoo DB / pre-build)."""
    if td is None:
        _d = available_trade_dates()
        td = _d[0] if _d else None
    if not td:
        return pd.DataFrame()
    ram = _serving_ram().get(td)
    if ram is not None and not ram.empty:
        return ram.copy()                                # copy so callers may mutate safely
    df = q("""SELECT UPPER(ticker) ticker, COUNT(*) n_strikes,
        SUM(COALESCE(openInt_Call_now,0)) call_oi, SUM(COALESCE(openInt_Put_now,0)) put_oi,
        SUM(COALESCE(change_OI_Call,0)) call_oi_chg, SUM(COALESCE(change_OI_Put,0)) put_oi_chg,
        SUM(COALESCE(vol_Call_now,0)) call_vol, SUM(COALESCE(vol_Put_now,0)) put_vol,
        SUM(COALESCE(lastPrice_Call_now,0)*COALESCE(openInt_Call_now,0)*100) call_notional,
        SUM(COALESCE(lastPrice_Put_now,0)*COALESCE(openInt_Put_now,0)*100) put_notional
        FROM options_change WHERE trade_date_now=? GROUP BY UPPER(ticker)""", [td])
    if not df.empty:
        df["pcr_oi"] = df.put_oi / df.call_oi.replace(0, pd.NA)
        df["net_oi_chg"] = df.call_oi_chg - df.put_oi_chg
    return df


# ── SCAN-UNIVERSE FILTERS (OI floor = instant; beta / market-cap = fundamentals) ──
@st.cache_data(ttl=3600, show_spinner=False)
def load_fundamentals_flat():
    """Flat (ticker, beta, mcap, sector) for the beta / market-cap sliders. Prefers the nightly
    `daily_fundamentals` table (fast, whole liquid universe); falls back to `fundamentals_cache`
    (JSON, from Anti-Bubble / the manual button). Unknown tickers pass the filters by default."""
    try:                                             # nightly flat table (instant, full universe)
        flat = q("SELECT ticker, beta, market_cap AS mcap, sector FROM daily_fundamentals")
        if not flat.empty:
            flat["ticker"] = flat["ticker"].astype(str).str.upper()
            return flat
    except Exception:
        pass
    import json as _json                             # fallback: JSON cache
    try:
        raw = q("SELECT ticker, data FROM fundamentals_cache")
    except Exception:
        return pd.DataFrame(columns=["ticker", "beta", "mcap", "sector"])
    rows = []
    for _, r in raw.iterrows():
        try:
            d = _json.loads(r["data"])
            rows.append({"ticker": str(r["ticker"]).upper(), "beta": d.get("beta"),
                         "mcap": d.get("mcap"), "sector": d.get("sector")})
        except Exception:
            pass
    return pd.DataFrame(rows) if rows else pd.DataFrame(columns=["ticker", "beta", "mcap", "sector"])


@st.cache_data(ttl=600, show_spinner=False)
def get_scan_universe(min_oi=10000, beta_lo=0.0, beta_hi=3.0, min_mcap_b=0.0, td=None):
    """Filtered scan universe: OI floor (serving layer, instant) + optional beta / market-cap
    (fundamentals; tickers without fundamentals are kept so the filter never empties the list)."""
    if td is None:
        _d = available_trade_dates()
        td = _d[0] if _d else None
    sm = load_ticker_summary(td)
    if sm.empty:
        return []
    sm = sm.copy()
    sm["_toi"] = sm["call_oi"].fillna(0) + sm["put_oi"].fillna(0)
    tks = set(sm[sm["_toi"] >= min_oi]["ticker"].astype(str).str.upper())
    if beta_lo > 0.0 or beta_hi < 3.0 or min_mcap_b > 0.0:      # a fundamentals filter is active
        f = load_fundamentals_flat()
        if not f.empty:
            known = set(f["ticker"])
            keep = set()
            for _, r in f.iterrows():
                if r["ticker"] not in tks:
                    continue
                ok = True
                if (beta_lo > 0.0 or beta_hi < 3.0) and pd.notna(r["beta"]):
                    ok = ok and (beta_lo <= float(r["beta"]) <= beta_hi)
                if min_mcap_b > 0.0 and pd.notna(r["mcap"]):
                    ok = ok and (float(r["mcap"]) >= min_mcap_b * 1e9)
                if ok:
                    keep.add(r["ticker"])
            tks = (tks & keep) | (tks - known)                 # known-pass ∪ unknown (kept)
    return sorted(tks)


def _ensure_fundamentals_for_universe(min_oi):
    """Fetch+cache fundamentals for the OI universe (slow first time; then daily-cached)."""
    import telegram_bot_optimized as _tb
    conn = get_conn()
    try:
        sm = load_ticker_summary()
        if sm.empty:
            return 0
        sm = sm.copy()
        sm["_toi"] = sm["call_oi"].fillna(0) + sm["put_oi"].fillna(0)
        tks = sm[sm["_toi"] >= min_oi]["ticker"].astype(str).str.upper().tolist()
        prog = st.progress(0.0, text=f"Fetching fundamentals for {len(tks)} tickers…")
        for i, tk in enumerate(tks):
            try:
                _tb._ab_fundamentals(tk, conn)
            except Exception:
                pass
            if i % 15 == 0:
                prog.progress(min(1.0, (i + 1) / max(len(tks), 1)))
        prog.progress(1.0)
        return len(tks)
    finally:
        conn.close()


@st.cache_data(ttl=120, show_spinner=False)
def load_stock_daily(ticker):
    df = q("SELECT * FROM stock_daily WHERE ticker=?", [ticker])
    if not df.empty:
        df["_dt"] = pd.to_datetime(df["trade_date"], format="%Y-%m-%d", errors="coerce")
        df = df.sort_values("_dt", ascending=False).drop(columns=["_dt"])
    return df


def get_next_day_stock_move(ticker, trade_date_mmddyyyy):
    """Get the stock price change on the next trading day after trade_date."""
    sd = load_stock_daily(ticker)
    if sd.empty:
        return None, None, None
    sd = sd.copy()
    sd["_dt"] = pd.to_datetime(sd["trade_date"], format="%Y-%m-%d", errors="coerce")
    sd = sd.sort_values("_dt").reset_index(drop=True)
    ref_dt = pd.to_datetime(trade_date_mmddyyyy, format="%Y-%m-%d")
    ref_row = sd[sd["_dt"] == ref_dt]
    if ref_row.empty:
        return None, None, None
    idx = ref_row.index[0]
    if idx + 1 >= len(sd):
        return float(ref_row["close"].iloc[0]), None, None
    next_row = sd.iloc[idx + 1]
    close_today = float(ref_row["close"].iloc[0])
    close_next = float(next_row["close"])
    pct = (close_next - close_today) / close_today * 100 if close_today else 0
    return close_today, close_next, pct

def oi_anomalies(df, z_thresh=2.0):
    """Aggregate OI changes per ticker and flag z-score anomalies."""
    agg = df.groupby("ticker").agg(
        call_oi_chg=("change_OI_Call", "sum"),
        put_oi_chg=("change_OI_Put", "sum"),
        call_vol_chg=("change_vol_Call", "sum"),
        put_vol_chg=("change_vol_Put", "sum"),
        call_oi=("openInt_Call_now", "sum"),
        put_oi=("openInt_Put_now", "sum"),
    ).reset_index()
    for c in ["call_oi_chg", "put_oi_chg", "call_vol_chg", "put_vol_chg"]:
        mu, sd = agg[c].mean(), agg[c].std()
        agg[f"{c}_z"] = (agg[c] - mu) / sd if sd > 0 else 0
    z_cols = [c for c in agg.columns if c.endswith("_z")]
    agg["max_z"] = agg[z_cols].abs().max(axis=1)
    agg["pcr"] = np.where(agg["call_oi"] > 0, agg["put_oi"] / agg["call_oi"], 0)
    return agg.sort_values("max_z", ascending=False)


def infer_pressure(row):
    """Infer buy/sell/hedge for a single options_change row."""
    c_sig, c_conf, p_sig, p_conf, reasons = "NEUTRAL", 0, "NEUTRAL", 0, []

    # CALL side
    oi_c = row.get("change_OI_Call", 0) or 0
    vol_c = row.get("vol_Call_now", 0) or 0
    c_open = row.get("call_open_now", None)
    c_close = row.get("call_close_now", None)
    c_high = row.get("call_high_now", None)
    c_low = row.get("call_low_now", None)

    if oi_c > 100:
        vol_r = vol_c / abs(oi_c) if oi_c else 0
        if c_close is not None and c_open is not None and c_close > 0:
            up = c_close > c_open
            rng = (c_high or c_close) - (c_low or c_open)
            pos = ((c_close - (c_low or c_open)) / rng) if rng > 0 else 0.5
            if up and vol_r >= 0.8 and pos > 0.6:
                c_sig, c_conf = "STRONG BUY", 90
            elif up and vol_r >= 0.5:
                c_sig, c_conf = "BUY", 70
            elif not up and pos < 0.4:
                c_sig, c_conf = "WRITING", 65
            else:
                c_sig, c_conf = "MIXED", 40
        else:
            c_sig, c_conf = "BUY" if vol_r > 0.5 else "MIXED", 55
        reasons.append(f"Call OI +{oi_c:,.0f}")
    elif oi_c < -100:
        c_sig, c_conf = "CLOSING", 80
        reasons.append(f"Call OI {oi_c:,.0f} closing")

    # PUT side
    oi_p = row.get("change_OI_Put", 0) or 0
    vol_p = row.get("vol_Put_now", 0) or 0
    p_open = row.get("put_open_now", None)
    p_close = row.get("put_close_now", None)
    p_high = row.get("put_high_now", None)
    p_low = row.get("put_low_now", None)

    if oi_p > 100:
        vol_r = vol_p / abs(oi_p) if oi_p else 0
        if p_close is not None and p_open is not None and p_close > 0:
            up = p_close > p_open
            rng = (p_high or p_close) - (p_low or p_open)
            pos = ((p_close - (p_low or p_open)) / rng) if rng > 0 else 0.5
            if up and vol_r >= 0.8 and pos > 0.6:
                p_sig, p_conf = "STRONG BUY", 90
            elif up and vol_r >= 0.5:
                p_sig, p_conf = "BUY", 70
            elif not up and pos < 0.4:
                p_sig, p_conf = "WRITING", 65
            else:
                p_sig, p_conf = "MIXED", 40
        else:
            p_sig, p_conf = "BUY" if vol_r > 0.5 else "MIXED", 55
        reasons.append(f"Put OI +{oi_p:,.0f}")
    elif oi_p < -100:
        p_sig, p_conf = "CLOSING", 80
        reasons.append(f"Put OI {oi_p:,.0f} closing")

    # Net interpretation
    net = ""
    if c_sig in ("STRONG BUY", "BUY") and p_sig in ("CLOSING", "WRITING", "NEUTRAL"):
        net = "BULLISH"
    elif p_sig in ("STRONG BUY", "BUY") and c_sig in ("CLOSING", "WRITING", "NEUTRAL"):
        net = "BEARISH / HEDGE"
    elif c_sig == "WRITING" and p_sig == "WRITING":
        net = "PREMIUM SELLING (range-bound)"
    elif c_sig == "CLOSING" and p_sig == "CLOSING":
        net = "RISK-OFF (unwinding)"
    elif c_sig in ("STRONG BUY", "BUY") and p_sig in ("STRONG BUY", "BUY"):
        net = "STRADDLE / VOL BUY"
    else:
        net = "MIXED"

    return dict(call_signal=c_sig, call_conf=c_conf, put_signal=p_sig,
                put_conf=p_conf, net_view=net, reasons="; ".join(reasons))


# ===================================================================
# ──  OI PREDICTION ENGINE  (next-day hints from OI changes)
# ===================================================================
def oi_prediction_analysis(ticker, dates_back=5):
    """
    Analyse OI changes across multiple days and predict next-day direction.

    Logic:
    1. Aggregate call/put OI change per day
    2. Calculate PCR trend, net delta proxy, gamma exposure proxy
    3. Backtest the signal against actual next-day stock moves
    4. Return prediction + accuracy table
    """
    conn = get_conn()
    # Get last N+1 trade dates for the ticker (chronological sort)
    raw_dates = pd.read_sql(
        "SELECT DISTINCT trade_date_now FROM options_change WHERE ticker=?",
        conn, params=[ticker])["trade_date_now"].tolist()
    all_dates = _sort_dates_chrono(raw_dates, descending=True)

    if len(all_dates) < 3:
        conn.close()
        return None, None

    dates_use = all_dates[:dates_back + 1]  # one extra for "next day"

    rows = []
    for td in dates_use:
        day_df = pd.read_sql(
            "SELECT change_OI_Call, change_OI_Put, openInt_Call_now, openInt_Put_now, "
            "vol_Call_now, vol_Put_now, strike, expiry_date, "
            "lastPrice_Call_now, lastPrice_Put_now "
            "FROM options_change WHERE ticker=? AND trade_date_now=?",
            conn, params=[ticker, td])
        if day_df.empty:
            continue

        call_oi_chg = day_df["change_OI_Call"].sum()
        put_oi_chg = day_df["change_OI_Put"].sum()
        call_oi_total = day_df["openInt_Call_now"].sum()
        put_oi_total = day_df["openInt_Put_now"].sum()
        pcr = put_oi_total / call_oi_total if call_oi_total > 0 else 0
        call_vol = day_df["vol_Call_now"].sum()
        put_vol = day_df["vol_Put_now"].sum()
        vol_pcr = put_vol / call_vol if call_vol > 0 else 0

        # Net OI bias: positive = more call OI added → bullish
        net_oi_bias = call_oi_chg - put_oi_chg

        # Gamma exposure proxy: sum(OI * strike) weighted
        day_df["gex_call"] = day_df["openInt_Call_now"] * day_df["strike"]
        day_df["gex_put"] = day_df["openInt_Put_now"] * day_df["strike"]
        gex_net = day_df["gex_call"].sum() - day_df["gex_put"].sum()

        rows.append(dict(
            trade_date=td,
            call_oi_chg=call_oi_chg, put_oi_chg=put_oi_chg,
            net_oi_bias=net_oi_bias,
            pcr_oi=pcr, vol_pcr=vol_pcr,
            call_vol=call_vol, put_vol=put_vol,
            gex_net=gex_net,
            call_oi_total=call_oi_total, put_oi_total=put_oi_total,
        ))

    conn.close()
    if not rows:
        return None, None
    pred_df = pd.DataFrame(rows)

    # Get stock price data for backtest
    stock_df = load_stock_daily(ticker)
    if not stock_df.empty:
        pred_df = pred_df.merge(stock_df[["trade_date", "close", "volume"]].rename(
            columns={"trade_date": "trade_date"}), left_on="trade_date",
            right_on="trade_date", how="left")
        pred_df["next_close"] = pred_df["close"].shift(-1)
        pred_df["actual_move"] = pred_df["next_close"] - pred_df["close"]
        pred_df["actual_pct"] = pred_df["actual_move"] / pred_df["close"] * 100

    # Signal: composite score
    pred_df["oi_signal"] = np.where(pred_df["net_oi_bias"] > 0, 1, -1)
    pred_df["pcr_signal"] = np.where(pred_df["pcr_oi"] < 0.7, 1,
                            np.where(pred_df["pcr_oi"] > 1.3, -1, 0))
    pred_df["vol_signal"] = np.where(pred_df["vol_pcr"] < 0.7, 1,
                            np.where(pred_df["vol_pcr"] > 1.3, -1, 0))
    pred_df["composite"] = pred_df["oi_signal"] + pred_df["pcr_signal"] + pred_df["vol_signal"]
    pred_df["prediction"] = np.where(pred_df["composite"] >= 2, "BULLISH",
                            np.where(pred_df["composite"] <= -2, "BEARISH", "NEUTRAL"))

    # Backtest accuracy
    if "actual_move" in pred_df.columns:
        valid = pred_df.dropna(subset=["actual_move"])
        if len(valid) > 0:
            correct = ((valid["composite"] > 0) & (valid["actual_move"] > 0)) | \
                      ((valid["composite"] < 0) & (valid["actual_move"] < 0))
            accuracy = correct.sum() / len(valid) * 100
        else:
            accuracy = None
    else:
        accuracy = None

    return pred_df, accuracy


# ===================================================================
# ──  MULTI-DAY OI ACCUMULATION  (cumulative build + conviction)
# ===================================================================

@st.cache_data(ttl=1800, show_spinner=False)
def _load_oi_multi_day(ticker, n_days=7):
    """Load OI data for last n_days trade dates for a ticker.
    Returns (DataFrame with trade_date column, list of dates newest-first).
    """
    conn = get_conn()
    raw_dates = pd.read_sql(
        "SELECT DISTINCT trade_date_now FROM options_change WHERE ticker=?",
        conn, params=[ticker])["trade_date_now"].tolist()
    conn.close()
    all_dates = _sort_dates_chrono(raw_dates, descending=True)
    dates_use = all_dates[:n_days]
    if not dates_use:
        return pd.DataFrame(), []
    frames = []
    for td in dates_use:
        df = q(
            "SELECT strike, expiry_date, change_OI_Call, change_OI_Put, "
            "openInt_Call_now, openInt_Put_now, vol_Call_now, vol_Put_now "
            "FROM options_change WHERE ticker=? AND trade_date_now=?",
            [ticker, td])
        if not df.empty:
            df["trade_date"] = td
            frames.append(df)
    if not frames:
        return pd.DataFrame(), dates_use
    return pd.concat(frames, ignore_index=True), dates_use


def _compute_oi_conviction(multi_df, dates_newest_first, live_px=0):
    """Per-strike conviction score based on N-day OI accumulation consistency.

    Returns DataFrame sorted by conviction descending.
    Columns: strike, direction, conviction, streak, streak_dir, cum_net,
             cum_call, cum_put, consistency, bull_days, bear_days, n_days
    """
    if multi_df.empty:
        return pd.DataFrame()

    # Aggregate across expiries to get per (strike, date) net
    day_agg = multi_df.groupby(["strike", "trade_date"]).agg(
        call_chg=("change_OI_Call", "sum"),
        put_chg=("change_OI_Put", "sum"),
        call_vol=("vol_Call_now", "sum"),
        put_vol=("vol_Put_now", "sum"),
    ).reset_index()
    day_agg["net_chg"] = day_agg["call_chg"] - day_agg["put_chg"]

    # Cumulative totals per strike across all N days
    strike_agg = day_agg.groupby("strike").agg(
        cum_call=("call_chg", "sum"),
        cum_put=("put_chg", "sum"),
        cum_net=("net_chg", "sum"),
        avg_call_vol=("call_vol", "mean"),
        avg_put_vol=("put_vol", "mean"),
        n_days=("trade_date", "count"),
        bull_days=("net_chg", lambda x: (x > 0).sum()),
        bear_days=("net_chg", lambda x: (x < 0).sum()),
    ).reset_index()

    # Current streak: consecutive matching direction from most recent day back
    date_rank = {d: i for i, d in enumerate(dates_newest_first)}  # 0 = newest
    streaks = []
    for strike in strike_agg["strike"].unique():
        sk = day_agg[day_agg["strike"] == strike].copy()
        sk["rank"] = sk["trade_date"].map(date_rank)
        sk = sk.sort_values("rank")  # newest first (rank 0 = newest)
        streak, streak_dir = 0, "FLAT"
        for _, row in sk.iterrows():
            d = row["net_chg"]
            cur_dir = "BULL" if d > 0 else ("BEAR" if d < 0 else "FLAT")
            if streak == 0:
                streak_dir = cur_dir
                streak = 1 if cur_dir != "FLAT" else 0
            elif cur_dir == streak_dir and cur_dir != "FLAT":
                streak += 1
            else:
                break
        streaks.append({"strike": strike, "streak": streak, "streak_dir": streak_dir})

    streak_df = pd.DataFrame(streaks)
    strike_agg = strike_agg.merge(streak_df, on="strike", how="left")

    # Directional consistency (fraction of days in winning direction)
    strike_agg["consistency"] = strike_agg.apply(
        lambda r: r["bull_days"] / r["n_days"] if r["cum_net"] >= 0
                  else r["bear_days"] / r["n_days"], axis=1)

    # Conviction score 0-10
    max_cum = strike_agg["cum_net"].abs().max()
    strike_agg["mag_score"] = (
        (strike_agg["cum_net"].abs() / max_cum * 4).clip(0, 4)
        if max_cum > 0 else 0.0
    )
    strike_agg["consistency_score"] = (strike_agg["consistency"] * 3).clip(0, 3)
    strike_agg["streak_score"] = strike_agg["streak"].clip(0, 2).astype(float)

    # ATM proximity bonus (+1 within 5% of spot)
    if live_px > 0:
        strike_agg["dist_pct"] = (strike_agg["strike"] - live_px).abs() / live_px * 100
        strike_agg["atm_bonus"] = np.where(strike_agg["dist_pct"] <= 5, 1.0, 0.0)
    else:
        strike_agg["dist_pct"] = 0.0
        strike_agg["atm_bonus"] = 0.0

    strike_agg["conviction"] = (
        strike_agg["mag_score"] + strike_agg["consistency_score"]
        + strike_agg["streak_score"] + strike_agg["atm_bonus"]
    ).clip(0, 10).round(1)

    strike_agg["direction"] = np.where(
        strike_agg["cum_net"] > 0, "BULL",
        np.where(strike_agg["cum_net"] < 0, "BEAR", "FLAT"))

    return strike_agg.sort_values("conviction", ascending=False).reset_index(drop=True)


def _sa_features(conn, ticker):
    """Per-ticker daily feature frame for signal-accuracy backtest: close, pcr_oi,
    OI net bias (sum CallΔOI - sum PutΔOI per snapshot), plus derived momentum / RSI /
    SMA features. Returns a date-sorted DataFrame or None if too little history."""
    sk = "trade_date"
    sd = pd.read_sql(
        f"SELECT trade_date, close, volume, pcr_oi FROM stock_daily WHERE ticker=? ORDER BY {sk}",
        conn, params=(ticker.upper(),))
    if len(sd) < 30:
        return None
    sd["close"] = pd.to_numeric(sd["close"], errors="coerce")
    sd["pcr_oi"] = pd.to_numeric(sd["pcr_oi"], errors="coerce")
    oi = pd.read_sql(
        "SELECT trade_date_now AS trade_date,"
        " SUM(COALESCE(change_OI_Call,0)) AS cb, SUM(COALESCE(change_OI_Put,0)) AS pb"
        " FROM options_change WHERE ticker=? GROUP BY trade_date_now",
        conn, params=(ticker.upper(),))
    sd = sd.merge(oi, on="trade_date", how="left")
    sd["oi_net"] = sd["cb"].fillna(0) - sd["pb"].fillna(0)
    # rolling z of OI net bias (per-ticker scale) and PCR (contrarian)
    sd["oi_z"] = (sd["oi_net"] - sd["oi_net"].rolling(20, min_periods=8).mean()) \
        / (sd["oi_net"].rolling(20, min_periods=8).std() + 1e-9)
    sd["pcr_z"] = (sd["pcr_oi"] - sd["pcr_oi"].rolling(20, min_periods=8).mean()) \
        / (sd["pcr_oi"].rolling(20, min_periods=8).std() + 1e-9)
    sd["mom10"] = sd["close"] / sd["close"].shift(10) - 1
    sd["sma20"] = sd["close"].rolling(20).mean()
    sd["pvs"] = sd["close"] / sd["sma20"] - 1
    d = sd["close"].diff()
    up = d.clip(lower=0).rolling(14).mean()
    dn = (-d.clip(upper=0)).rolling(14).mean()
    sd["rsi"] = 100 - 100 / (1 + up / dn.replace(0, np.nan))
    return sd


# DB-computable signals: (name, description, fn(row)->direction in {+1 bull,-1 bear,0 skip})
_SA_SIGNALS = [
    ("OI Net Bias", "Net call-vs-put ΔOI (z>0.5 bull / z<-0.5 bear)",
     lambda r: 1 if r["oi_z"] > 0.5 else (-1 if r["oi_z"] < -0.5 else 0)),
    ("PCR Contrarian", "Put/Call OI z-score, faded (z>1 bull / z<-1 bear)",
     lambda r: 1 if r["pcr_z"] > 1.0 else (-1 if r["pcr_z"] < -1.0 else 0)),
    ("Momentum 10d", "10-day price momentum, continuation",
     lambda r: 1 if r["mom10"] > 0.01 else (-1 if r["mom10"] < -0.01 else 0)),
    ("RSI(14) Reversion", "Oversold<35 bounce / overbought>65 fade",
     lambda r: 1 if r["rsi"] < 35 else (-1 if r["rsi"] > 65 else 0)),
    ("Price vs SMA20", "Trend filter, above/below 20-day mean",
     lambda r: 1 if r["pvs"] > 0.005 else (-1 if r["pvs"] < -0.005 else 0)),
]


@st.cache_data(ttl=300, show_spinner=False)
def _signal_accuracy_backtest(ticker, hold_days=5, move_thr=0.005):
    """Backtest DB-computable signals for one ticker or the whole universe ('(All)').
    For each historical day, derive each signal's directional call, then score it against
    the forward `hold_days` stock return. Returns dict with per-signal hit-rate, mean
    signed (directional) return = edge, sample sizes, and overall coverage."""
    if not DB_PATH:
        return None
    conn = sqlite3.connect(DB_PATH)
    try:
        if ticker and ticker != "(All)":
            tickers = [ticker.upper()]
        else:
            tickers = [r[0] for r in conn.execute(
                "SELECT DISTINCT ticker FROM stock_daily").fetchall()]
        frames = []
        for tk in tickers:
            f = _sa_features(conn, tk)
            if f is None:
                continue
            f["fwd"] = f["close"].shift(-hold_days) / f["close"] - 1
            frames.append(f)
    finally:
        conn.close()
    if not frames:
        return None
    df = pd.concat(frames, ignore_index=True)
    df = df[df["fwd"].notna()]
    out = []
    for name, desc, fn in _SA_SIGNALS:
        try:
            dirs = df.apply(fn, axis=1)
        except Exception:
            continue
        m = dirs != 0
        sub = df[m]
        sd_ = dirs[m]
        if len(sub) < 5:
            out.append({"name": name, "desc": desc, "n": int(len(sub)),
                        "hit": None, "edge": None, "n_bull": int((sd_ > 0).sum()),
                        "n_bear": int((sd_ < 0).sum())})
            continue
        signed = sd_.values * sub["fwd"].values            # directional return per call
        hit = float(((sd_.values > 0) & (sub["fwd"].values > move_thr)).sum()
                    + ((sd_.values < 0) & (sub["fwd"].values < -move_thr)).sum()) / len(sub)
        out.append({"name": name, "desc": desc, "n": int(len(sub)),
                    "hit": round(hit * 100, 1), "edge": round(float(np.mean(signed)) * 100, 2),
                    "n_bull": int((sd_ > 0).sum()), "n_bear": int((sd_ < 0).sum())})
    # naive baseline: unconditional P(up) over same horizon
    base_up = round(float((df["fwd"] > move_thr).mean()) * 100, 1)
    base_ret = round(float(df["fwd"].mean()) * 100, 2)
    return {"ticker": ticker, "hold_days": hold_days, "move_thr": move_thr,
            "signals": out, "n_obs": int(len(df)), "n_tickers": len(frames),
            "base_up": base_up, "base_ret": base_ret}


@st.cache_data(ttl=300, show_spinner=False)
def _signal_accuracy_24model(ticker):
    """Forward-tracked accuracy of the 24-model ensemble from the signal_accuracy table
    (populated live by telegram_bot's high_prob_signals_engine). Returns per-model and
    overall hit-rate over resolved predictions, or None if nothing resolved yet."""
    if not DB_PATH:
        return None
    conn = sqlite3.connect(DB_PATH)
    try:
        q = ("SELECT model_name, signal, correct, actual_ret FROM signal_accuracy"
             " WHERE correct>=0")
        params = ()
        if ticker and ticker != "(All)":
            q += " AND ticker=?"
            params = (ticker.upper(),)
        df = pd.read_sql(q, conn, params=params)
    except Exception:
        return None
    finally:
        conn.close()
    if df.empty:
        return None
    g = df.groupby("model_name").agg(
        n=("correct", "size"), hit=("correct", "mean"),
        avg_ret=("actual_ret", "mean")).reset_index()
    g["hit"] = (g["hit"] * 100).round(1)
    g["avg_ret"] = (g["avg_ret"] * 100).round(2)
    g = g.sort_values("hit", ascending=False)
    return {"per_model": g, "overall_hit": round(float(df["correct"].mean()) * 100, 1),
            "n_total": int(len(df))}


def _log_sentiment(ticker, source, label, score=None):
    """Forward-log a daily sentiment reading so it can be OBSERVED over time (not scored —
    sentiment is noisy/reflexive, so we record it for eyeballing, not as a validated edge).
    Keyed by ticker+date+source; idempotent within a day."""
    try:
        today_s = datetime.now().strftime("%Y-%m-%d")
        with sqlite3.connect(DB_PATH) as conn:
            conn.execute(
                "CREATE TABLE IF NOT EXISTS sentiment_log ("
                "ticker TEXT, trade_date TEXT, source TEXT, label TEXT, score REAL, "
                "fwd_ret REAL, PRIMARY KEY (ticker, trade_date, source))")
            conn.execute(
                "INSERT OR REPLACE INTO sentiment_log (ticker, trade_date, source, label, score) "
                "VALUES (?,?,?,?,?)",
                (ticker.upper(), today_s, source, str(label),
                 float(score) if score is not None else None))
            conn.commit()
    except Exception:
        pass


@st.cache_data(ttl=300, show_spinner=False)
def _sentiment_log_view(ticker=None, move_thr=0.005):
    """Read the forward-logged sentiment, resolve next-day returns from stock_daily, and SCORE
    it: hit-rate + directional edge per label and per source (BULLISH→up, BEARISH→down,
    MIXED/NEUTRAL→flat). Sample is small/forward-only, so it's scored *and* caveated."""
    try:
        with sqlite3.connect(DB_PATH) as conn:
            if not conn.execute("SELECT name FROM sqlite_master WHERE type='table' "
                                "AND name='sentiment_log'").fetchone():
                return None
            q = "SELECT ticker, trade_date, source, label, score, fwd_ret FROM sentiment_log"
            params = ()
            if ticker and ticker != "(All)":
                q += " WHERE ticker=?"; params = (ticker.upper(),)
            df = pd.read_sql(q, conn, params=params)
            if df.empty:
                return None
            # resolve next-day forward return for any unresolved rows
            need = df[df["fwd_ret"].isna()]
            for tk in need["ticker"].unique():
                px = pd.read_sql(
                    "SELECT trade_date, close FROM stock_daily WHERE ticker=? ORDER BY "
                    "trade_date",
                    conn, params=(tk,))
                if len(px) < 2:
                    continue
                px["close"] = pd.to_numeric(px["close"], errors="coerce")
                px["nret"] = px["close"].shift(-1) / px["close"] - 1
                rmap = dict(zip(px["trade_date"], px["nret"]))
                for _, r in need[need["ticker"] == tk].iterrows():
                    rr = rmap.get(r["trade_date"])
                    if rr is not None and pd.notna(rr):
                        conn.execute("UPDATE sentiment_log SET fwd_ret=? WHERE ticker=? AND "
                                     "trade_date=? AND source=?",
                                     (round(float(rr), 5), r["ticker"], r["trade_date"], r["source"]))
            conn.commit()
            df = pd.read_sql(q, conn, params=params)
    except Exception:
        return None
    res = df[df["fwd_ret"].notna()].copy()
    if res.empty:
        return {"n_logged": int(len(df)), "n_resolved": 0, "by_label": None,
                "by_source": None, "overall_hit": None}

    def _dir(lbl):
        return 1 if lbl == "BULLISH" else -1 if lbl == "BEARISH" else 0
    res["dir"] = res["label"].map(_dir)
    res["signed"] = res["dir"] * res["fwd_ret"]

    def _hit(r):
        if r["dir"] == 1:
            return 1.0 if r["fwd_ret"] > move_thr else 0.0
        if r["dir"] == -1:
            return 1.0 if r["fwd_ret"] < -move_thr else 0.0
        return 1.0 if abs(r["fwd_ret"]) < move_thr else 0.0
    res["correct"] = res.apply(_hit, axis=1)

    by_label = res.groupby("label").agg(
        n=("correct", "size"), hit=("correct", "mean"),
        edge=("signed", "mean"), avg_next=("fwd_ret", "mean")).reset_index()
    by_label["hit"] = (by_label["hit"] * 100).round(1)
    by_label["edge"] = (by_label["edge"] * 100).round(2)
    by_label["avg_next"] = (by_label["avg_next"] * 100).round(2)

    # directional rows only (exclude neutral/mixed) for the per-source scorecard
    dres = res[res["dir"] != 0]
    by_source = None
    if not dres.empty:
        by_source = dres.groupby("source").agg(
            n=("correct", "size"), hit=("correct", "mean"), edge=("signed", "mean")).reset_index()
        by_source["hit"] = (by_source["hit"] * 100).round(1)
        by_source["edge"] = (by_source["edge"] * 100).round(2)
        by_source = by_source.sort_values("hit", ascending=False)

    overall_hit = round(float(dres["correct"].mean()) * 100, 1) if not dres.empty else None
    return {"n_logged": int(len(df)), "n_resolved": int(len(res)),
            "by_label": by_label, "by_source": by_source, "overall_hit": overall_hit}


def _oi_idea_metrics(conn, ticker, strike, direction, spot, r=0.045):
    """Concrete economics for an OI-conviction idea: entry premium (from DB), expiry/DTE,
    IV (back-solved), POP (~|delta|), a 1-sigma expected-move target + the option's value
    there, max risk and reward:risk. Returns dict, or None if no usable premium in DB."""
    if not spot or spot <= 0:
        return None
    typ = "call" if direction == "BULL" else "put"
    last_col = "lastPrice_Call_now" if typ == "call" else "lastPrice_Put_now"
    oi_col = "openInt_Call_now" if typ == "call" else "openInt_Put_now"
    try:
        rows = pd.read_sql(
            f"SELECT expiry_date, {last_col} AS last, {oi_col} AS oi "
            "FROM options_change WHERE ticker=? AND strike=?",
            conn, params=(ticker, float(strike)))
    except Exception:
        return None
    if rows.empty:
        return None
    today = datetime.now()
    cand = []
    for _, rr in rows.iterrows():
        ed = None
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%m-%d-%Y", "%Y/%m/%d"):
            try:
                ed = datetime.strptime(str(rr["expiry_date"]), fmt); break
            except Exception:
                pass
        if ed is None:
            continue
        dte = (ed - today).days
        last = float(rr["last"] or 0)
        if dte >= 1 and last > 0:
            cand.append((dte, str(rr["expiry_date"]), last, float(rr["oi"] or 0)))
    if not cand:
        return None
    # prefer the ideal 21-50 DTE entry zone, else the nearest future expiry
    ideal = [c for c in cand if 21 <= c[0] <= 50]
    dte, exp, entry, oi = sorted(ideal or cand, key=lambda c: (0 if 21 <= c[0] <= 50 else 1, c[0]))[0]
    T = max(dte, 1) / 365.0
    iv = _implied_vol(entry, spot, float(strike), T, r, typ)
    g = bs_greeks(spot, float(strike), T, r, iv, typ)
    pop = abs(g.get("delta", 0.0)) * 100
    H = min(dte, 10)                                   # ~2-week hold (capped by DTE)
    sigma_move = spot * iv * (H / 252.0) ** 0.5        # 1-sigma expected move
    target = spot + sigma_move if typ == "call" else spot - sigma_move
    T_rem = max(dte - H, 1) / 365.0
    tval = bs_greeks(target, float(strike), T_rem, r, iv, typ).get("price", 0.0)
    profit_pct = (tval - entry) / entry * 100 if entry > 0 else 0.0
    return {
        "type": typ, "expiry": exp, "dte": dte, "entry": entry, "invest": entry * 100,
        "iv": iv, "pop": pop, "target": target, "target_val": tval,
        "profit_pct": profit_pct, "max_risk": entry * 100,
        "rr": (max(tval - entry, 0) / entry) if entry > 0 else 0.0,
        "hold": H, "move_pct": sigma_move / spot * 100 * (1 if typ == "call" else -1),
    }


@st.cache_data(ttl=600, show_spinner=False)
def _backtest_oi_conviction(ticker, lookback=7, hold_days=5, min_conv=6, max_ideas=5,
                            tp_pct=100.0, sl_pct=50.0):
    """Walk-forward backtest of OI-conviction ideas using stored option premiums.
    For each historical date, fire ideas (conviction >= min_conv) and track the long
    option over the next `hold_days` on the SAME strike+expiry:
      • fixed-hold P&L (exit on day N),
      • managed P&L with a take-profit / stop rule (first daily close to touch),
      • MFE / MAE (best & worst close reached during the hold).
    Returns (summary dict, trades DataFrame)."""
    conn = get_conn()
    try:
        hist = pd.read_sql(
            "SELECT strike, expiry_date, trade_date_now, change_OI_Call, change_OI_Put, "
            "openInt_Call_now, openInt_Put_now, vol_Call_now, vol_Put_now, "
            "lastPrice_Call_now, lastPrice_Put_now FROM options_change WHERE ticker=?",
            conn, params=(ticker,))
        sd = pd.read_sql("SELECT trade_date, close FROM stock_daily WHERE ticker=?",
                         conn, params=(ticker,))
    finally:
        conn.close()
    if hist.empty:
        return {"n": 0}, pd.DataFrame()
    spot_by_date = {str(d): float(c) for d, c in zip(sd["trade_date"], sd["close"])}
    dates = _sort_dates_chrono(list(hist["trade_date_now"].dropna().unique()), descending=False)
    if len(dates) < lookback + hold_days + 1:
        return {"n": 0, "error": "not enough history"}, pd.DataFrame()

    def _parse(d):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%m-%d-%Y", "%Y/%m/%d"):
            try:
                return datetime.strptime(str(d), fmt)
            except Exception:
                pass
        return None

    # fast price index: (date, strike, expiry) -> (callLast, putLast)
    pidx = {}
    for t in hist.itertuples(index=False):
        pidx[(t.trade_date_now, float(t.strike), t.expiry_date)] = (
            float(t.lastPrice_Call_now or 0), float(t.lastPrice_Put_now or 0))

    tp, sl = tp_pct / 100.0, sl_pct / 100.0
    trades = []
    for i in range(lookback - 1, len(dates) - hold_days):
        sig_d = dates[i]
        path_dates = dates[i + 1: i + hold_days + 1]
        exit_d = path_dates[-1]
        window = dates[i - lookback + 1: i + 1]
        sub = hist[hist["trade_date_now"].isin(window)].copy()
        spot_sig = spot_by_date.get(sig_d)
        if sub.empty or not spot_sig:
            continue
        sub = sub.rename(columns={"trade_date_now": "trade_date"})
        conv = _compute_oi_conviction(sub, _sort_dates_chrono(list(window), descending=True), spot_sig)
        if conv.empty:
            continue
        exd = _parse(exit_d)
        for _, rr2 in conv[conv["conviction"] >= min_conv].head(max_ideas).iterrows():
            direction = rr2["direction"]
            if direction not in ("BULL", "BEAR"):
                continue
            strike = float(rr2["strike"]); typ = "call" if direction == "BULL" else "put"
            ix = 0 if typ == "call" else 1
            lc = "lastPrice_Call_now" if typ == "call" else "lastPrice_Put_now"
            oc = "openInt_Call_now" if typ == "call" else "openInt_Put_now"
            er = hist[(hist["trade_date_now"] == sig_d) & (hist["strike"] == strike)]
            best = None
            for _, e in er.iterrows():
                ed = _parse(e["expiry_date"])
                if ed is None or (exd is not None and ed <= exd):
                    continue                          # skip expiries that die during the hold
                entry_px = float(e[lc] or 0)
                if entry_px <= 0:
                    continue
                if best is None or float(e[oc] or 0) > best[2]:
                    best = (str(e["expiry_date"]), entry_px, float(e[oc] or 0))
            if best is None:
                continue
            exp, entry_px, _ = best
            # daily option-price path over the hold
            path = []
            for d in path_dates:
                pv = pidx.get((d, strike, exp))
                if pv is not None and pv[ix] >= 0:
                    path.append(pv[ix])
            if not path:
                continue
            exit_px = path[-1]
            fixed = (exit_px - entry_px) / entry_px * 100
            mfe = (max(path) - entry_px) / entry_px * 100
            mae = (min(path) - entry_px) / entry_px * 100
            managed, reason = fixed, "TIME"          # first daily close to hit TP or SL
            for pv in path:
                ch = (pv - entry_px) / entry_px
                if ch >= tp:
                    managed, reason = tp * 100, "TP"; break
                if ch <= -sl:
                    managed, reason = -sl * 100, "SL"; break
            trades.append({
                "signal_date": sig_d, "exit_date": exit_d, "strike": strike,
                "dir": direction, "type": typ, "expiry": exp, "entry": round(entry_px, 2),
                "exit": round(exit_px, 2), "pnl_pct": round(fixed, 1),
                "managed_pct": round(managed, 1), "exit_reason": reason,
                "mfe_pct": round(mfe, 1), "mae_pct": round(mae, 1),
                "conviction": float(rr2["conviction"]),
                "path": [round((pv - entry_px) / entry_px * 100, 1) for pv in path],
            })
    tdf = pd.DataFrame(trades)
    if tdf.empty:
        return {"n": 0}, tdf

    def _pf(series):
        g = float(series[series > 0].sum()); l = float(series[series < 0].sum())
        return (g / abs(l)) if l < 0 else (float("inf") if g > 0 else 0.0)

    wins = tdf["pnl_pct"] > 0
    mw = tdf["managed_pct"] > 0
    buckets = {}
    for lo, hi, lbl in [(6, 7, "6–7"), (7, 8, "7–8"), (8, 10.01, "8–10")]:
        b = tdf[(tdf["conviction"] >= lo) & (tdf["conviction"] < hi)]
        if not b.empty:
            buckets[lbl] = {"n": int(len(b)), "win": float((b["pnl_pct"] > 0).mean() * 100),
                            "avg": float(b["pnl_pct"].mean())}
    summary = {
        "n": int(len(tdf)),
        "win_rate": float(wins.mean() * 100),
        "avg_pnl": float(tdf["pnl_pct"].mean()),
        "median_pnl": float(tdf["pnl_pct"].median()),
        "avg_win": float(tdf[wins]["pnl_pct"].mean()) if wins.any() else 0.0,
        "avg_loss": float(tdf[~wins]["pnl_pct"].mean()) if (~wins).any() else 0.0,
        "profit_factor": _pf(tdf["pnl_pct"]),
        "avg_mfe": float(tdf["mfe_pct"].mean()),
        "avg_mae": float(tdf["mae_pct"].mean()),
        "mgd_win_rate": float(mw.mean() * 100),
        "mgd_avg_pnl": float(tdf["managed_pct"].mean()),
        "mgd_profit_factor": _pf(tdf["managed_pct"]),
        "tp_hit": int((tdf["exit_reason"] == "TP").sum()),
        "sl_hit": int((tdf["exit_reason"] == "SL").sum()),
        "time_exit": int((tdf["exit_reason"] == "TIME").sum()),
        "bull_n": int((tdf["dir"] == "BULL").sum()),
        "bear_n": int((tdf["dir"] == "BEAR").sum()),
        "bull_win": float((tdf[tdf["dir"] == "BULL"]["pnl_pct"] > 0).mean() * 100) if (tdf["dir"] == "BULL").any() else 0.0,
        "bear_win": float((tdf[tdf["dir"] == "BEAR"]["pnl_pct"] > 0).mean() * 100) if (tdf["dir"] == "BEAR").any() else 0.0,
        "buckets": buckets,
        "hold_days": hold_days, "lookback": lookback, "min_conv": min_conv,
        "tp_pct": tp_pct, "sl_pct": sl_pct,
    }
    return summary, tdf


@st.cache_data(ttl=600, show_spinner=False)
def _optimize_oi_exit(ticker, lookback, hold_days, min_conv):
    """Grid-search take-profit/stop-loss over the backtested trades' daily price paths,
    then walk-forward validate (optimize on the 1st half, test out-of-sample on the 2nd).
    Returns (best dict, grid DataFrame, walk_forward dict)."""
    _, tdf = _backtest_oi_conviction(ticker, lookback, hold_days, min_conv)
    if tdf is None or tdf.empty or "path" not in tdf.columns:
        return {}, pd.DataFrame(), {}
    tdf = tdf.sort_values("signal_date").reset_index(drop=True)
    paths = list(tdf["path"]); fixed = list(tdf["pnl_pct"])
    tp_grid = [25, 40, 50, 75, 100, 150, 200]
    sl_grid = [25, 40, 50, 60, 75, 100]

    def _apply(ps, fs, tp, sl):
        out = []
        for pth, fx in zip(ps, fs):
            r = fx
            for ch in (pth or []):
                if ch >= tp:
                    r = float(tp); break
                if ch <= -sl:
                    r = float(-sl); break
            out.append(r)
        return np.array(out, dtype=float) if out else np.array([0.0])

    def _stats(arr):
        g = float(arr[arr > 0].sum()); l = float(arr[arr < 0].sum())
        return {"exp": float(arr.mean()), "win": float((arr > 0).mean() * 100),
                "pf": (g / abs(l)) if l < 0 else (float("inf") if g > 0 else 0.0)}

    rows = []
    for tp in tp_grid:
        for sl in sl_grid:
            s = _stats(_apply(paths, fixed, tp, sl))
            rows.append({"tp": tp, "sl": sl, **s})
    grid = pd.DataFrame(rows)
    best = grid.loc[grid["exp"].idxmax()].to_dict()

    # walk-forward: optimize on first half, apply to held-out second half
    n = len(tdf); mid = max(1, n // 2)
    tr_p, tr_f = paths[:mid], fixed[:mid]
    te_p, te_f = paths[mid:], fixed[mid:]
    b_tp, b_sl, b_exp = tp_grid[0], sl_grid[0], -1e9
    for tp in tp_grid:
        for sl in sl_grid:
            e = float(_apply(tr_p, tr_f, tp, sl).mean())
            if e > b_exp:
                b_tp, b_sl, b_exp = tp, sl, e
    te = _apply(te_p, te_f, b_tp, b_sl)
    te_s = _stats(te)
    wf = {"tp": b_tp, "sl": b_sl, "train_exp": b_exp, "n_train": mid, "n_test": len(te_p),
          "test_exp": te_s["exp"], "test_win": te_s["win"], "test_pf": te_s["pf"]}
    return best, grid, wf


# ── News + sentiment helpers (free sources, no API key) ──
_NEWS_POS = ("rally", "surge", "bull", "gain", "beat", "strong", "rise", "record", "buy",
             "upgrade", "boost", "growth", "profit", "optimis", "soar", "jump", "outperform",
             "raise", "tops", "win", "deal", "approval", "rebound", "expand", "demand")
_NEWS_NEG = ("drop", "fall", "crash", "sell-off", "bear", "loss", "cut", "slash", "tariff",
             "warn", "fear", "decline", "recession", "weak", "miss", "layoff", "plunge",
             "tumble", "sink", "dump", "concern", "risk", "threat", "crisis", "downgrade",
             "probe", "lawsuit", "halt", "slump", "fraud", "ban", "selloff", "glut")


# Words/phrases that dominate — if present, the headline reads negative regardless of any
# upbeat keyword (handles "deal paused", "Hormuz closed", "talks collapse", geopolitics, etc.)
_NEG_OVERRIDE = (
    "paused", "pause", "halt", "stall", "collapse", "delay", "fail", "fell through",
    "off the table", "blocked", "breakdown", "no deal", "scrapped", "called off",
    "closure", "closed", "shut", "blockade", "hormuz", "strait", "embargo", "sanction",
    "escalat", "conflict", " war", "attack", "strike on", "missile", "disrupt", "shortage",
    "glut", "probe", "lawsuit", "fraud", "recall", "downgrade", "plunge", "crash",
    "selloff", "sell-off", "tariff", "ban ", "slump", "tumble",
)
_NEG_FLIP = tuple(f"{neg} {pw}" for neg in ("no", "not", "without", "never", "denies", "denied")
                  for pw in ("deal", "beat", "gain", "growth", "upgrade", "demand", "approval"))


def _headline_tone(title):
    t = str(title).lower()
    if any(w in t for w in _NEG_OVERRIDE) or any(ph in t for ph in _NEG_FLIP):
        return -1                                  # decisive negative / disruption / negation
    p = sum(1 for w in _NEWS_POS if w in t)
    n = sum(1 for w in _NEWS_NEG if w in t)
    return 1 if p > n else (-1 if n > p else 0)


@st.cache_data(ttl=600, show_spinner=False)
def _ticker_news(ticker, n=6):
    """Free real-time headlines (Google News + Yahoo + Reddit RSS) with a simple
    bullish/bearish tone score. No API key. Returns dict(items, bull, bear, label)."""
    out = {"items": [], "bull": 0, "bear": 0, "label": "NEUTRAL"}
    try:
        import feedparser, time as _t, html as _h, socket
        socket.setdefaulttimeout(6)
    except Exception:
        return out
    srcs = [
        ("Google", f"https://news.google.com/rss/search?q={ticker}%20stock&hl=en-US&gl=US&ceid=US:en"),
        ("Yahoo", f"https://feeds.finance.yahoo.com/rss/2.0/headline?s={ticker}&region=US&lang=en-US"),
        ("Reddit", f"https://www.reddit.com/search.rss?q={ticker}&sort=new"),
    ]
    seen, items = set(), []
    for sname, url in srcs:
        try:
            fp = feedparser.parse(url)
            for e in fp.entries[:8]:
                title = _h.unescape(e.get("title", "")).strip()
                key = title.lower()[:80]
                if not title or key in seen:
                    continue
                seen.add(key)
                pp = e.get("published_parsed")
                when = _t.strftime("%d %b %H:%M", pp).lstrip("0") if pp else ""
                items.append({"title": title, "link": e.get("link", ""), "source": sname,
                              "when": when, "tone": _headline_tone(title)})
        except Exception:
            continue
    bull = sum(1 for i in items if i["tone"] > 0)
    bear = sum(1 for i in items if i["tone"] < 0)
    label = ("BULLISH" if bull > bear + 1 else "BEARISH" if bear > bull + 1
             else "MIXED" if (bull or bear) else "NEUTRAL")
    out.update({"items": items[:n], "bull": bull, "bear": bear, "label": label})
    return out


@st.cache_data(ttl=600, show_spinner=False)
def _stocktwits_sentiment(ticker):
    """Free StockTwits crowd sentiment (Bullish/Bearish message tags). No API key."""
    try:
        import urllib.request, json as _j
        req = urllib.request.Request(
            f"https://api.stocktwits.com/api/2/streams/symbol/{ticker}.json",
            headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=6) as r:
            d = _j.loads(r.read().decode())
        bull = bear = 0
        for m in d.get("messages", []):
            b = ((m.get("entities") or {}).get("sentiment") or {}).get("basic")
            if b == "Bullish": bull += 1
            elif b == "Bearish": bear += 1
        if bull + bear > 0:
            return {"bull": bull, "bear": bear,
                    "label": "BULLISH" if bull > bear * 1.3 else "BEARISH" if bear > bull * 1.3 else "MIXED"}
    except Exception:
        pass
    return None


@st.cache_data(ttl=900, show_spinner=False)
@st.cache_data(ttl=3600, show_spinner=False)
def _finnhub_insider_recs(ticker):
    """Finnhub analyst recommendation trend + insider-transaction sentiment (free endpoints).
    Returns {recs, insider} or None."""
    import os as _os, urllib.request as _u, json as _j, datetime as _dt
    key = _os.environ.get("FINNHUB_API_KEY") or _os.environ.get("FINNHUB_KEY")
    if not key:
        return None
    out = {"recs": None, "insider": None}
    try:
        d = _j.loads(_u.urlopen(f"https://finnhub.io/api/v1/stock/recommendation?symbol={ticker}&token={key}",
                                timeout=12).read().decode())
        if d:
            out["recs"] = d[0]
    except Exception:
        pass
    try:
        frm = (_dt.date.today() - _dt.timedelta(days=180)).isoformat(); to = _dt.date.today().isoformat()
        d = _j.loads(_u.urlopen(
            f"https://finnhub.io/api/v1/stock/insider-sentiment?symbol={ticker}&from={frm}&to={to}&token={key}",
            timeout=12).read().decode())
        rows = d.get("data", [])
        if rows:
            out["insider"] = {"net": sum(r.get("change", 0) for r in rows),
                              "mspr": sum(r.get("mspr", 0) for r in rows) / len(rows), "months": len(rows)}
    except Exception:
        pass
    return out if (out["recs"] or out["insider"]) else None


def _finnhub_sentiment(ticker):
    """Finnhub sentiment. Tries the news-sentiment endpoint (premium on some plans); if that's
    gated, falls back to the free company-news endpoint and scores the headlines locally.
    Needs free FINNHUB_API_KEY env var; returns None if no key / nothing usable."""
    key = os.environ.get("FINNHUB_API_KEY") or os.environ.get("FINNHUB_KEY")
    if not key:
        return None
    import urllib.request, json as _j
    # 1) news-sentiment (richest, but premium on some tiers)
    try:
        with urllib.request.urlopen(
                f"https://finnhub.io/api/v1/news-sentiment?symbol={ticker}&token={key}", timeout=6) as r:
            d = _j.loads(r.read().decode())
        bp = (d.get("sentiment") or {}).get("bullishPercent")
        if bp is not None:
            return {"bull_pct": bp * 100, "buzz": (d.get("buzz") or {}).get("buzz"),
                    "label": "BULLISH" if bp >= 0.6 else "BEARISH" if bp <= 0.4 else "MIXED",
                    "src": "news-sentiment"}
    except Exception:
        pass
    # 2) free fallback: company-news → score headlines with the context-aware tone fn
    try:
        from datetime import date, timedelta
        _to = date.today(); _from = _to - timedelta(days=7)
        with urllib.request.urlopen(
                f"https://finnhub.io/api/v1/company-news?symbol={ticker}"
                f"&from={_from}&to={_to}&token={key}", timeout=6) as r:
            arts = _j.loads(r.read().decode())
        bull = bear = 0
        for a in (arts or [])[:40]:
            t = _headline_tone((a.get("headline", "") + " " + a.get("summary", "")))
            if t > 0: bull += 1
            elif t < 0: bear += 1
        if bull + bear > 0:
            return {"bull_pct": bull / (bull + bear) * 100, "buzz": None, "bull": bull, "bear": bear,
                    "label": "BULLISH" if bull > bear * 1.3 else "BEARISH" if bear > bull * 1.3 else "MIXED",
                    "src": "company-news"}
    except Exception:
        pass
    return None


def _gp_writeup(tk, spot, em, walls, r1, s1, dd, th, nw, tlegs, stt=None):
    """Plain-language next-day read for one stock: levels + expected move + news + position risk."""
    cw, pw = walls.get("call_wall"), walls.get("put_wall")
    P = []
    if cw and pw:
        if pw < spot < cw:
            P.append(f"{tk} sits between put-wall ${pw:.0f} (support) and call-wall ${cw:.0f} "
                     "(resistance) — dealers tend to pin price inside this range.")
        elif spot >= cw:
            P.append(f"{tk} is above its call wall ${cw:.0f} — extended; that level often caps or reverses moves.")
        else:
            P.append(f"{tk} is below its put wall ${pw:.0f} — support has broken, momentum is weak.")
    elif cw:
        P.append(f"{tk} faces overhead resistance at the call wall ${cw:.0f}.")
    elif pw:
        P.append(f"{tk} has support at the put wall ${pw:.0f}.")
    else:
        P.append(f"{tk} has no dominant OI wall nearby, so price can roam.")
    P.append(f"Tomorrow's 1-day expected move is about ±${em:.2f} (≈{em/spot*100:.1f}%) — a normal "
             f"session likely stays in ${spot-em:.0f}–${spot+em:.0f}.")
    if nw.get("items"):
        if nw["label"] == "BULLISH":
            P.append(f"News flow leans positive ({nw['bull']} up vs {nw['bear']} down headlines) — supportive "
                     "for the open, though good news can deflate option IV.")
        elif nw["label"] == "BEARISH":
            P.append(f"News flow leans negative ({nw['bear']} down vs {nw['bull']} up headlines) — raises gap-down "
                     "and IV-spike risk overnight.")
        elif nw["label"] == "MIXED":
            P.append(f"News is mixed ({nw['bull']} up / {nw['bear']} down) — no clean catalyst, so the levels above "
                     "should drive the tape.")
        else:
            P.append("Newsflow is quiet — technicals and the walls should dominate.")
    if stt:
        P.append(f"Retail crowd on StockTwits is {stt['label'].lower()} "
                 f"({stt['bull']} bullish / {stt['bear']} bearish).")
        if (nw.get("items") and nw["label"] in ("BULLISH", "BEARISH")
                and stt["label"] in ("BULLISH", "BEARISH") and stt["label"] != nw["label"]):
            P.append("Heads-up: news and the crowd disagree — expect choppier, headline-driven moves.")
    if dd > 0:
        P.append(f"Your {tk} legs are net long (${dd:,.0f} per +1%) — a green open helps; a gap-down is the risk.")
    elif dd < 0:
        P.append(f"Your {tk} legs are net short (${dd:,.0f} per +1%) — a gap-up is the main risk.")
    risks = []
    for l in tlegs:
        money = "ITM" if ((l["spot"] > l["K"]) if l["typ"] == "call" else (l["spot"] < l["K"])) else "OTM"
        if l["side"] == "short" and money == "ITM":
            risks.append(f"short ${_kf(l['K'])}{l['typ'][0].upper()} is ITM (assignment risk)")
        if l["dte"] <= 7:
            risks.append(f"${_kf(l['K'])}{l['typ'][0].upper()} has {l['dte']}DTE (theta/gamma spike)")
    if risks:
        P.append("Watch: " + "; ".join(dict.fromkeys(risks)) + ".")
    if cw and pw and pw < spot < cw and th >= 0:
        P.append("Plan: hold — let the range and time decay work; act only on a clean break of a wall.")
    else:
        P.append("Plan: manage the flagged legs at the open (roll / trim / hedge) per the table below.")
    return " ".join(P)


@st.cache_data(ttl=300, show_spinner=False)
def _macro_backdrop():
    """Live-ish cross-asset/international backdrop via yfinance (futures, vol, FX, rates,
    commodities, China/EM, crypto) with a risk-on/off read. Returns (dict, label, score)."""
    syms = {
        "S&P fut": "ES=F", "Nasdaq fut": "NQ=F", "VIX": "^VIX", "WTI oil": "CL=F",
        "Gold": "GC=F", "Dollar (DXY)": "DX=F", "US 10y": "^TNX",
        "China (FXI)": "FXI", "EM (EEM)": "EEM", "Bitcoin": "BTC-USD",
    }
    out = {}
    for name, sym in syms.items():
        try:
            c = _cached_history(sym, "5d")["Close"].dropna()
            if len(c) >= 2:
                out[name] = {"price": float(c.iloc[-1]),
                             "pct": (float(c.iloc[-1]) / float(c.iloc[-2]) - 1) * 100}
        except Exception:
            continue
    score = 0
    if "S&P fut" in out:
        score += 1 if out["S&P fut"]["pct"] > 0 else -1
    if "VIX" in out:
        score += -1 if out["VIX"]["pct"] > 3 else (1 if out["VIX"]["pct"] < -3 else 0)
    if "Dollar (DXY)" in out:
        score += -1 if out["Dollar (DXY)"]["pct"] > 0.3 else (1 if out["Dollar (DXY)"]["pct"] < -0.3 else 0)
    if "US 10y" in out:
        score += -1 if out["US 10y"]["pct"] > 2 else 0
    label = "RISK-ON" if score >= 2 else ("RISK-OFF" if score <= -2 else "MIXED")
    return out, label, score


@st.cache_data(ttl=600, show_spinner=False)
def _gp_indicators(tk):
    """Technical read for a ticker: each indicator with value, signal, plain explanation,
    and whether to weight it. Computed from cached daily history."""
    h = _cached_history(tk, "14mo")
    if h is None or len(h) < 60:
        return []
    c = h["Close"].dropna()
    v = h["Volume"].fillna(0) if "Volume" in h else pd.Series(0, index=c.index)
    px = float(c.iloc[-1])
    out = []
    for n in (20, 50, 200):
        if len(c) >= n:
            sma = float(c.rolling(n).mean().iloc[-1])
            out.append({"name": f"Price vs SMA{n}", "val": f"${sma:.2f}",
                        "sig": "BULL" if px > sma else "BEAR",
                        "why": f"Price is {'above' if px > sma else 'below'} its {n}-day average → "
                               f"{'up' if px > sma else 'down'}trend on that horizon.",
                        "use": "Trend filter. SMA200 = most reliable (long-term); SMA20 is noisy/short."})
    d = c.diff()
    up = d.clip(lower=0).rolling(14).mean(); dn = (-d.clip(upper=0)).rolling(14).mean()
    rsi = float((100 - 100 / (1 + up / dn.replace(0, np.nan))).iloc[-1])
    out.append({"name": "RSI(14)", "val": f"{rsi:.0f}",
                "sig": "BEAR" if rsi > 70 else "BULL" if rsi < 30 else "NEUTRAL",
                "why": ("Overbought (>70) — pullback risk." if rsi > 70 else
                        "Oversold (<30) — bounce potential." if rsi < 30 else "Neutral momentum."),
                "use": "Strong only at extremes. In trends RSI can stay >70 for weeks — don't fade blindly."})
    macd = c.ewm(span=12).mean() - c.ewm(span=26).mean()
    mv2 = float((macd - macd.ewm(span=9).mean()).iloc[-1])
    out.append({"name": "MACD", "val": f"{mv2:+.2f}", "sig": "BULL" if mv2 > 0 else "BEAR",
                "why": f"MACD is {'above' if mv2 > 0 else 'below'} its signal → "
                       f"{'bullish' if mv2 > 0 else 'bearish'} momentum.",
                "use": "Momentum confirm; lags in chop. Crossovers matter more than level."})
    if {"High", "Low"} <= set(h.columns):
        pc = c.shift(1)
        tr = pd.concat([(h["High"] - h["Low"]), (h["High"] - pc).abs(), (h["Low"] - pc).abs()], axis=1).max(axis=1)
        atr = float(tr.rolling(14).mean().iloc[-1])
        out.append({"name": "ATR(14)", "val": f"${atr:.2f} ({atr/px*100:.1f}%)", "sig": "NEUTRAL",
                    "why": f"Typical daily range ≈ {atr/px*100:.1f}%.",
                    "use": "Risk sizing, NOT direction. Stops tighter than ~1×ATR get whipsawed."})
        tp = (h["High"] + h["Low"] + c) / 3
        vwap = float((tp * v).rolling(20).sum().iloc[-1] / v.rolling(20).sum().replace(0, np.nan).iloc[-1])
        out.append({"name": "VWAP (20d)", "val": f"${vwap:.2f}", "sig": "BULL" if px > vwap else "BEAR",
                    "why": f"Price is {'above' if px > vwap else 'below'} the volume-weighted avg → "
                           f"{'buyers' if px > vwap else 'sellers'} in control (20-day).",
                    "use": "Institutions anchor to VWAP. Daily approximation (no intraday). Above = demand."})
    hi52, lo52 = float(c.max()), float(c.min())
    pos = (px - lo52) / (hi52 - lo52) * 100 if hi52 > lo52 else 50
    out.append({"name": "52-week range", "val": f"{pos:.0f}% of range",
                "sig": "BULL" if pos > 70 else "BEAR" if pos < 30 else "NEUTRAL",
                "why": f"Trading at {pos:.0f}% of its 52-week range.",
                "use": "High = momentum/strength; low = value or falling knife. Pair with trend."})
    if float(v.rolling(20).mean().iloc[-1] or 0) > 0:
        vr = float(v.iloc[-1]) / float(v.rolling(20).mean().iloc[-1])
        out.append({"name": "Volume vs 20d", "val": f"{vr:.1f}×", "sig": "NEUTRAL",
                    "why": f"Last session volume was {vr:.1f}× the 20-day average.",
                    "use": "Confirms moves: breakout on >1.5× volume is real; low-volume moves are suspect."})
    return out


@st.cache_data(ttl=600, show_spinner=False)
def _gp_orderflow(tk):
    """Free options order-flow proxy from the latest stored chain: net OI build (calls vs puts)
    and volume PCR → who's positioning which way."""
    conn = get_conn()
    try:
        df = pd.read_sql(
            "SELECT change_OI_Call, change_OI_Put, vol_Call_now, vol_Put_now FROM options_change "
            "WHERE ticker=? AND trade_date_now=(SELECT trade_date_now FROM options_change "
            "WHERE ticker=? ORDER BY trade_date_now DESC LIMIT 1)", conn, params=(tk.upper(), tk.upper()))
    except Exception:
        df = pd.DataFrame()
    finally:
        conn.close()
    if df.empty:
        return None
    coi = float(pd.to_numeric(df["change_OI_Call"], errors="coerce").sum())
    poi = float(pd.to_numeric(df["change_OI_Put"], errors="coerce").sum())
    cv = float(pd.to_numeric(df["vol_Call_now"], errors="coerce").sum())
    pv = float(pd.to_numeric(df["vol_Put_now"], errors="coerce").sum())
    net = coi - poi
    pcrv = pv / cv if cv else 0.0
    flow = ("BULLISH" if net > 0 and pcrv < 1 else "BEARISH" if (net < 0 or pcrv > 1.3) else "MIXED")
    return {"coi": coi, "poi": poi, "net": net, "cv": cv, "pv": pv, "pcrv": pcrv, "flow": flow}


# intent label → human bucket (buying / selling / hedging)
_OI_BUCKET = {
    "BULLISH":       ("🟢 Bullish call buying",      "Calls accumulating near/at-the-money — directional upside bets."),
    "BULLISH_BREAK": ("🟢 Bullish call buying",      "Calls building above spot — breakout/upside positioning."),
    "BEARISH":       ("🔴 Bearish put buying",       "Puts accumulating at-the-money — directional downside bets."),
    "NEAR_BEARISH":  ("🔴 Bearish put buying",       "Puts building just below spot — bearish lean."),
    "HEDGE":         ("🔵 Downside hedging",         "Deep-OTM puts added — protective insurance, NOT directional shorts."),
    "HEDGE_UNWIND":  ("🔵 Hedge unwind",             "Protective puts being removed — risk appetite returning."),
    "COVERED_CALL":  ("🟡 Call selling (overwrite)", "Far-OTM calls added — likely covered-call income / supply, caps upside."),
    "STRADDLE":      ("🟣 Vol / straddle",           "Both sides built at-the-money — event/vol play, not direction."),
    "UNWIND":        ("⚪ Position unwind",           "OI falling both sides — positions closing, conviction fading."),
    "NEUTRAL":       ("⚪ Neutral / balanced",        "No clear opening flow."),
}


@st.cache_data(ttl=120, show_spinner=False)
def _gp_oi_analytics(tk, spot):
    """Deep options-flow analytics from the latest stored chain: classifies opening flow as
    buying / selling / hedging per strike (via the hedge-aware intent algo), shows the biggest
    ΔOI strikes within the front expiry (across-strike), and net ΔOI per expiry (across-expiry /
    calendar). Returns a dict for rendering, or None."""
    if not spot or spot <= 0:
        return None
    conn = get_conn()
    try:
        df = pd.read_sql(
            "SELECT strike, expiry_date, change_OI_Call, change_OI_Put, "
            "openInt_Call_now, openInt_Put_now, vol_Call_now, vol_Put_now FROM options_change "
            "WHERE ticker=? AND trade_date_now=(SELECT trade_date_now FROM options_change "
            "WHERE ticker=? ORDER BY trade_date_now DESC LIMIT 1)", conn, params=(tk.upper(), tk.upper()))
    except Exception:
        df = pd.DataFrame()
    finally:
        conn.close()
    if df.empty:
        return None
    for c in df.columns:
        if c != "expiry_date":
            df[c] = pd.to_numeric(df[c], errors="coerce").fillna(0.0)

    # ── per-strike intent (buying/selling/hedging), aggregated over all expiries ──
    bystrike = df.groupby("strike", as_index=False).agg(
        call_oi_change=("change_OI_Call", "sum"), put_oi_change=("change_OI_Put", "sum"))
    enr, isig, _icol, idesc, idet = _oi_intent_algo(bystrike, spot)
    enr["flow_wt"] = enr["call_oi_change"].abs() + enr["put_oi_change"].abs()
    buckets = {}
    for _, rr in enr.iterrows():
        lbl, why = _OI_BUCKET.get(rr["intent"], _OI_BUCKET["NEUTRAL"])
        b = buckets.setdefault(lbl, {"wt": 0.0, "why": why})
        b["wt"] += float(rr["flow_wt"])
    tot_wt = sum(b["wt"] for b in buckets.values()) or 1.0
    bucket_rows = sorted(
        ({"Flow type": k, "% of activity": round(v["wt"] / tot_wt * 100, 1),
          "What it signals": v["why"]} for k, v in buckets.items() if v["wt"] > 0),
        key=lambda r: r["% of activity"], reverse=True)

    # ── across-strike: biggest ΔOI strikes (front-most expiry only) ──
    def _exp_key(s):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%m-%d-%Y", "%Y/%m/%d"):
            try:
                return datetime.strptime(str(s), fmt)
            except Exception:
                continue
        return datetime.max
    exps = sorted(df["expiry_date"].unique(), key=_exp_key)
    front = exps[0] if exps else None
    fdf = df[df["expiry_date"] == front].copy() if front else df.copy()
    fdf["net"] = fdf["change_OI_Call"] - fdf["change_OI_Put"]
    fdf["tot_chg"] = fdf["change_OI_Call"].abs() + fdf["change_OI_Put"].abs()
    top_strikes = fdf.sort_values("tot_chg", ascending=False).head(8)
    strike_rows = [{
        "Strike": f"${_kf(r['strike'])}",
        "vs spot": f"{(r['strike']/spot-1)*100:+.1f}%",
        "Call ΔOI": int(r["change_OI_Call"]), "Put ΔOI": int(r["change_OI_Put"]),
        "Read": ("call build" if r["change_OI_Call"] > abs(r["change_OI_Put"]) and r["change_OI_Call"] > 0
                 else "put build" if r["change_OI_Put"] > abs(r["change_OI_Call"]) and r["change_OI_Put"] > 0
                 else "unwind" if r["change_OI_Call"] < 0 and r["change_OI_Put"] < 0 else "mixed"),
    } for _, r in top_strikes.iterrows()]

    # ── across-expiry (calendar): where new OI is going ──
    cal = df.groupby("expiry_date", as_index=False).agg(
        call=("change_OI_Call", "sum"), put=("change_OI_Put", "sum"))
    cal["__k"] = cal["expiry_date"].map(_exp_key)
    cal = cal.sort_values("__k")
    today = datetime.now()
    cal_rows = [{
        "Expiry": str(r["expiry_date"]),
        "DTE": max((_exp_key(r["expiry_date"]) - today).days, 0),
        "Call ΔOI": int(r["call"]), "Put ΔOI": int(r["put"]),
        "Net": int(r["call"] - r["put"]),
    } for _, r in cal.iterrows()]
    # front vs back tilt
    if len(cal) >= 2:
        half = cal["__k"].median()
        fb = cal[cal["__k"] <= half]; bk = cal[cal["__k"] > half]
        front_net = float((fb["call"] - fb["put"]).sum())
        back_net = float((bk["call"] - bk["put"]).sum())
        cal_tilt = ("Most new positioning is in NEAR expiries — short-dated, tactical."
                    if abs(front_net) > abs(back_net)
                    else "New positioning skews to LATER expiries — longer-horizon conviction.")
    else:
        front_net = back_net = 0.0
        cal_tilt = "Only one expiry has flow."

    return {"intent_sig": isig, "intent_desc": idesc, "hedge_pct": idet.get("hedge_pct", 0),
            "buckets": bucket_rows, "front": front, "strikes": strike_rows,
            "calendar": cal_rows, "cal_tilt": cal_tilt,
            "front_net": front_net, "back_net": back_net}


@st.cache_data(ttl=300, show_spinner=False)
def _gp_patterns(tk, spot, put_wall=None, call_wall=None):
    """Technical-pattern checklist: EMA sequence (8/21/50 stacking), golden/death cross
    (50/200 DMA), bull/bear flag continuation, and dealer gamma regime (positive = pinned/
    mean-revert, negative 'golden gamma' = moves amplified). Returns list of dicts
    {name, val, sig, why, use}."""
    out = []
    try:
        h = _cached_history(tk, "1y")
        c = h["Close"].dropna() if (h is not None and "Close" in getattr(h, "columns", [])) else pd.Series(dtype=float)
    except Exception:
        c = pd.Series(dtype=float)
    if len(c) >= 30:
        px = float(c.iloc[-1])
        e8 = float(c.ewm(span=8).mean().iloc[-1])
        e21 = float(c.ewm(span=21).mean().iloc[-1])
        e50 = float(c.ewm(span=50).mean().iloc[-1])
        if e8 > e21 > e50 and px >= e8:
            _s, _w = "BULL", "8>21>50 EMAs stacked up & price on top — clean uptrend sequence."
        elif e8 < e21 < e50 and px <= e8:
            _s, _w = "BEAR", "8<21<50 EMAs stacked down & price below — bearish EMA sequence."
        else:
            _s, _w = "NEUTRAL", "EMAs tangled — no clean trend sequence."
        out.append({"name": "EMA sequence (8/21/50)", "val": f"{e8:.1f}/{e21:.1f}/{e50:.1f}",
                    "sig": _s, "why": _w,
                    "use": "Trade with the stack; avoid counter-trend entries when cleanly stacked."})
        # golden / death cross (50 vs 200 DMA)
        if len(c) >= 200:
            s50 = c.rolling(50).mean(); s200 = c.rolling(200).mean()
            a50, a200 = float(s50.iloc[-1]), float(s200.iloc[-1])
            p50, p200 = float(s50.iloc[-6]), float(s200.iloc[-6])
            if a50 > a200:
                gs = "BULL"
                gw = ("Fresh GOLDEN CROSS (50-DMA just crossed above 200) — bullish regime shift."
                      if p50 <= p200 else "50-DMA above 200-DMA (golden-cross regime) — long-term bull.")
            else:
                gs = "BEAR"
                gw = ("Fresh DEATH CROSS (50-DMA just crossed below 200) — bearish regime shift."
                      if p50 >= p200 else "50-DMA below 200-DMA (death-cross regime) — long-term bear.")
            out.append({"name": "Golden/Death cross (50/200)", "val": f"{a50:.0f}/{a200:.0f}",
                        "sig": gs, "why": gw,
                        "use": "Defines the dominant regime; trade pullbacks in its direction."})
        # bull / bear flag continuation
        if len(c) >= 25:
            pole = px / float(c.iloc[-21]) - 1
            last5 = c.iloc[-5:]
            drift = float(last5.iloc[-1] / last5.iloc[0] - 1)
            rng = float((last5.max() - last5.min()) / last5.mean())
            if pole > 0.08 and -0.04 < drift <= 0.01 and rng < 0.06:
                out.append({"name": "Bull flag (continuation)", "val": f"pole {pole*100:+.0f}%",
                            "sig": "BULL",
                            "why": "Strong up-move then a tight, slightly-down pause — classic bull flag; "
                                   "breakouts usually resolve UP.",
                            "use": "Look for a break above the flag high to add/hold longs."})
            elif pole < -0.08 and -0.01 <= drift < 0.04 and rng < 0.06:
                out.append({"name": "Bear flag (continuation)", "val": f"pole {pole*100:+.0f}%",
                            "sig": "BEAR",
                            "why": "Sharp down-move then a tight, slightly-up bounce — bear-flag "
                                   "continuation; usually resolves DOWN.",
                            "use": "A break below the flag low favors staying short / cutting longs."})
    # dealer gamma regime ("golden gamma" flip)
    if put_wall and call_wall and spot:
        flip = (float(put_wall) + float(call_wall)) / 2.0
        if spot < min(float(put_wall), flip):
            out.append({"name": "Dealer gamma regime", "val": f"flip ≈ ${flip:.0f}", "sig": "BEAR",
                        "why": f"Spot ${spot:.0f} is BELOW the gamma-flip (~${flip:.0f}) → **negative gamma**: "
                               "dealers hedge *with* the move, amplifying swings (especially downside).",
                        "use": "Expect bigger, trendier moves; respect stops, fade less."})
        elif spot > max(float(call_wall), flip):
            out.append({"name": "Dealer gamma regime", "val": f"flip ≈ ${flip:.0f}", "sig": "BULL",
                        "why": f"Spot is above the call wall — stretched; dealers may cap further upside.",
                        "use": f"Chase less; watch for mean-reversion back toward ${flip:.0f}."})
        else:
            out.append({"name": "Dealer gamma regime", "val": f"pinned ${float(put_wall):.0f}–${float(call_wall):.0f}",
                        "sig": "NEUTRAL",
                        "why": f"Spot is between the put/call walls → **positive gamma**: dealers fade moves, "
                               f"price tends to pin / mean-revert toward ${flip:.0f}.",
                        "use": "Favor range / premium-selling; breakouts need volume to stick."})
    return out


def _gp_debate(tk, tl, spot, em, dd, th, w, nw, stt, ivr, earn):
    """Both-sides assessment: reasons to HOLD vs reasons to CLOSE/adjust, then a verdict."""
    holds, closes = [], []
    pnl = sum(x["pnl"] for x in tl)
    min_dte = min(x["dte"] for x in tl)
    has_short = any(x["side"] == "short" for x in tl)
    short_itm = any(x["side"] == "short" and ((spot > x["K"]) if x["typ"] == "call" else (spot < x["K"])) for x in tl)
    # HOLD case
    if th > 0:
        holds.append(f"You **collect ${th:,.0f}/day** in theta — time decay works *for* you.")
    if th < 0 and min_dte > 21:
        holds.append(f"Long premium but **{min_dte} DTE** left — the thesis still has time to play out.")
    if w.get("put_wall") and w.get("call_wall") and w["put_wall"] < spot < w["call_wall"]:
        holds.append(f"Spot is **pinned between ${w['put_wall']:.0f}–${w['call_wall']:.0f} walls** → range-bound, "
                     "which favors holding (esp. short premium).")
    if ivr and ivr.get("rank", 50) < 30 and th < 0:
        holds.append(f"IV is **cheap (rank {ivr['rank']:.0f})** — your long options aren't overpaying.")
    if stt and stt.get("label") == "BULLISH" and dd > 0:
        holds.append("Crowd is bullish and your book is net-long — sentiment aligns.")
    # CLOSE case
    if min_dte <= 7:
        closes.append(f"**{min_dte} DTE** — gamma/theta risk spikes into expiry; decide now.")
    if th < 0:
        closes.append(f"You **pay ${abs(th):,.0f}/day** in decay — it bleeds unless the move comes soon.")
    if pnl >= 0.5 * sum(abs(x["entry"] * x["m"]) for x in tl if x["side"] == "long") and pnl > 0:
        closes.append(f"Open P&L **${pnl:,.0f}** — consider locking gains / taking profit.")
    if short_itm:
        closes.append("A **short leg is ITM** — assignment risk; roll or close it.")
    if ivr and ivr.get("rank", 50) > 70 and th < 0:
        closes.append(f"IV is **rich (rank {ivr['rank']:.0f})** — long premium is overpaying; roll down/out.")
    if earn and earn.get("days", 99) <= min_dte:
        closes.append(f"**Earnings in {earn['days']}d** (before expiry) — binary gap risk.")
    if nw and nw.get("label") == "BEARISH" and dd > 0:
        closes.append("News skews bearish while you're net-long — headline gap-down risk.")
    if nw and nw.get("label") == "BULLISH" and dd < 0:
        closes.append("News skews bullish while you're net-short — squeeze/gap-up risk.")
    # verdict
    if len(closes) >= len(holds) + 2 or short_itm or min_dte <= 3:
        verdict = "⚠️ **Lean CLOSE / adjust** — risks outweigh the carry here."
    elif len(holds) >= len(closes) + 1:
        verdict = "✅ **Lean HOLD** — the structure still works in your favor."
    else:
        verdict = "🟡 **Lean TRIM** — take some off, keep a runner; it's balanced."
    return holds, closes, verdict


def _gp_levels_fig(tk, spot, w, r1, s1, em):
    """Horizontal bar chart of key levels: each level is a bar at its price, ordered high→low
    (resistance on top, support on bottom), green below spot / red above, with the spot line and
    the shaded 1-day expected-move band. Bar labels show price + % distance from spot."""
    rows = []
    seen = set()
    for nm, x in (("🟥 Call wall", w.get("call_wall")), ("R1 resistance", r1),
                  ("⚪ Spot (now)", spot), ("S1 support", s1), ("🟩 Put wall", w.get("put_wall"))):
        if not x or round(x, 2) in seen:
            continue
        seen.add(round(x, 2))
        rows.append((nm, float(x)))
    rows.sort(key=lambda r: r[1])                       # low → high (Plotly bars stack bottom→top)
    names = [r[0] for r in rows]
    prices = [r[1] for r in rows]

    # User ask 2026-07-27: the spot bar/line were plain white, which vanishes against this
    # chart's white plot background (both app themes render this panel white) -- switched to
    # a high-contrast navy so "now" is actually visible instead of blending in.
    _SPOT_COLOR = "#1a237e"

    def _col(nm, x):
        if "Spot" in nm:
            return _SPOT_COLOR
        return "#00e676" if x < spot else "#ff5c6c"
    cols = [_col(nm, x) for nm, x in rows]
    labels = [f"${x:,.0f}  ({(x/spot-1)*100:+.1f}%)" if "Spot" not in nm else f"${x:,.0f}  ← now"
              for nm, x in rows]

    fig = go.Figure(go.Bar(
        x=prices, y=names, orientation="h", marker_color=cols,
        text=labels, textposition="outside", cliponaxis=False, textfont=dict(size=15),
        hovertemplate="%{y}: $%{x:,.2f}<extra></extra>"))
    if em:
        # User report 2026-07-27 (screenshot, both light+dark theme): this in-plot annotation
        # sat right where the Call wall / R1 outside-bar labels land whenever those two prices
        # are close together, so all three overlapped into one unreadable cluster -- not really
        # a color bug, a text-collision bug (the light-blue annotation was just the hardest of
        # the three to make out once stacked). Dropped the in-plot annotation entirely; the
        # ±$ figure is shown as a plain st.caption below the chart instead (see call site),
        # which can never collide with a bar label and always uses the app's own text color.
        fig.add_vrect(x0=spot - em, x1=spot + em, fillcolor="rgba(61,139,255,0.16)", line_width=0)
    fig.add_vline(x=spot, line_color=_SPOT_COLOR, line_width=2.5, line_dash="dot")
    _lo = min(prices + [spot - (em or 0)]); _hi = max(prices + [spot + (em or 0)])
    _pad = (_hi - _lo) * 0.12 or spot * 0.02
    fig.update_layout(template="plotly_dark", height=260, margin=dict(t=36, b=30, l=10, r=10),
                      title=dict(text=f"{tk} — key levels vs spot", font=dict(size=16)),
                      xaxis=dict(title=dict(text="Price ($)", font=dict(size=13)),
                                 range=[_lo - _pad, _hi + _pad * 1.6], showgrid=False,
                                 tickfont=dict(size=12)),
                      yaxis=dict(title="", tickfont=dict(size=13)),
                      showlegend=False, bargap=0.45)
    return fig


