def _ahf_analyst_signals(F, ticker):
    """Analyst-desk agents: Valuation, Fundamentals, Technicals, Sentiment."""
    g = F.get
    out = []
    # Valuation
    out.append(("📐 Valuation", _ahf_tally([
        _v(None if g("upside") is None else g("upside") > 0.10, f"{(g('upside') or 0)*100:+.0f}% to mean target", f"{(g('upside') or 0)*100:+.0f}% to target"),
        _v(None if g("fcf_yield") is None else g("fcf_yield") > 0.05, "attractive FCF yield", "low FCF yield"),
        _v(None if g("graham_num") is None or g("price") is None else g("price") < g("graham_num"), "below Graham value", "above Graham value"),
    ])))
    # Fundamentals
    out.append(("🏛 Fundamentals", _ahf_tally([
        _v(None if g("roe") is None else g("roe") > 0.12, "profitable (ROE)", "low ROE"),
        _v(None if g("rg") is None else g("rg") > 0.08, "growing", "stagnant"),
        _v(None if g("de") is None else g("de") < 120, "healthy balance sheet", "leveraged"),
        _v(None if g("om") is None else g("om") > 0.10, "good margins", "weak margins"),
    ])))
    # Technicals
    out.append(("📈 Technicals", _ahf_tally([
        _v(g("above200"), "above 200-DMA", "below 200-DMA"),
        _v(None if g("mom6") is None else g("mom6") > 0, f"6-mo trend {(g('mom6') or 0)*100:+.0f}%", f"6-mo trend {(g('mom6') or 0)*100:+.0f}%"),
    ])))
    # Sentiment (reuse free sources)
    sv = []
    try:
        nw = _ticker_news(ticker)
        if nw:
            sv.append(_v(nw["label"] == "BULLISH" if nw["label"] in ("BULLISH", "BEARISH") else None,
                         "news tone bullish", "news tone bearish"))
    except Exception:
        pass
    try:
        stt = _stocktwits_sentiment(ticker)
        if stt:
            sv.append(_v(stt["label"] == "BULLISH" if stt["label"] in ("BULLISH", "BEARISH") else None,
                         "crowd bullish", "crowd bearish"))
    except Exception:
        pass
    out.append(("💬 Sentiment", _ahf_tally(sv)))
    return out


def _ahf_risk(F, ticker):
    """Risk Manager: volatility/beta-based risk level + suggested max position size & stop."""
    atrp = None
    try:
        h = _cached_history(ticker, "3mo")
        c = h["Close"]; pc = c.shift(1)
        tr = pd.concat([(h["High"] - h["Low"]), (h["High"] - pc).abs(), (h["Low"] - pc).abs()], axis=1).max(axis=1)
        atrp = float(tr.rolling(14).mean().iloc[-1] / c.iloc[-1])
    except Exception:
        pass
    beta = F.get("beta")
    if (atrp and atrp > 0.04) or (beta and beta > 1.5):
        level = "HIGH"
    elif (atrp and atrp < 0.02) and (not beta or beta < 1.0):
        level = "LOW"
    else:
        level = "MEDIUM"
    max_pos = {"HIGH": 5, "MEDIUM": 10, "LOW": 15}[level]
    return {"atrp": atrp, "beta": beta, "level": level, "max_pos": max_pos,
            "stop": (atrp * 2) if atrp else None}


@st.cache_data(ttl=600, show_spinner=False)
def _ahf_run(ticker):
    """Run the whole desk: investor personas + analyst agents + risk + portfolio manager."""
    F = _ahf_fundamentals(ticker)
    if not F:
        return None
    personas = [{"agent": nm, **fn(F)} for nm, fn in _AHF_AGENTS]
    analysts = [{"agent": nm, **sig} for nm, sig in _ahf_analyst_signals(F, ticker)]
    risk = _ahf_risk(F, ticker)
    allsig = personas + analysts
    bull = sum(a["signal"] == "BULLISH" for a in allsig)
    bear = sum(a["signal"] == "BEARISH" for a in allsig)
    neu = len(allsig) - bull - bear
    net = bull - bear
    if net >= 4:
        action = "BUY"
    elif net <= -4:
        action = "AVOID / SELL"
    else:
        action = "HOLD / WATCH"
    conf = min(95, 50 + abs(net) * 5)
    size = risk["max_pos"] if action == "BUY" else (0 if action.startswith("AVOID") else round(risk["max_pos"] / 2))
    return {"F": F, "personas": personas, "analysts": analysts, "risk": risk,
            "bull": bull, "bear": bear, "neu": neu, "net": net,
            "action": action, "conf": conf, "size": size}


@st.cache_data(ttl=120, show_spinner=False)
def _cached_hp_engine(ticker):
    """Cached 24-model engine (telegram_bot.high_prob_signals_engine) so the Game Plan's deep
    analysis doesn't re-run all 24 models on every rerun / 30s auto-refresh. OI is EOD so a
    2-min cache loses nothing."""
    try:
        import telegram_bot_optimized as _tbe
        conn = get_conn()
        try:
            return _tbe.high_prob_signals_engine(ticker, conn)
        finally:
            conn.close()
    except Exception:
        return None


def _render_ahf_pretrade(ticker, key=""):
    """Compact 'should I take this?' pre-trade check (reuses the AI Hedge Fund committee):
    one-line verdict + risk + suggested size, expandable to the per-agent vote. Drop-in for
    any tab that surfaces a trade idea."""
    if not ticker:
        return
    res = _ahf_run(str(ticker).upper())
    if not res:
        st.caption(f"🧑‍💼 Pre-trade check: no fundamentals for {ticker} (ETF/index or not covered).")
        return
    _ac = {"BUY": "🟢", "HOLD / WATCH": "🟡", "AVOID / SELL": "🔴"}.get(res["action"], "⚪")
    _rk = res["risk"]; _rkc = {"LOW": "🟢", "MEDIUM": "🟡", "HIGH": "🔴"}.get(_rk["level"], "⚪")
    with st.expander(f"🧑‍💼 Pre-trade check — {_ac} **{res['action']}** ({res['conf']:.0f}%) · "
                     f"{res['bull']}🟢/{res['bear']}🔴 agents · {_rkc} {_rk['level']} risk · "
                     f"size ≤{_rk['max_pos']}%", expanded=False):
        st.markdown(
            (f"Committee on **{str(ticker).upper()}**: **{res['bull']} bullish / {res['bear']} bearish / "
             f"{res['neu']} neutral** → **{res['action']}**"
             + (f" · suggest **{res['size']}%** of book" if res["size"] else "")
             + (f" · stop ≈ {_rk['stop']*100:.0f}% " if _rk["stop"] else "")).replace("$", "\\$"))
        _pe = {"BULLISH": "🟢", "BEARISH": "🔴", "NEUTRAL": "⚪"}
        _pinned_df(pd.DataFrame([
            {"Investor": p["agent"], "Call": f"{_pe[p['signal']]} {p['signal']}", "Why": p["reason"]}
            for p in res["personas"]]), hide_index=True, use_container_width=True)
        st.caption("Fundamental committee view — pair with the OI/flow read above. Full detail on the "
                   "🧑‍💼 AI Hedge Fund page. Educational, not advice.")


def _bs_price_vec(S, K, T, r, sigma, typ):
    """Vectorized Black-Scholes price over an array of spots (for Monte Carlo)."""
    S = np.maximum(S, 1e-9)
    if T <= 0:
        return np.maximum(S - K, 0.0) if typ == "call" else np.maximum(K - S, 0.0)
    d1 = (np.log(S / K) + (r + 0.5 * sigma ** 2) * T) / (sigma * np.sqrt(T))
    d2 = d1 - sigma * np.sqrt(T)
    if typ == "call":
        return S * norm.cdf(d1) - K * np.exp(-r * T) * norm.cdf(d2)
    return K * np.exp(-r * T) * norm.cdf(-d2) - S * norm.cdf(-d1)


def _gp_montecarlo(legs, horizon_days=1, n=10000, rho=0.6, r=0.045):
    """Monte Carlo P&L distribution for the whole book: GBM per underlying (annualized IV),
    correlated through a shared market factor (rho), options repriced with BS at the horizon."""
    dt = max(horizon_days, 0) / 252.0
    zm = np.random.standard_normal(n)
    tot = np.zeros(n)
    for l in legs:
        zi = np.random.standard_normal(n)
        z = rho * zm + np.sqrt(max(1 - rho * rho, 0.0)) * zi
        st_ = l["spot"] * np.exp(-0.5 * l["iv"] ** 2 * dt + l["iv"] * np.sqrt(dt) * z)
        t2 = max(l["dte"] - horizon_days, 0) / 365.0
        if l["typ"] == "stock" or not l.get("K"):
            val = st_                                  # shares: worth the simulated price itself
        else:
            val = _bs_price_vec(st_, l["K"], t2, r, l["iv"], l["typ"])
        tot += (val - l["cur"]) * l["m"]
    return {"mean": float(tot.mean()), "p_profit": float((tot > 0).mean() * 100),
            "p5": float(np.percentile(tot, 5)), "p50": float(np.percentile(tot, 50)),
            "p95": float(np.percentile(tot, 95)), "worst": float(tot.min()),
            "best": float(tot.max()), "samples": tot, "n": n, "horizon": horizon_days}


def _combo_bounds(legs, spot, n=600):
    """Theoretical max profit / max loss of a set of legs held to EXPIRY, scanned over an
    underlying-price grid. Flags unbounded upside profit (naked long call) or unbounded loss
    (naked short call). Works for one leg (strike level) or many (position/portfolio level)."""
    if not legs or not spot or spot <= 0:
        return None
    ks = [float(l["K"]) for l in legs if float(l["K"]) > 0] or [spot]
    hi = max(3.0 * spot, max(ks) * 1.5, spot + 1.0)
    grid = np.linspace(0.01, hi, n)
    pnl = np.zeros(n)
    for l in legs:
        if l["typ"] == "stock":                      # shares: linear value = price itself
            intr = grid
        else:
            intr = (np.maximum(grid - l["K"], 0.0) if l["typ"] == "call"
                    else np.maximum(l["K"] - grid, 0.0))
        pnl += (intr - l["entry"]) * l["m"]
    slope_top = float(pnl[-1] - pnl[-2])
    return {"max_profit": float(pnl.max()), "max_loss": float(pnl.min()),
            "up_profit_unlimited": slope_top > 1e-6,    # rising at top = unlimited upside (long call)
            "up_loss_unlimited": slope_top < -1e-6}     # falling at top = unlimited loss (short call)


def _fmt_maxp(b):
    """'Unlimited' for uncapped upside, else $max_profit."""
    if not b:
        return "—"
    return "Unlimited" if b["up_profit_unlimited"] else f"${b['max_profit']:,.0f}"


def _fmt_maxl(b):
    """'Unlimited' for uncapped downside loss, else $max_loss."""
    if not b:
        return "—"
    return "Unlimited" if b["up_loss_unlimited"] else f"${b['max_loss']:,.0f}"


def _exit_sequence(legs, spot):
    """Rank legs by how urgently to CLOSE them (capture profit / cut risk first). Returns a
    score-sorted list of dicts with the leg, an urgency score, the reason, and its bounds."""
    rows = []
    for l in legs:
        b = _combo_bounds([l], spot) or {"max_profit": 0.0, "max_loss": 0.0,
                                         "up_profit_unlimited": False, "up_loss_unlimited": False}
        maxp = b["max_profit"]
        cap = (l["pnl"] / maxp) if maxp > 1e-6 else (1.0 if l["pnl"] > 0 else 0.0)
        itm = (spot > l["K"]) if l["typ"] == "call" else (spot < l["K"])
        pnl_pct = ((l["cur"] - l["entry"]) / l["entry"] * 100 * (1 if l["qty"] > 0 else -1)) if l["entry"] else 0.0
        score = 0.0; why = []
        if l["side"] == "short" and itm and l["dte"] <= 10:
            score += 4.0; why.append("short ITM near expiry — assignment risk")
        if l["dte"] <= 5:
            score += 2.5; why.append(f"{l['dte']}DTE — expiry risk")
        if l["pnl"] > 0 and cap >= 0.6:
            score += 2.5; why.append(f"{cap*100:.0f}% of max profit captured — little left to gain")
        elif l["pnl"] > 0 and l["dte"] <= 10:
            score += 1.5; why.append("in profit into expiry — lock it")
        if pnl_pct <= -50 and l["dte"] <= 21:
            score += 1.5; why.append("down ≥50% with limited time — cut / roll")
        if l.get("pos_theta", 0) < 0 and l["pnl"] < 0 and l["dte"] <= 30:
            score += 0.5; why.append("paying theta while losing")
        rows.append({"leg": l, "score": score, "cap": cap, "bounds": b,
                     "why": "; ".join(why) if why else "no urgency — hold / let it work"})
    rows.sort(key=lambda r: r["score"], reverse=True)
    return rows


def _pos_analytics(legs, spot, r=0.045):
    """Breakeven(s), probability-of-profit (POP) and expected value (EV) for a set of legs,
    evaluated at the NEAREST expiry horizon using an IV-implied lognormal terminal distribution.
    Also returns the P&L-vs-price curve for the payoff chart. P&L is measured from ENTRY."""
    if not legs or not spot or spot <= 0:
        return None
    iv = float(np.median([max(l["iv"], 0.01) for l in legs]))
    h_dte = max(min(l["dte"] for l in legs), 0)
    if h_dte > 400:                       # stock-only group (shares carry dte=9999) → 30d horizon
        h_dte = 30
    T = max(h_dte, 0.5) / 365.0
    sig = max(iv * np.sqrt(T), 1e-4)
    grid = np.linspace(max(spot * np.exp(-4 * sig), 0.01), spot * np.exp(4 * sig), 501)
    pnl = np.zeros_like(grid)
    for l in legs:
        if l["typ"] == "stock":                      # shares: value = terminal price, no decay
            pnl += (grid - l["entry"]) * l["m"]
            continue
        rem = max(l["dte"] - h_dte, 0) / 365.0
        if rem <= 0:
            val = np.maximum(grid - l["K"], 0.0) if l["typ"] == "call" else np.maximum(l["K"] - grid, 0.0)
        else:
            val = _bs_price_vec(grid, l["K"], rem, r, l["iv"], l["typ"])
        pnl += (val - l["entry"]) * l["m"]
    mu = np.log(spot) + (r - 0.5 * iv * iv) * T
    pdf = np.exp(-(np.log(grid) - mu) ** 2 / (2 * sig * sig)) / (grid * sig * np.sqrt(2 * np.pi))
    w = pdf / pdf.sum()
    pop = float(w[pnl > 0].sum()) * 100.0
    ev = float((w * pnl).sum())
    bes = []
    for i in range(1, len(grid)):
        if pnl[i - 1] == 0 or pnl[i] == 0 or (pnl[i - 1] < 0) == (pnl[i] < 0):
            continue
        x0, x1, y0, y1 = grid[i - 1], grid[i], pnl[i - 1], pnl[i]
        bes.append(float(x0 - y0 * (x1 - x0) / (y1 - y0)))
    return {"pop": pop, "ev": ev, "breakevens": bes, "grid": grid, "pnl": pnl,
            "horizon_dte": h_dte, "iv": iv, "spot": spot}


def _pos_payoff_fig(tk, a):
    """Interactive payoff diagram: P&L vs underlying price with profit (green) / loss (red)
    zones, the spot marker and breakeven lines — an at-a-glance read on the position."""
    grid, pnl = a["grid"], a["pnl"]
    pos = np.where(pnl >= 0, pnl, np.nan)
    neg = np.where(pnl < 0, pnl, np.nan)
    fig = go.Figure()
    fig.add_trace(go.Scatter(x=grid, y=pos, fill="tozeroy", line=dict(color="#00e676", width=2),
                             name="profit", hovertemplate="$%{x:.0f} → $%{y:,.0f}<extra></extra>"))
    fig.add_trace(go.Scatter(x=grid, y=neg, fill="tozeroy", line=dict(color="#ff5c6c", width=2),
                             name="loss", hovertemplate="$%{x:.0f} → $%{y:,.0f}<extra></extra>"))
    fig.add_hline(y=0, line_color="#888")
    fig.add_vline(x=a["spot"], line_color="#ffffff", line_dash="dot",
                  annotation_text=f"now ${a['spot']:.0f}", annotation_position="top")
    for be in a["breakevens"]:
        fig.add_vline(x=be, line_color="#ffd54f", line_dash="dash",
                      annotation_text=f"B/E ${be:.0f}", annotation_position="bottom")
    fig.update_layout(template="plotly_dark", height=300, showlegend=False,
                      title=f"{tk} payoff by {a['horizon_dte']}DTE · POP {a['pop']:.0f}% · EV ${a['ev']:,.0f}",
                      xaxis_title="Underlying price", yaxis_title="Position P&L ($)",
                      margin=dict(t=46, b=10))
    return fig


@st.cache_data(ttl=3600, show_spinner=False)
def _beta_to_spy(ticker, lookback=60):
    """Beta of a ticker's daily returns vs SPY from stored stock_daily history (or None)."""
    sk = "trade_date"
    conn = get_conn()
    try:
        a = pd.read_sql(f"SELECT trade_date, close FROM stock_daily WHERE ticker=? ORDER BY {sk}",
                        conn, params=(ticker.upper(),))
        s = pd.read_sql(f"SELECT trade_date, close FROM stock_daily WHERE ticker='SPY' ORDER BY {sk}", conn)
    except Exception:
        return None
    finally:
        conn.close()
    if len(a) < 20 or len(s) < 20:
        return None
    m = a.merge(s, on="trade_date", suffixes=("", "_spy")).tail(lookback + 1)
    if len(m) < 20:
        return None
    ra = pd.to_numeric(m["close"], errors="coerce").pct_change().dropna().values
    rs = pd.to_numeric(m["close_spy"], errors="coerce").pct_change().dropna().values
    n = min(len(ra), len(rs))
    if n < 15 or np.var(rs[-n:]) <= 0:
        return None
    return float(np.cov(ra[-n:], rs[-n:])[0, 1] / np.var(rs[-n:]))


@st.cache_data(ttl=3600, show_spinner=False)
def _corr_matrix(tickers):
    """Pairwise return-correlation matrix of the given tickers from stock_daily; also the
    average off-diagonal correlation (a concentration/diversification gauge)."""
    import itertools
    sk = "trade_date"
    conn = get_conn()
    try:
        frames = {}
        for t in tickers:
            d = pd.read_sql(f"SELECT trade_date, close FROM stock_daily WHERE ticker=? ORDER BY {sk}",
                            conn, params=(t.upper(),))
            if len(d) > 20:
                frames[t] = pd.to_numeric(d["close"], errors="coerce").pct_change().values[-60:]
    except Exception:
        return None
    finally:
        conn.close()
    if len(frames) < 2:
        return None
    n = min(len(v) for v in frames.values())
    df = pd.DataFrame({t: v[-n:] for t, v in frames.items()}).dropna()
    if len(df) < 10:
        return None
    c = df.corr()
    vals = [c.loc[x, y] for x, y in itertools.combinations(c.columns, 2)]
    return {"matrix": c, "avg": float(np.mean(vals)) if vals else 0.0}


def _gp_order_tickets(tl, spot, w, r=0.045):
    """Concrete, ready-to-place order ideas per leg:
    • longs → a 'sell to reduce cost' overlay (sell the call/put wall = GEX resistance → turns it
      into a spread, lowering net cost) plus the modeled MAX value if price reaches its wall / 1σ.
    • shorts → a buy-to-close ticket. Premiums are per-share BS estimates at current IV."""
    if not tl or not spot:
        return []
    tips = []
    iv_med = float(np.median([max(l["iv"], 0.01) for l in tl]))
    h = min(max(min(l["dte"] for l in tl), 1), 10)          # ~1–2 week working horizon
    em = spot * iv_med * np.sqrt(h / 365.0)
    for l in tl:
        if l["typ"] == "stock" or not l.get("K"):      # shares: no strikes to roll/spread
            continue
        K, typ, iv, dte, q, exp = l["K"], l["typ"], max(l["iv"], 0.01), l["dte"], abs(l["qty"]), l["exp"][:10]
        T, Trem = max(dte, 0) / 365.0, max(dte - h, 0) / 365.0
        if l["side"] == "long":
            if typ == "call":
                k2 = w.get("call_wall") or round(spot + em)
                tgt = max(w.get("call_wall") or spot * 1.06, spot + em)
                if k2 and k2 > K:
                    credit = bs_greeks(spot, k2, T, r, iv, "call").get("price", 0.0)
                    if credit > 0.02:
                        tips.append(f"💡 **SELL {q}× {_kf(k2)}C {exp}** ≈ \\${credit:.2f} → makes a "
                                    f"\\${_kf(K)}/{_kf(k2)} call spread: net cost \\${max(l['entry']-credit,0):.2f} "
                                    f"(was \\${l['entry']:.2f}), max value \\${k2-K:.2f}/sh.")
                mv = bs_greeks(tgt, K, Trem, r, iv, "call").get("price", max(tgt - K, 0)) if Trem > 0 else max(tgt - K, 0)
                tips.append(f"🎯 **{_kf(K)}C** could be worth ≈ **\\${mv:.2f}** if {l['ticker']} reaches "
                            f"\\${tgt:.0f} (call wall / +1σ) by ~{h}DTE — now \\${l['cur']:.2f}.")
            else:
                k2 = w.get("put_wall") or round(spot - em)
                tgt = min(w.get("put_wall") or spot * 0.94, spot - em)
                if k2 and k2 < K:
                    credit = bs_greeks(spot, k2, T, r, iv, "put").get("price", 0.0)
                    if credit > 0.02:
                        tips.append(f"💡 **SELL {q}× {_kf(k2)}P {exp}** ≈ \\${credit:.2f} → makes a "
                                    f"\\${_kf(K)}/{_kf(k2)} put spread: net cost \\${max(l['entry']-credit,0):.2f} "
                                    f"(was \\${l['entry']:.2f}), max value \\${K-k2:.2f}/sh.")
                mv = bs_greeks(tgt, K, Trem, r, iv, "put").get("price", max(K - tgt, 0)) if Trem > 0 else max(K - tgt, 0)
                tips.append(f"🎯 **{_kf(K)}P** could be worth ≈ **\\${mv:.2f}** if {l['ticker']} reaches "
                            f"\\${tgt:.0f} (put wall / −1σ) by ~{h}DTE — now \\${l['cur']:.2f}.")
        else:
            tips.append(f"🛡 **BUY {q}× {_kf(K)}{typ[0].upper()} {exp}** ≈ \\${l['cur']:.2f} to close "
                        f"(locks \\${l['pnl']:,.0f}).")
    return tips


def _gp_booking_notes(tl, spot):
    """When a leg has captured most of its achievable profit, advise booking it with a concrete
    pre-market limit price — short premium nearly decayed (buy-to-close cheap) or a profitable
    long near expiry / up big (sell-to-close). Returns (notes, checklist_items)."""
    notes, chk = [], []
    for l in tl:
        q = abs(l["qty"]); buf = max(0.05, round(l["cur"] * 0.05, 2))
        if l["typ"] == "stock":                       # shares: no theta — different economics
            pnlp = ((l["cur"] - l["entry"]) / l["entry"] * 100 * (1 if l["qty"] > 0 else -1)) if l["entry"] else 0
            if l["pnl"] > 0 and pnlp >= 50:
                notes.append(f"💎 **{q:g} shares (long)** — up {pnlp:+.0f}%. Shares don't decay, so there's "
                             f"no exit pressure from time. If trimming, use a limit near the mark "
                             f"(${l['cur']:.2f}) — and check the **tax clock first** (Portfolio → P&L tab "
                             "or bot /tax): an early sale can flip a 15% LT gain to ordinary rates.")
            continue
        tag = f"${_kf(l['K'])}{l['typ'][0].upper()}"
        if l["side"] == "short":
            maxp = l["entry"] * q * 100                      # premium collected = max profit (capped)
            cap = (l["pnl"] / maxp) if maxp > 1e-6 else 0.0
            if l["pnl"] > 0 and cap >= 0.75:
                lim = max(round(l["cur"] + buf, 2), 0.01)
                notes.append(f"✅ **{tag} (short)** — **{cap*100:.0f}% of max premium (${maxp:,.0f}) captured.** "
                             f"Place **BUY {q}× to close @ ${lim:.2f}** pre-market to lock it — the last "
                             "few cents aren't worth a reversal/assignment.")
                chk.append(f"{l['ticker']} {tag}: book profit — BUY-to-close @ ${lim:.2f}")
        else:
            pnlp = ((l["cur"] - l["entry"]) / l["entry"] * 100) if l["entry"] else 0
            if l["pnl"] > 0 and (pnlp >= 50 or l["dte"] <= 5):
                lim = max(round(l["cur"] - buf, 2), 0.01)
                why = (f"up {pnlp:+.0f}%" + (f", only {l['dte']}DTE" if l["dte"] <= 5 else ""))
                notes.append(f"✅ **{tag} (long)** — {why}. Place **SELL {q}× to close @ ${lim:.2f}** "
                             f"pre-market (target ≈ mark ${l['cur']:.2f}; scale the limit down if it "
                             "doesn't fill) to bank the gain before theta/reversal.")
                chk.append(f"{l['ticker']} {tag}: take profit — SELL-to-close @ ${lim:.2f}")
    return notes, chk


def _gp_exec_timing(tk, tl, spot, chg):
    """Scenario-based execution timing: close at open vs wait, order type, and the time-of-day
    windows where liquidity/institutions concentrate. Uses volatility, swings and volume."""
    atrp = volr = swing5 = None
    try:
        h = _cached_history(tk, "3mo")
        if h is not None and len(h) > 20 and {"High", "Low"} <= set(h.columns):
            c = h["Close"]; pc = c.shift(1)
            tr = pd.concat([(h["High"] - h["Low"]), (h["High"] - pc).abs(), (h["Low"] - pc).abs()], axis=1).max(axis=1)
            atrp = float(tr.rolling(14).mean().iloc[-1]) / float(c.iloc[-1]) * 100
            swing5 = float((h["High"].iloc[-5:].max() - h["Low"].iloc[-5:].min()) / float(c.iloc[-1]) * 100)
            if "Volume" in h:
                va = float(h["Volume"].rolling(20).mean().iloc[-1] or 0)
                volr = float(h["Volume"].iloc[-1]) / va if va else None
    except Exception:
        pass
    min_dte = min(x["dte"] for x in tl)
    short_itm = any(x["side"] == "short" and ((spot > x["K"]) if x["typ"] == "call" else (spot < x["K"])) for x in tl)
    net_long = sum(x["ddelta_1pct"] for x in tl) > 0
    urgent = min_dte <= 2 or short_itm
    B = []
    B.append("**Don't trade the first 5–15 min blind.** 9:30–10:00 ET is the most volatile window and often "
             "*reverses* the opening gap; spreads are widest and market orders slip. Let it settle, reassess ~10:00.")
    if chg > 0.3 and net_long:
        B.append("You're **gapping up, net-long** — the open is frequently the day's high. If trimming, **sell into "
                 "opening strength with a limit** near the ask; don't wait for a dip that may not come.")
    elif chg < -0.3 and net_long:
        B.append("**Gapping down, net-long** — avoid panic-selling at 9:30. The **10:00–10:30 stabilization** usually "
                 "gives a better exit; if it's not urgent, wait.")
    elif chg < -0.3 and not net_long:
        B.append("**Gapping down, net-short** — the move favors you; consider banking profit into the open weakness with a limit.")
    elif chg > 0.3 and not net_long:
        B.append("**Gapping up, net-short** — squeeze risk; don't chase the cover at the open, wait for the ~10:00 fade or define risk.")
    B.append("**Best fills:** ~**9:45–10:30** and the **power hour 3:00–3:55** (institutions, index funds & MOC desks "
             "most active). **Avoid 12:00–1:30** lunch lull — thin, wide spreads, drifty.")
    B.append("**Close auction 3:50–4:00:** market-on-close imbalances + passive/index flows can shove price — biggest "
             "on OPEX (3rd Fri) and month/quarter-end.")
    if atrp is not None:
        if atrp > 3 or (swing5 and swing5 > 9):
            B.append(f"Volatility **high** (ATR ≈ {atrp:.1f}%/day, 5-day swing ≈ {swing5:.0f}%) — use **limits & scale out "
                     "in pieces**; a single market order will slip.")
        else:
            B.append(f"Volatility **moderate** (ATR ≈ {atrp:.1f}%/day) — limits near mid should fill; you can be patient.")
    if volr is not None:
        B.append(f"Volume **{volr:.1f}× the 20-day avg** — "
                 + ("real conviction behind the move; trust it more." if volr > 1.3
                    else "below average; moves are less reliable — don't overreact." if volr < 0.8 else "normal."))
    if urgent:
        head = ("⏱ **Act today** (≤2 DTE or short-ITM) — don't carry the gamma. Work the **9:45–10:30** window with "
                "limit orders; if it must go at the open, use a *marketable limit*, never a plain market order.")
    elif chg < -0.3 and net_long:
        head = "⏱ **No need to close at the open** — non-urgent long into a gap-down; let the first 30 min shake out, reassess at 10:00."
    elif chg > 0.3 and net_long:
        head = "⏱ **Opening strength is your friend** — if you want out, sell into the first hour with a limit rather than waiting for a dip."
    else:
        head = "⏱ **No rush** — use the 9:45–10:30 or 3:00–3:55 windows; skip the open and the lunch lull."
    return head, B


def _macro_writeup(mac, label):
    def mv(k):
        if k in mac:
            p = mac[k]["pct"]
            return ("up" if p > 0.1 else "down" if p < -0.1 else "flat") + f" {p:+.1f}%"
        return None
    bits = []
    for k in ("S&P fut", "VIX", "Dollar (DXY)", "US 10y", "WTI oil", "Gold", "China (FXI)"):
        m = mv(k)
        if m:
            bits.append(f"{k} {m}")
    tail = {
        "RISK-ON": "Supportive backdrop for longs / semis / tech — tailwind into the open.",
        "RISK-OFF": "Headwind — favor hedges, trim high-beta, and expect wider swings.",
        "MIXED": "No clear global push — let your stock-level levels lead.",
    }[label]
    return f"Overnight, {', '.join(bits)}. {tail}"


_EDGAR_H = {"User-Agent": "RUDRARJUN Analytics research srinivas.analystsas@gmail.com"}
_EDGAR_DDL = ("CREATE TABLE IF NOT EXISTS edgar_13f (cik TEXT, fund TEXT, quarter TEXT, "
              "filing_date TEXT, cusip TEXT, issuer TEXT, shares REAL, value REAL, put_call TEXT, "
              "PRIMARY KEY (cik, quarter, cusip, put_call))")


def _edgar_13f_filings(cik, n=12):
    """List the last n 13F-HR filings for a CIK from SEC EDGAR submissions JSON."""
    import urllib.request, json as _j
    url = f"https://data.sec.gov/submissions/CIK{int(cik):010d}.json"
    req = urllib.request.Request(url, headers=_EDGAR_H)
    with urllib.request.urlopen(req, timeout=20) as r:
        d = _j.loads(r.read().decode())
    rec = d["filings"]["recent"]
    seen = {}
    for form, acc, fd, rd in zip(rec["form"], rec["accessionNumber"], rec["filingDate"], rec["reportDate"]):
        if form == "13F-HR" and rd not in seen:
            seen[rd] = {"accession": acc, "filing_date": fd, "report_date": rd}
    return sorted(seen.values(), key=lambda x: x["report_date"], reverse=True)[:n]


def _edgar_parse_infotable(cik, accession):
    """Parse a 13F information-table XML into a list of holdings dicts."""
    import urllib.request, json as _j, xml.etree.ElementTree as ET
    ciki = str(int(cik)); acc = accession.replace("-", "")
    idx = f"https://www.sec.gov/Archives/edgar/data/{ciki}/{acc}/index.json"
    req = urllib.request.Request(idx, headers=_EDGAR_H)
    with urllib.request.urlopen(req, timeout=20) as r:
        items = _j.loads(r.read().decode())["directory"]["item"]
    xmls = [it["name"] for it in items if it["name"].lower().endswith(".xml")]
    cand = [n for n in xmls if n.lower() != "primary_doc.xml"]
    rows = []
    for nm in (cand or xmls):                          # combine ALL info-table files (big filers split them)
        try:
            url = f"https://www.sec.gov/Archives/edgar/data/{ciki}/{acc}/{nm}"
            req = urllib.request.Request(url, headers=_EDGAR_H)
            with urllib.request.urlopen(req, timeout=25) as r:
                root = ET.fromstring(r.read().decode(errors="ignore"))
            for el in root.iter():
                if el.tag.split("}")[-1] == "infoTable":
                    d = {}
                    for ch in el.iter():
                        t = ch.tag.split("}")[-1]
                        if t in ("nameOfIssuer", "cusip", "value", "putCall", "sshPrnamt"):
                            d[t] = (ch.text or "").strip()
                    if d.get("cusip"):
                        rows.append(d)
        except Exception:
            continue
    return rows


def _edgar_build_history(cik, fund, n=12, force=False):
    """Fetch + parse + store the last n 13F-HR holdings for a CIK. Returns quarters stored."""
    import time as _t
    conn = get_conn()
    try:
        conn.execute(_EDGAR_DDL); conn.commit()
        have = set() if force else {x[0] for x in conn.execute(
            "SELECT DISTINCT quarter FROM edgar_13f WHERE cik=?", (str(cik),)).fetchall()}
        stored = 0
        for f in _edgar_13f_filings(cik, n):
            q = f["report_date"]
            if q in have:
                stored += 1; continue
            rows = _edgar_parse_infotable(cik, f["accession"]); _t.sleep(0.2)
            dollars = f["filing_date"] >= "2023-01-01"   # SEC switched $thousands→dollars in 2023
            recs = []
            for d in rows:
                try:
                    val = float(d.get("value") or 0) * (1 if dollars else 1000)
                except Exception:
                    val = 0.0
                try:
                    sh = float(d.get("sshPrnamt") or 0)
                except Exception:
                    sh = 0.0
                recs.append((str(cik), fund, q, f["filing_date"], d.get("cusip", ""),
                             d.get("nameOfIssuer", ""), sh, val, d.get("putCall", "") or ""))
            if recs:
                conn.execute("DELETE FROM edgar_13f WHERE cik=? AND quarter=?", (str(cik), q))
                conn.executemany("INSERT OR REPLACE INTO edgar_13f VALUES (?,?,?,?,?,?,?,?,?)", recs)
                conn.commit(); stored += 1
        return stored
    finally:
        conn.close()


def _edgar_load(cik):
    conn = get_conn()
    try:
        conn.execute(_EDGAR_DDL); conn.commit()
        return pd.read_sql("SELECT * FROM edgar_13f WHERE cik=?", conn, params=(str(cik),))
    except Exception:
        return pd.DataFrame()
    finally:
        conn.close()


