def _heatmap_panel(live=None):
    """Sector treemap on the dashboard — same engine as the Telegram /heatmap.

    Interactive here rather than a PNG: Streamlit renders plotly natively, so hovering a
    tile gives the exact move. Reuses _heatmap_frame from the bot engine so there is one
    implementation, not two (user 2026-08-07).
    """
    if _TB_ENGINE is None:
        return
    try:
        _lv = _market_state() == "OPEN" if live is None else bool(live)
        _c = get_conn()
        try:
            m = _TB_ENGINE._heatmap_frame(_c, live=_lv)
        finally:
            _c.close()
        if m is None or len(m) < 10:
            st.caption("Heatmap unavailable — no market-cap/sector data.")
            return
        _lab = [f"{r.ticker}<br>{r.pct:+.1f}%" for r in m.itertuples()]
        _secs = sorted(set(m["sector"]))
        fig = go.Figure(go.Treemap(
            labels=_lab + _secs,
            parents=list(m["sector"]) + [""] * len(_secs),
            values=list(m["market_cap"]) + [0] * len(_secs),
            marker=dict(colors=list(m["pct"]) + [0] * len(_secs),
                        colorscale=[[0, "#8b1a1a"], [0.5, "#3a3a3a"], [1, "#0f7b2f"]],
                        cmid=0, cmin=-4, cmax=4, line=dict(width=1, color="#111")),
            textposition="middle center", textfont=dict(size=12),
            hovertemplate="%{label}<extra></extra>",
        ))
        fig.update_layout(height=640, margin=dict(l=2, r=2, t=8, b=2),
                          paper_bgcolor="rgba(0,0,0,0)")
        st.plotly_chart(fig, use_container_width=True, key="mkt_heatmap")
        st.caption(f"Tile size = market cap · colour = "
                   f"{'LIVE move' if _lv else 'last completed session'} · "
                   f"{len(m)} names across {m.sector.nunique()} sectors. "
                   f"Hover any tile for the exact figure.")
    except Exception as _e:
        st.caption(f"Heatmap unavailable: {_e}")


def _catchup_panel(where=""):
    """Today's scheduled briefings, and whether each has actually gone out.

    The bot pushes these on a clock and catches up what was missed. Streamlit had no view
    of any of it, so there was no way to tell "quiet morning" from "the bot was asleep"
    (user 2026-08-07). Reads the same alert_dedup rows the bot writes.
    """
    _SCHED = [("digest_morning", "08:15", "Morning digest"),
              ("catalyst_alert", "08:20", "Catalyst Radar"),
              ("plan_alert",     "08:30", "Next-day game plan"),
              ("action_board",   "08:35", "Action Board"),
              ("earnings_alert", "08:45", "Earnings Radar"),
              ("morning_alert",  "09:00", "Morning alert"),
              ("briefing_alert", "09:05", "Daily briefing")]
    try:
        _c = get_conn()
        try:
            _today = datetime.now().strftime("%Y-%m-%d")
            _sent = {r[0] for r in _c.execute(
                "SELECT grp_key FROM alert_dedup WHERE alert_date=? AND atype='sched'",
                (_today,))}
        finally:
            _c.close()
    except Exception as _e:
        st.caption(f"Catch-up status unavailable: {_e}")
        return
    _now = datetime.now().strftime("%H:%M")
    _rows, _missing = [], []
    for _k, _t, _lbl in _SCHED:
        _done = _k in _sent
        _due = _t <= _now
        _rows.append({"Briefing": _lbl, "Scheduled": _t,
                      "Status": "✅ sent" if _done else ("⏳ due — not sent" if _due
                                                         else "🕐 later today")})
        if _due and not _done:
            _missing.append(_lbl)
    if _missing:
        st.warning(f"📭 **{len(_missing)} briefing(s) due but not sent** — "
                   + ", ".join(_missing)
                   + ". The bot sends these on a clock, so if the laptop was asleep they "
                     "were skipped. Run **/catchup** in Telegram to get them now.")
    else:
        st.success("📬 All briefings due so far today have been sent.")
    with st.expander("Today's briefing schedule", expanded=False):
        st.dataframe(pd.DataFrame(_rows), hide_index=True, use_container_width=True)


