@st.cache_data(ttl=600, show_spinner=False)
def _sm_strike_map(d0):
    """WHERE the flow went, per ticker, on the OI snapshot date: hottest call strike by ΔOI
    (conviction build) and by volume (speculation), each with expiry + last price, plus spot."""
    with get_conn() as c:
        df = pd.read_sql(
            "SELECT ticker, strike, expiry_date, change_OI_Call, vol_Call_now, lastPrice_Call_now, "
            "change_OI_Put, lastPrice_Put_now "
            "FROM options_change WHERE trade_date_now=?", c, params=(d0,))
        sp = pd.read_sql(
            "SELECT s.ticker, s.close FROM stock_daily s JOIN ("
            " SELECT ticker, MAX(trade_date) mk FROM stock_daily GROUP BY ticker) m"
            " ON s.ticker=m.ticker AND s.trade_date=m.mk", c)
    out = {"doi": {}, "vol": {}, "doi_p": {}, "spot": {}}
    if df.empty:
        return out
    df["ticker"] = df["ticker"].astype(str).str.upper()
    for col in ("strike", "change_OI_Call", "vol_Call_now", "lastPrice_Call_now",
                "change_OI_Put", "lastPrice_Put_now"):
        df[col] = pd.to_numeric(df[col], errors="coerce").fillna(0)

    def _lbl(r, cp="C"):
        lp = r["lastPrice_Call_now"] if cp == "C" else r["lastPrice_Put_now"]
        px = f" @ ${lp:.2f}" if lp > 0 else ""
        return f"${r['strike']:g}{cp} {str(r['expiry_date'])[:10]}{px}"

    for tk, gg in df.groupby("ticker"):
        r1 = gg.loc[gg["change_OI_Call"].idxmax()]
        if r1["change_OI_Call"] > 0:
            out["doi"][tk] = _lbl(r1)
        r2 = gg.loc[gg["vol_Call_now"].idxmax()]
        if r2["vol_Call_now"] > 0:
            out["vol"][tk] = _lbl(r2)
        r3 = gg.loc[gg["change_OI_Put"].idxmax()]
        if r3["change_OI_Put"] > 0:
            out["doi_p"][tk] = _lbl(r3, "P")
    if not sp.empty:
        out["spot"] = {str(t).upper(): float(v) for t, v in zip(sp["ticker"], sp["close"]) if v}
    return out


def _ab_norm_exp(e):
    """Any stored expiry format → YYYY-MM-DD (the trades-table format)."""
    for fmt in ("%Y-%m-%d", "%m-%d-%Y", "%m/%d/%Y", "%Y/%m/%d"):
        try:
            return datetime.strptime(str(e)[:10], fmt).strftime("%Y-%m-%d")
        except Exception:
            continue
    return str(e)[:10]


@st.cache_data(ttl=900, show_spinner=False)
def _ab_ideas():
    """One row per actionable idea across every DB-first scanner in the bot engine, each with a
    concrete option (strike/expiry/last price) so it can be tracked as a position. Returns
    (ideas list, snapshot date)."""
    import telegram_bot_optimized as _tb
    ideas = []
    with get_conn() as c:
        row = c.execute("SELECT MAX(trade_date_now) FROM options_change").fetchone()
        d0 = row[0] if row else None
        snap = pd.DataFrame()
        if d0:
            snap = pd.read_sql("SELECT ticker, strike, expiry_date, lastPrice_Call_now, lastPrice_Put_now "
                               "FROM options_change WHERE trade_date_now=?", c, params=(d0,))
        spots = _sm_strike_map(d0)["spot"] if d0 else {}
        if not snap.empty:
            snap["tk"] = snap["ticker"].astype(str).str.upper()
            for col in ("strike", "lastPrice_Call_now", "lastPrice_Put_now"):
                snap[col] = pd.to_numeric(snap[col], errors="coerce").fillna(0)
            _tdy = datetime.now().date()
            snap["dte"] = snap["expiry_date"].map(
                lambda e: (datetime.strptime(_ab_norm_exp(e), "%Y-%m-%d").date() - _tdy).days
                if _ab_norm_exp(e)[:4].isdigit() else None)

        def _pick(tk, typ):
            """Nearest-ATM contract, expiry ≥10 DTE closest to ~30d, with a real last price."""
            tk = tk.upper()
            spot = spots.get(tk)
            if snap.empty or not spot:
                return None
            pcol = "lastPrice_Call_now" if typ == "call" else "lastPrice_Put_now"
            g = snap[(snap["tk"] == tk) & (snap["dte"].notna()) & (snap["dte"] >= 10) & (snap[pcol] > 0)].copy()
            if g.empty:
                return None
            g["_dd"] = (g["dte"] - 30).abs()
            best_exp = g.sort_values("_dd")["expiry_date"].iloc[0]
            g2 = g[g["expiry_date"] == best_exp].copy()
            g2["_kd"] = (g2["strike"] - spot).abs()
            r = g2.sort_values("_kd").iloc[0]
            return {"K": float(r["strike"]), "exp": _ab_norm_exp(best_exp), "px": float(r[pcol])}

        def _add(source, tk, bias, why, legs, label):
            ideas.append({"Source": source, "Ticker": tk.upper(), "Bias": bias,
                          "Why": why, "Trade": label, "legs": legs})

        def _dir_idea(source, tk, long_side, why):
            """Directional idea → long call (bullish) or long put (bearish) near ATM ~30d."""
            typ = "call" if long_side else "put"
            p = _pick(tk, typ)
            bias = "🟢 LONG" if long_side else "🔴 SHORT"
            if p:
                lab = f"BUY ${p['K']:g}{typ[0].upper()} {p['exp']} @ ${p['px']:.2f}"
                _add(source, tk, bias, why, [(typ, p["K"], p["exp"], p["px"], +1)], lab)
            else:
                _add(source, tk, bias, why, [], "— no chain in snapshot")

        try:                                            # 🐋 unusual options activity (actual contract)
            for r in _tb._uoa_scan(c)[:5]:
                typ = "call" if r["side"] == "C" else "put"
                p = _pick(r["ticker"], typ)             # price lookup for THE flow contract
                px = 0.0
                gg = snap[(snap["tk"] == r["ticker"].upper()) & (snap["strike"] == r["strike"]) &
                          (snap["expiry_date"] == r["expiry"])] if not snap.empty else pd.DataFrame()
                if not gg.empty:
                    px = float(gg.iloc[0]["lastPrice_Call_now" if typ == "call" else "lastPrice_Put_now"])
                exp = _ab_norm_exp(r["expiry"])
                lab = f"FOLLOW ${r['strike']:g}{r['side']} {exp}" + (f" @ ${px:.2f}" if px > 0 else "")
                _add("🐋 UOA flow", r["ticker"], "🟢 LONG" if r["side"] == "C" else "🔴 SHORT",
                     f"vol {r['ratio']:.1f}× OI · ${_tb._knum(r['notional'])} fresh flow",
                     [(typ, float(r["strike"]), exp, px, +1)] if px > 0 else [], lab)
        except Exception:
            pass
        try:                                            # 🏗️ positioning builder
            for r in _tb._positioning_scan(c)[:5]:
                _dir_idea("🏗️ Building", r["ticker"], r["bias"] == "LONG",
                          f"new {'call' if r['bias']=='LONG' else 'put'} OI +{r['build_pct']*100:.0f}% · stage {r['stage']}")
        except Exception:
            pass
        try:                                            # 📈 52-week breakout / breakdown
            for r in _tb._breakout_scan(c)[:4]:
                hi = r["sig"] == "HIGH"
                _dir_idea("📈 Breakout", r["ticker"], hi,
                          f"{'at 52w HIGH' if hi else 'at 52w LOW'} ({(r['from_hi'] if hi else r['from_lo'])*100:+.1f}%)")
        except Exception:
            pass
        try:                                            # 📏 z-score reversion
            for r in _tb._zrev_scan(c)[:4]:
                _dir_idea("📏 Z-Rev", r["ticker"], r["side"] == "LONG", f"z={r['z']:+.1f} vs 20d mean")
        except Exception:
            pass
        try:                                            # 🔄 5-day reversal
            for r in _tb._revert_scan(c)[:4]:
                _dir_idea("🔄 Revert", r["ticker"], r["side"] == "LONG",
                          f"5d ret {r['ret']*100:+.1f}% · z={r['z']:+.1f}")
        except Exception:
            pass
        try:                                            # 💪 relative-strength leaders
            for r in _tb._rs_scan(c)[:4]:
                _dir_idea("💪 RS leader", r["ticker"], True, f"3M {r['r3']*100:+.0f}% · vs SPY {r['ex3']*100:+.0f}%")
        except Exception:
            pass
        try:                                            # 🌪️ VRP — only on names already on the board (full scan too slow)
            _board_tks = list(dict.fromkeys(i["Ticker"] for i in ideas))[:12]
            for r in _tb._vrp_scan(c, tickers=_board_tks)[:4]:
                why = f"IV {r['iv']*100:.0f}% vs RV {r['rv']*100:.0f}% (VRP {r['vrp']*100:+.0f}pt)"
                if r["side"] == "SELL":
                    p = _pick(r["ticker"], "put")
                    if p:
                        _add("🌪️ VRP", r["ticker"], "🟡 SELL VOL", why,
                             [("put", p["K"], p["exp"], p["px"], -1)],
                             f"SELL ${p['K']:g}P {p['exp']} @ ${p['px']:.2f} (CSP)")
                    else:
                        _add("🌪️ VRP", r["ticker"], "🟡 SELL VOL", why, [], "sell premium (CSP/condor)")
                else:
                    pc, pp = _pick(r["ticker"], "call"), _pick(r["ticker"], "put")
                    if pc and pp:
                        _add("🌪️ VRP", r["ticker"], "🟣 BUY VOL", why,
                             [("call", pc["K"], pc["exp"], pc["px"], +1), ("put", pp["K"], pp["exp"], pp["px"], +1)],
                             f"BUY straddle ${pc['K']:g} {pc['exp']} @ ${pc['px']+pp['px']:.2f}")
                    else:
                        _add("🌪️ VRP", r["ticker"], "🟣 BUY VOL", why, [], "buy vol (straddle)")
        except Exception:
            pass
    # ⭐ consensus: same ticker + same direction from ≥2 different indicators
    from collections import Counter
    _cnt = Counter((i["Ticker"], i["Bias"]) for i in ideas)
    for i in ideas:
        i["⭐"] = "⭐" if _cnt[(i["Ticker"], i["Bias"])] >= 2 and i["Bias"] in ("🟢 LONG", "🔴 SHORT") else ""
    return ideas, d0



# ── Pinned identity columns on every table (ID 97, user 2026-08-03) ───────────────────
# Scrolling a wide table sideways lost the ticker, so the numbers belonged to nobody.
# Rather than edit 147 st.dataframe call sites, every call goes through this wrapper: it
# pins the first identity-ish columns it finds and merges whatever column_config the call
# site already passed (the call site wins on conflict). Streamlit >=1.42 for `pinned`.
_PIN_PRIMARY = ("Ticker", "Tkr", "Symbol", "Sym", "Pair", "Market", "Name", "Company",
                "Sector", "Strategy", "Signal", "Model", "Region", "Item", "Metric")
_PIN_SECOND = ("Spot", "Spot $", "Px", "Price", "Close", "Last", "Score", "Value")


_DEC3_RE = re.compile(r"^[^\d]{0,2}[\d,]*\.\d{3,}[^\d]{0,2}$")


def _two_dp(v):
    """2dp, but never fake a zero: a real 0.004 shows as <0.01, not 0.00."""
    try:
        if v is None or (isinstance(v, float) and v != v):    # None / NaN
            return "—"
        f = float(v)
    except (TypeError, ValueError):
        return v
    if f != 0 and abs(f) < 0.005:
        # Rounds to zero but isn't zero. NOT "<0.01": pandas' Styler does not escape HTML,
        # so a literal '<' opens a tag and the cell disappears from the rendered grid.
        return "≈0.00" if f > 0 else "≈-0.00"
    return f"{f:,.2f}"


def _cap_2dp(data):
    """Cap DISPLAY precision at 2 decimals everywhere (user 2026-08-08, ID 197/203).

    Values were already rounded at source in most places; the leak was on the DISPLAY side —
    a pandas Styler with no .format() falls back to `display.precision` of 6, which is how
    Paper Trading was showing `Qty 101.000000`. Doing it here, in the one helper every grid
    goes through, is what keeps it from having to be remembered per table.

    Two things are deliberately left alone:
      * columns a caller already formatted (per-column `.format({...})` dicts on the Shorts
        and Gamma-Wall tables) — those are intentional and would be clobbered by a blanket
        format, so only unformatted float columns are touched;
      * any column with an explicit column_config — that is the escape hatch for a column
        that genuinely needs more precision.
    """
    try:
        import pandas as _pd
        from pandas.io.formats.style import Styler as _Styler
    except Exception:
        return data
    try:
        if not isinstance(data, _Styler):
            return data
        _df = data.data
        if _df.empty:
            return data
        funcs = getattr(data, "_display_funcs", None)
        # Ask each column what it would actually PRINT, and cap only the ones printing 3+
        # decimals. Checking the rendered text (not the dtype) is what makes this safe next
        # to the per-column .format({...}) dicts on the Shorts and Gamma-Wall tables:
        # "$450" and "12.3%" do not match, so they are left exactly as their author wrote
        # them. Same test the bot's _pipe_table uses, so both front ends agree on the rule.
        wide = []
        for j, c in enumerate(_df.columns):
            for i in range(min(len(_df), 5)):
                v = _df.iloc[i, j]
                if v is None or (isinstance(v, float) and v != v):
                    continue
                try:
                    fn = funcs[(i, j)] if funcs is not None else None
                    shown = fn(v) if callable(fn) else None
                except Exception:
                    shown = None
                if shown is None:
                    shown = f"{v:.6f}" if isinstance(v, float) else str(v)
                if isinstance(shown, str) and _DEC3_RE.match(shown.strip()):
                    wide.append(c)
                break
        return data.format(_two_dp, subset=wide) if wide else data
    except Exception:
        return data


# Columns whose SIGN carries meaning, so they earn red/green. Matched case-insensitively on
# a substring, because the same idea is spelled a dozen ways across 60 tables.
_SIGNED_COLS = ("p&l", "pnl", "chg", "change", "%", "edge", "net", "return", "ret",
                "move", "drift", "surprise", "vs spot", "delta", "gap")
# Columns where a number is NOT a gain/loss and must never be coloured: prices, counts,
# strikes, identifiers. Colouring these was the trap -- a red "Entry 166.80" reads as a loss.
_UNSIGNED_COLS = ("entry", "strike", "spot", "price", "qty", "lots", "oi", "volume",
                  "dte", "days", "id", "count", "ticker", "date", "expiry", "limit", "theo")


def _colour_signed(df):
    """Red/green wash on the columns where sign means gain or loss (ID 297).

    A pandas Styler, so it only affects DISPLAY -- values are untouched. Deliberately NOT a
    gradient: a gradient re-scales to whatever happens to be in the frame, so a table of
    small losses would paint its least-bad row bright green. Sign decides the hue and
    MAGNITUDE only decides the strength, capped, so the colour means the same thing in every
    table on every page.

    Returns the frame unchanged when nothing qualifies, so callers never need to check.
    """
    try:
        import pandas as _pd
        if not isinstance(df, _pd.DataFrame) or df.empty:
            return df
        cols = []
        for c in df.columns:
            lc = str(c).lower()
            if any(u in lc for u in _UNSIGNED_COLS):
                continue
            if not any(k in lc for k in _SIGNED_COLS):
                continue
            if _pd.to_numeric(df[c], errors="coerce").notna().any():
                cols.append(c)
        if not cols:
            return df

        # SCALE PER COLUMN, not with one global cap. A fixed cap saturates instantly on
        # dollars: P&L of 18,045 / 8,379 / 2,010 / 463 all came out the identical green, so
        # the column was still a monolith -- the exact complaint. The 90th percentile of
        # |value| gives each column its own sensible top end whatever the unit, and the
        # floor stops a column of near-zeros being amplified into noise.
        _scale = {}
        for c in cols:
            v = _pd.to_numeric(df[c], errors="coerce").abs().dropna()
            hi = float(v.quantile(0.90)) if len(v) else 0.0
            _scale[c] = max(hi, 1e-9)

        def _cell(v, col=None):
            n = _pd.to_numeric(v, errors="coerce")
            if n is None or _pd.isna(n) or n == 0:
                return ""
            a = min(abs(float(n)) / _scale.get(col, 1.0), 1.0)
            # Sign picks the hue and always shows; magnitude only modulates the strength, so
            # a small gain never reads as a loss just because it is the column's weakest.
            rgb = "22,163,74" if float(n) > 0 else "220,38,38"
            return f"background-color: rgba({rgb},{0.08 + 0.30 * a:.2f})"

        sty = df.style
        for c in cols:
            sty = sty.map(lambda v, _c=c: _cell(v, _c), subset=[c])
        return sty
    except Exception:
        return df


def _pinned_df(data, *args, **kwargs):
    """st.dataframe with identity columns pinned. Falls back silently on older Streamlit."""
    data = _cap_2dp(data)
    # Sign colouring at the same choke point as the 2dp cap (ID 297), so every grid in
    # the app gets it without 60 call sites remembering to. Skipped when the caller
    # already supplied a Styler -- their formatting wins.
    try:
        import pandas as _pd0
        if isinstance(data, _pd0.DataFrame):
            data = _colour_signed(data)
    except Exception:
        pass
    try:
        import pandas as _pd
        # A Styler hides its columns behind .data — read through it, or every styled table
        # (Paper Trading, P&L groups, …) silently loses pinning AND the flag ImageColumn,
        # which is how the flag column would have rendered as a raw data: URI string.
        _frame = data.data if hasattr(data, "data") and not isinstance(data, _pd.DataFrame) else data
        cols = list(_frame.columns) if isinstance(_frame, _pd.DataFrame) else []
    except Exception:
        _frame, cols = data, []
    if cols:
        cfg = dict(kwargs.get("column_config") or {})
        pinned = 0
        for name in _PIN_PRIMARY:
            if pinned >= 2:
                break
            if name in cols and name not in cfg:
                try:
                    cfg[name] = st.column_config.Column(name, pinned=True)
                    pinned += 1
                except Exception:
                    pass
        for name in _PIN_SECOND:                      # one more anchor: usually the price
            if pinned >= 3:
                break
            if name in cols and name not in cfg:
                try:
                    cfg[name] = st.column_config.Column(name, pinned=True)
                    pinned += 1
                except Exception:
                    pass
        # Plain-DataFrame half of the 2dp rule. Only float columns with no caller-supplied
        # config: ints keep their natural form, and an explicit column_config still wins.
        # The flag column is a picture everywhere it appears, without each caller repeating it.
        if "🌍" in cols and "🌍" not in cfg:
            try:
                cfg["🌍"] = st.column_config.ImageColumn(
                    "🌍", width="small",
                    help="Country the instrument belongs to — from the exchange suffix "
                         "(.NS = India) or a curated ADR/ETF map; 🇺🇸 by default.")
            except Exception:
                pass
        try:
            import pandas as _pd2
            for name in cols:
                if name in cfg or not _pd2.api.types.is_float_dtype(_frame[name]):
                    continue
                _s = _frame[name].dropna()
                if _s.empty:
                    continue
                # EVERY float column reads 2dp, not just the ones that overflow it — the rule
                # is a display rule, so 166.8 and 166.80 in the same column is the same bug in
                # a smaller size. Callers that need other precision pass their own config.
                cfg[name] = st.column_config.NumberColumn(str(name), format="%.2f")
        except Exception:
            pass
        if cfg:
            kwargs["column_config"] = cfg
    try:
        return st.dataframe(data, *args, **kwargs)
    except TypeError:
        kwargs.pop("column_config", None)             # very old Streamlit
        return st.dataframe(data, *args, **kwargs)


