    _rc_reset_keys = ["rc_tk", "rc_type", "rc_strike", "rc_exp", "rc_entry", "rc_qty", "rc_side"]
    if st.button("🔄 Reset Fields", key="rc_reset"):
        for _k in _rc_reset_keys:
            st.session_state.pop(_k, None)
