        f"<div><div>Entry Price</div><div>${ep_entry:.2f}</div></div>"
        f"<div><div>P&L ({ep_qty} contract{'s' if ep_qty > 1 else ''})</div><div>${_pred_pnl:+,.0f} ({_pred_pnl_pct:+.1f}%)</div></div>"
