                            _exp_hi=_vprof[_hi_b+1] if _hi_b<_N-1 else 0
                            if _exp_lo>=_exp_hi and _lo_b>0: _lo_b-=1; _acc+=_vprof[_lo_b]
                            elif _hi_b<_N-1: _hi_b+=1; _acc+=_vprof[_hi_b]
                            else: break
