@st.cache_data(ttl=300, show_spinner=False)
def _hiprob_scan(tickers, dte_lo=20, dte_hi=45, min_pop=0.80, r=0.045):
    """Scan live option chains for >=min_pop probability-of-profit setups: premium selling
    (cash-secured puts, put/call credit spreads) + deep-ITM call debit spreads (buying).
    POP from the IV-implied lognormal at expiry. Returns trades sorted by POP then return-on-risk."""
    import datetime as _dt
    out = []

    def _pa(S, X, T, iv):  # P(S_T > X) lognormal
        if min(S, X, T, iv) <= 0:
            return None
        d2 = (np.log(S / X) + (r - 0.5 * iv * iv) * T) / (iv * np.sqrt(T))
        return float(norm.cdf(d2))

    for tk in tickers:
        tk = str(tk).strip().upper()
        if not tk:
            continue
        try:
            spot = _spot(tk) or _cached_price(tk)
            if not spot:
                continue
            try:
                exps = list(yf.Ticker(tk).options)
            except Exception:
                exps = []
            exp = dte = None
            for e in exps:
                try:
                    d = (_dt.datetime.strptime(e, "%Y-%m-%d").date() - _dt.date.today()).days
                except Exception:
                    continue
                if dte_lo <= d <= dte_hi:
                    exp, dte = e, d
                    break
            if not exp:
                continue
            T = max(dte, 1) / 365.0
            ch = _cached_option_chain(tk, exp)
            if ch is None:
                continue
            puts = ch.puts.copy(); calls = ch.calls.copy()
            for df in (puts, calls):
                df["mid"] = ((df["bid"].fillna(0) + df["ask"].fillna(0)) / 2).where(
                    (df["bid"] > 0) & (df["ask"] > 0), df["lastPrice"])

            # ── cash-secured put (sell) ──
            pl = puts[(puts["strike"] < spot) & (puts["mid"] > 0.05)].sort_values("strike", ascending=False).reset_index(drop=True)
            for i in range(len(pl)):
                K = float(pl.loc[i, "strike"]); cr = float(pl.loc[i, "mid"]); iv = float(pl.loc[i, "impliedVolatility"] or 0)
                if iv <= 0:
                    continue
                pop = _pa(spot, K - cr, T, iv)
                if pop is None or pop < min_pop:
                    continue
                ror = cr / max(K - cr, 0.01) * 100
                out.append({"Ticker": tk, "Strategy": "Cash-secured put (sell)", "DTE": dte,
                            "Expiry": exp, "Legs": f"Sell {K:g}P", "POP %": round(pop * 100, 1), "Credit/Debit": f"+${cr:.2f}",
                            "Max profit": f"${cr*100:,.0f}", "Max loss": f"${(K-cr)*100:,.0f}",
                            "Ret/risk": f"{ror:.1f}%", "Breakeven": f"${K-cr:.2f}", "_pop": pop, "_ror": ror,
                            "_exp": exp, "_spot0": spot, "_k1": K, "_k2": 0.0, "_net": cr})
                # put credit spread off the same short strike
                if i + 2 < len(pl):
                    Kl = float(pl.loc[i + 2, "strike"]); cl = float(pl.loc[i + 2, "mid"])
                    net = cr - cl; width = K - Kl
                    if net > 0.03 and width > 0:
                        ror2 = net / max(width - net, 0.01) * 100
                        out.append({"Ticker": tk, "Strategy": "Put credit spread (sell)", "DTE": dte,
                                    "Expiry": exp, "Legs": f"Sell {K:g}P / Buy {Kl:g}P", "POP %": round(pop * 100, 1),
                                    "Credit/Debit": f"+${net:.2f}", "Max profit": f"${net*100:,.0f}",
                                    "Max loss": f"${(width-net)*100:,.0f}", "Ret/risk": f"{ror2:.1f}%",
                                    "Breakeven": f"${K-net:.2f}", "_pop": pop, "_ror": ror2,
                                    "_exp": exp, "_spot0": spot, "_k1": K, "_k2": Kl, "_net": net})
                break

            # ── call credit spread (sell) ──
            cu = calls[(calls["strike"] > spot) & (calls["mid"] > 0.05)].sort_values("strike").reset_index(drop=True)
            for i in range(len(cu)):
                K = float(cu.loc[i, "strike"]); cr = float(cu.loc[i, "mid"]); iv = float(cu.loc[i, "impliedVolatility"] or 0)
                if iv <= 0:
                    continue
                pa = _pa(spot, K + cr, T, iv)
                if pa is None:
                    continue
                pop = 1 - pa
                if pop < min_pop:
                    continue
                if i + 2 < len(cu):
                    Kl = float(cu.loc[i + 2, "strike"]); cl = float(cu.loc[i + 2, "mid"])
                    net = cr - cl; width = Kl - K
                    if net > 0.03 and width > 0:
                        ror = net / max(width - net, 0.01) * 100
                        out.append({"Ticker": tk, "Strategy": "Call credit spread (sell)", "DTE": dte,
                                    "Expiry": exp, "Legs": f"Sell {K:g}C / Buy {Kl:g}C", "POP %": round(pop * 100, 1),
                                    "Credit/Debit": f"+${net:.2f}", "Max profit": f"${net*100:,.0f}",
                                    "Max loss": f"${(width-net)*100:,.0f}", "Ret/risk": f"{ror:.1f}%",
                                    "Breakeven": f"${K+net:.2f}", "_pop": pop, "_ror": ror,
                                    "_exp": exp, "_spot0": spot, "_k1": K, "_k2": Kl, "_net": net})
                break

            # ── deep-ITM call debit spread (buying, high POP) ──
            ci = calls[(calls["strike"] < spot) & (calls["mid"] > 0.05)].sort_values("strike", ascending=False).reset_index(drop=True)
            co = calls[(calls["strike"] > spot) & (calls["mid"] > 0.05)].sort_values("strike").reset_index(drop=True)
            if len(ci) > 2 and len(co) > 2:
                Kb = float(ci.loc[2, "strike"]); db = float(ci.loc[2, "mid"]); iv = float(ci.loc[2, "impliedVolatility"] or 0)
                Ks = float(co.loc[2, "strike"]); cs = float(co.loc[2, "mid"])
                net = db - cs; width = Ks - Kb
                if iv > 0 and net > 0 and width > net:
                    be = Kb + net; pop = _pa(spot, be, T, iv)
                    if pop and pop >= min_pop:
                        ror = (width - net) / net * 100
                        out.append({"Ticker": tk, "Strategy": "ITM call debit spread (buy)", "DTE": dte,
                                    "Expiry": exp, "Legs": f"Buy {Kb:g}C / Sell {Ks:g}C", "POP %": round(pop * 100, 1),
                                    "Credit/Debit": f"-${net:.2f}", "Max profit": f"${(width-net)*100:,.0f}",
                                    "Max loss": f"${net*100:,.0f}", "Ret/risk": f"{ror:.1f}%",
                                    "Breakeven": f"${be:.2f}", "_pop": pop, "_ror": ror,
                                    "_exp": exp, "_spot0": spot, "_k1": Kb, "_k2": Ks, "_net": net})
        except Exception:
            continue
    out.sort(key=lambda d: (-d["_pop"], -d["_ror"]))
    return out


# ── High-Prob RECOMMENDATION TRACKER: every scan result auto-logged as a paper trade,
#    settled at expiry from DB closes, scored win/loss + P&L on the same page ──────────
def _hiprob_ensure(c):
    c.execute("""CREATE TABLE IF NOT EXISTS hiprob_recs(
        rec_id INTEGER PRIMARY KEY AUTOINCREMENT,
        rec_date TEXT, ticker TEXT, strategy TEXT, legs TEXT,
        expiry TEXT, dte INTEGER, pop REAL, ror REAL,
        k1 REAL, k2 REAL, net REAL, spot0 REAL, capital REAL,
        status TEXT DEFAULT 'OPEN', settle_px REAL, pnl REAL,
        UNIQUE(rec_date, ticker, strategy, legs, expiry))""")
    c.commit()


def _hiprob_capital(strategy, k1, k2, net):
    """Capital at risk per 1 lot = the max loss (collateral for CSP)."""
    if "Cash-secured" in strategy:
        return (k1 - net) * 100
    if "Put credit" in strategy:
        return (k1 - k2 - net) * 100
    if "Call credit" in strategy:
        return (k2 - k1 - net) * 100
    return net * 100                       # debit spread: risk = debit paid


def _hiprob_pnl(strategy, k1, k2, net, S):
    """P&L per 1 lot held to expiry, settled at underlying close S."""
    if "Cash-secured" in strategy:
        return (net if S >= k1 else S - k1 + net) * 100
    if "Put credit" in strategy:
        w = k1 - k2
        return (net if S >= k1 else (-(w - net) if S <= k2 else S - k1 + net)) * 100
    if "Call credit" in strategy:
        w = k2 - k1
        return (net if S <= k1 else (-(w - net) if S >= k2 else k1 - S + net)) * 100
    if "debit" in strategy:
        w = k2 - k1
        return (min(max(S - k1, 0.0), w) - net) * 100
    return None


def _hiprob_persist(res):
    """Log today's scan results (INSERT OR IGNORE → same rec counted once per day)."""
    if not res:
        return 0
    today = datetime.now().strftime("%Y-%m-%d")
    n = 0
    with get_conn() as c:
        _hiprob_ensure(c)
        for d in res:
            try:
                cap = _hiprob_capital(d["Strategy"], d["_k1"], d["_k2"], d["_net"])
                c.execute("INSERT OR IGNORE INTO hiprob_recs(rec_date,ticker,strategy,legs,expiry,"
                          "dte,pop,ror,k1,k2,net,spot0,capital) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",
                          (today, d["Ticker"], d["Strategy"], d["Legs"], d["_exp"], int(d["DTE"]),
                           float(d["_pop"]) * 100, float(d["_ror"]), float(d["_k1"]),
                           float(d["_k2"]), float(d["_net"]), float(d["_spot0"]), float(cap)))
                n += c.execute("SELECT changes()").fetchone()[0]
            except Exception:
                continue
        c.commit()
    return n


def _hiprob_settle_px(c, tk, expiry):
    """Underlying close ON (or last session before) expiry — DB-first (stock_history
    then stock_daily; both ISO YYYY-MM-DD), yfinance only if the DB has nothing usable."""
    ei = str(expiry)[:10]                       # ISO date string sorts naturally
    for tbl in ("stock_history", "stock_daily"):
        try:
            r = c.execute(f"SELECT close, trade_date FROM {tbl} WHERE ticker=? AND trade_date<=? "
                          f"ORDER BY trade_date DESC LIMIT 1", (tk.upper(), ei)).fetchone()
            if r and r[0] and r[1] >= (pd.Timestamp(expiry) - pd.Timedelta(days=7)).strftime("%Y-%m-%d"):
                return float(r[0])
        except Exception:
            continue
    try:                                        # last resort: yfinance daily bar at expiry
        h = yf.Ticker(tk).history(start=pd.Timestamp(expiry) - pd.Timedelta(days=7),
                                  end=pd.Timestamp(expiry) + pd.Timedelta(days=1))
        if len(h):
            return float(h["Close"].iloc[-1])
    except Exception:
        pass
    return None


def _hiprob_settle():
    """Settle every OPEN rec whose expiry has passed: WIN/LOSS + realized P&L."""
    today = datetime.now().strftime("%Y-%m-%d")
    n = 0
    with get_conn() as c:
        _hiprob_ensure(c)
        rows = c.execute("SELECT rec_id, ticker, strategy, k1, k2, net, expiry FROM hiprob_recs "
                         "WHERE status='OPEN' AND expiry < ?", (today,)).fetchall()
        for rid, tk, strat, k1, k2, net, expiry in rows:
            S = _hiprob_settle_px(c, tk, expiry)
            if S is None:
                continue                          # no close yet — try again next load
            pnl = _hiprob_pnl(strat, float(k1), float(k2), float(net), S)
            if pnl is None:
                continue
            c.execute("UPDATE hiprob_recs SET status=?, settle_px=?, pnl=? WHERE rec_id=?",
                      ("WIN" if pnl >= 0 else "LOSS", S, round(pnl, 2), rid))
            n += 1
        c.commit()
    return n


# ══════════════════════════════════════════════════════════════════════════════
# Spreads scanner · Wheel/CSP screener · Signed GEX · Spread backtest
# Inspired by BigDipper-style positioning + spread dashboards, but built entirely
# from your own DB + yfinance + the Black-Scholes engine above (no paid feeds).
# ══════════════════════════════════════════════════════════════════════════════

def _pop_above(S, X, T, iv, r=0.045):
    """P(S_T > X) under the IV-implied lognormal at expiry."""
    if None in (S, X, T, iv) or min(S, X, T, iv) <= 0:
        return None
    d2 = (np.log(S / X) + (r - 0.5 * iv * iv) * T) / (iv * np.sqrt(T))
    return float(norm.cdf(d2))


def _pick_expiry(tk, dte_lo, dte_hi):
    """First listed expiry inside [dte_lo, dte_hi]; else the nearest expiry at/after dte_lo."""
    import datetime as _dt
    try:
        exps = list(yf.Ticker(tk).options)
    except Exception:
        return None, None
    best = None
    for e in exps:
        try:
            d = (_dt.datetime.strptime(e, "%Y-%m-%d").date() - _dt.date.today()).days
        except Exception:
            continue
        if dte_lo <= d <= dte_hi:
            return e, d
        if d >= dte_lo and (best is None or d < best[1]):
            best = (e, d)
    return best if best else (None, None)


def _chain_prep(tk, exp):
    """Return (calls, puts) DataFrames with a robust 'mid' and 'oi' column, or (None, None)."""
    ch = _cached_option_chain(tk, exp)
    if ch is None:
        return None, None
    calls = ch.calls.copy(); puts = ch.puts.copy()
    for df in (calls, puts):
        df["mid"] = ((df["bid"].fillna(0) + df["ask"].fillna(0)) / 2).where(
            (df["bid"] > 0) & (df["ask"] > 0), df["lastPrice"])
        df["oi"] = df["openInterest"].fillna(0) if "openInterest" in df.columns else 0
    return calls, puts


@st.cache_data(ttl=300, show_spinner=False)
def _spreads_scan(tickers, dte_lo=20, dte_hi=45, r=0.045, top_per=6):
    """Bull Call (debit), Bear Call (credit), Bear Put (debit) candidates, ranked by a
    composite score from POP, reward/risk, breakeven cushion, and leg liquidity."""
    out = []
    for tk in tickers:
        tk = str(tk).strip().upper()
        if not tk:
            continue
        try:
            spot = _spot(tk) or _cached_price(tk)
            if not spot:
                continue
            exp, dte = _pick_expiry(tk, dte_lo, dte_hi)
            if not exp:
                continue
            T = max(dte, 1) / 365.0
            calls, puts = _chain_prep(tk, exp)
            if calls is None:
                continue

            def _near(df):
                d = df[(df["mid"] > 0.02) & (df["strike"] >= spot * 0.85) & (df["strike"] <= spot * 1.15)]
                return d.sort_values("strike").reset_index(drop=True).to_dict("records")
            C = _near(calls); P = _near(puts)
            cand = []

            def add(strat, legs, net, width, be, pop, oi_min, direction):
                if net is None or net <= 0 or width <= 0 or pop is None or not (0 < pop < 1):
                    return
                maxp, maxl = (width - net, net) if direction == "debit" else (net, width - net)
                if maxp <= 0.05 or maxl <= 0.05:   # drop worthless far-OTM / zero-payoff legs
                    return
                if direction == "credit" and net / width < 0.05:   # collect >=5% of width
                    return
                rr = maxp / maxl
                if rr < 0.10:   # drop near-zero-reward degenerate spreads
                    return
                cushion = abs(be - spot) / spot
                score = 100 * (0.40 * pop + 0.25 * min(rr, 2) / 2
                               + 0.20 * min(cushion, 0.10) / 0.10
                               + 0.15 * min(oi_min, 500) / 500)
                cand.append({"Ticker": tk, "Strategy": strat, "DTE": dte, "Expiry": str(exp)[:10], "Legs": legs,
                             "Score": round(score, 1), "POP %": round(pop * 100, 1),
                             "Net": (f"-${net:.2f}" if direction == "debit" else f"+${net:.2f}"),
                             "Max profit": f"${maxp*100:,.0f}", "Max loss": f"${maxl*100:,.0f}",
                             "R/R": f"{rr:.2f}", "Breakeven": f"${be:.2f}", "Width": f"{width:g}",
                             "OI": int(oi_min), "_score": score, "_strat": strat})

            for i in range(len(C)):
                for j in range(i + 1, min(i + 5, len(C))):
                    a, b = C[i], C[j]
                    width = b["strike"] - a["strike"]
                    iv_a = float(a.get("impliedVolatility") or 0)
                    oi_min = min(a["oi"] or 0, b["oi"] or 0)
                    # Bull Call (debit): buy lower, sell higher
                    net = a["mid"] - b["mid"]; be = a["strike"] + net
                    add("Bull Call", f"Buy {a['strike']:g}C / Sell {b['strike']:g}C",
                        net, width, be, _pop_above(spot, be, T, iv_a), oi_min, "debit")
                    # Bear Call (credit): sell lower, buy higher
                    pa = _pop_above(spot, be, T, iv_a)
                    add("Bear Call", f"Sell {a['strike']:g}C / Buy {b['strike']:g}C",
                        net, width, be, (None if pa is None else 1 - pa), oi_min, "credit")
            for i in range(len(P)):
                for j in range(i + 1, min(i + 5, len(P))):
                    a, b = P[i], P[j]  # a = lower strike, b = higher strike
                    width = b["strike"] - a["strike"]
                    iv_b = float(b.get("impliedVolatility") or 0)
                    oi_min = min(a["oi"] or 0, b["oi"] or 0)
                    # Bear Put (debit): buy higher, sell lower
                    net = b["mid"] - a["mid"]; be = b["strike"] - net
                    pa = _pop_above(spot, be, T, iv_b)
                    add("Bear Put", f"Buy {b['strike']:g}P / Sell {a['strike']:g}P",
                        net, width, be, (None if pa is None else 1 - pa), oi_min, "debit")

            cand.sort(key=lambda d: -d["_score"])
            seen = {}
            for c in cand:
                seen.setdefault(c["_strat"], 0)
                if seen[c["_strat"]] < top_per:
                    out.append(c); seen[c["_strat"]] += 1
        except Exception:
            continue
    out.sort(key=lambda d: -d["_score"])
    return out


@st.cache_data(ttl=300, show_spinner=False)
def _wheel_scan(tickers, dte_lo=20, dte_hi=45, r=0.045, otm_max=0.18):
    """Cash-secured puts ranked by annualized yield vs assignment risk (POP)."""
    out = []
    for tk in tickers:
        tk = str(tk).strip().upper()
        if not tk:
            continue
        try:
            spot = _spot(tk) or _cached_price(tk)
            if not spot:
                continue
            exp, dte = _pick_expiry(tk, dte_lo, dte_hi)
            if not exp:
                continue
            T = max(dte, 1) / 365.0
            calls, puts = _chain_prep(tk, exp)
            if puts is None:
                continue
            pl = puts[(puts["strike"] < spot) & (puts["strike"] >= spot * (1 - otm_max)) & (puts["mid"] > 0.03)]
            for _, row in pl.iterrows():
                K = float(row["strike"]); cr = float(row["mid"]); iv = float(row.get("impliedVolatility") or 0)
                if not (iv > 0):
                    continue
                pop = _pop_above(spot, K, T, iv)   # P(S_T > K) = keep premium, no assignment
                if pop is None:
                    continue
                p_assign = 1 - pop
                yld = cr / K
                ann = yld * (365.0 / max(dte, 1))
                be = K - cr
                score = 100 * (0.45 * pop + 0.35 * min(ann, 1.0) + 0.20 * min(cr / spot, 0.05) / 0.05)
                out.append({"Ticker": tk, "DTE": dte, "Expiry": str(exp)[:10], "Strike": f"{K:g}", "Premium": f"${cr:.2f}",
                            "Yield": f"{yld*100:.2f}%", "Annualized": f"{ann*100:.0f}%",
                            "POP %": round(pop * 100, 1), "P(assign) %": round(p_assign * 100, 1),
                            "Breakeven": f"${be:.2f}", "Discount": f"{(spot-be)/spot*100:.1f}%",
                            "Capital": f"${K*100:,.0f}", "Score": round(score, 1), "_score": score})
        except Exception:
            continue
    out.sort(key=lambda d: -d["_score"])
    return out


@st.cache_data(ttl=300, show_spinner=False)
def _covered_call_scan(tickers, dte_lo=20, dte_hi=45, r=0.045, otm_max=0.18):
    """Covered calls (assume 100 shares held) ranked by annualized yield + upside-if-called."""
    out = []
    for tk in tickers:
        tk = str(tk).strip().upper()
        if not tk:
            continue
        try:
            spot = _spot(tk) or _cached_price(tk)
            if not spot:
                continue
            exp, dte = _pick_expiry(tk, dte_lo, dte_hi)
            if not exp:
                continue
            T = max(dte, 1) / 365.0
            calls, puts = _chain_prep(tk, exp)
            if calls is None:
                continue
            cu = calls[(calls["strike"] > spot) & (calls["strike"] <= spot * (1 + otm_max)) & (calls["mid"] > 0.03)]
            for _, row in cu.iterrows():
                K = float(row["strike"]); cr = float(row["mid"]); iv = float(row.get("impliedVolatility") or 0)
                if not (iv > 0):
                    continue
                pa = _pop_above(spot, K, T, iv)   # P(S_T > K) = called away
                if pa is None:
                    continue
                pop_keep = 1 - pa
                yld = cr / spot
                ann = yld * (365.0 / max(dte, 1))
                upside = (K - spot + cr) / spot   # total return if called away
                score = 100 * (0.40 * pop_keep + 0.35 * min(ann, 1.0) + 0.25 * min(upside, 0.12) / 0.12)
                out.append({"Ticker": tk, "DTE": dte, "Expiry": str(exp)[:10], "Strike": f"{K:g}", "Premium": f"${cr:.2f}",
                            "Yield": f"{yld*100:.2f}%", "Annualized": f"{ann*100:.0f}%",
                            "P(keep shares) %": round(pop_keep * 100, 1),
                            "Upside if called": f"{upside*100:.1f}%", "Score": round(score, 1), "_score": score})
        except Exception:
            continue
    out.sort(key=lambda d: -d["_score"])
    return out


@st.cache_data(ttl=300, show_spinner=False)
def _gex_profile(ticker, dte_lo=0, dte_hi=45, r=0.045):
    """Signed dealer gamma exposure (GEX) by strike across near-term expiries + zero-gamma flip.
    Convention: dealers long calls / short puts -> call gamma adds (+), put gamma subtracts (-).
    GEX per strike ≈ sign * gamma * OI * 100 * spot^2 * 0.01 (≈ $ gamma per 1% move)."""
    import datetime as _dt, collections
    tk = str(ticker).strip().upper()
    spot = _spot(tk) or _cached_price(tk)
    if not spot:
        return None
    try:
        exps = list(yf.Ticker(tk).options)
    except Exception:
        exps = []
    by = collections.defaultdict(float)
    by_c = collections.defaultdict(float); by_p = collections.defaultdict(float)
    legs = []
    for e in exps:
        try:
            d = (_dt.datetime.strptime(e, "%Y-%m-%d").date() - _dt.date.today()).days
        except Exception:
            continue
        if not (dte_lo <= d <= dte_hi):
            continue
        T = max(d, 1) / 365.0
        calls, puts = _chain_prep(tk, e)
        if calls is None:
            continue
        for df, sign, opt in ((calls, +1, "call"), (puts, -1, "put")):
            for _, row in df.iterrows():
                K = float(row["strike"]); oi = float(row.get("oi") or 0); iv = float(row.get("impliedVolatility") or 0)
                if not (oi > 0) or not (iv > 0) or K <= 0 or not (spot * 0.7 <= K <= spot * 1.3):
                    continue
                g = bs_greeks(spot, K, T, r, iv, opt)["gamma"]
                gex = sign * g * oi * 100 * spot * spot * 0.01
                by[K] += gex
                (by_c if sign > 0 else by_p)[K] += gex
                legs.append((K, T, iv, oi, sign, opt))
    if not by:
        return None
    strikes = sorted(by)
    profile = [(k, by[k]) for k in strikes]
    total = sum(by.values())
    # zero-gamma flip: scan candidate spot levels, interpolate first sign change
    flip = None; prev = None
    for S in np.linspace(spot * 0.85, spot * 1.15, 61):
        tot = 0.0
        for K, T, iv, oi, sign, opt in legs:
            tot += sign * bs_greeks(S, K, T, r, iv, opt)["gamma"] * oi * 100 * S * S * 0.01
        if prev is not None and (prev[1] < 0) != (tot < 0):
            S0, t0 = prev
            flip = S0 + (S - S0) * (0 - t0) / (tot - t0) if (tot - t0) else S
            break
        prev = (S, tot)
    call_wall = max(by_c.items(), key=lambda kv: kv[1], default=(None, 0))[0] if by_c else None
    put_wall = min(by_p.items(), key=lambda kv: kv[1], default=(None, 0))[0] if by_p else None
    return {"ticker": tk, "spot": spot, "profile": profile, "total": total,
            "flip": flip, "call_wall": call_wall, "put_wall": put_wall}


@st.cache_data(ttl=1800, show_spinner=False)
def _spread_backtest(ticker, dte=30, width_pct=0.04, profit_target=0.30, loss_threshold=0.50,
                     lookback_days=180, r=0.045):
    """Model-based vertical-spread backtest on stock_daily closes (BS-priced with trailing
    realized vol). For each historical entry it tracks the spread to expiry and records whether
    it hit the profit target or the loss threshold first. NOT live fills — a model estimate."""
    import datetime as _dt
    try:
        with get_conn() as c:
            rows = c.execute(
                "SELECT trade_date, close FROM stock_daily WHERE ticker=? "
                "ORDER BY trade_date",
                (ticker.upper(),)).fetchall()
    except Exception:
        return None
    if not rows or len(rows) < dte + 25:
        return None
    dates = [str(rt[0]) for rt in rows]
    closes = np.array([float(rt[1]) for rt in rows], dtype=float)
    # trailing 20d realized vol per index
    logret = np.diff(np.log(closes))
    n = len(closes)
    start = max(25, n - lookback_days - dte)
    strategies = ["Bull Call", "Bear Call", "Bear Put"]
    stats = {s: {"trades": 0, "tp": 0, "sl": 0} for s in strategies}

    def _spread_value(strat, S, T, iv, S0):
        if strat == "Bull Call":
            k1, k2 = S0, S0 * (1 + width_pct)
            return bs_greeks(S, k1, T, r, iv, "call")["price"] - bs_greeks(S, k2, T, r, iv, "call")["price"]
        if strat == "Bear Call":
            k1, k2 = S0 * (1 + 0.005), S0 * (1 + 0.005 + width_pct)
            return bs_greeks(S, k1, T, r, iv, "call")["price"] - bs_greeks(S, k2, T, r, iv, "call")["price"]
        # Bear Put
        k2, k1 = S0, S0 * (1 - width_pct)
        return bs_greeks(S, k2, T, r, iv, "put")["price"] - bs_greeks(S, k1, T, r, iv, "put")["price"]

    for i in range(start, n - dte):
        if i < 21:
            continue
        iv = float(np.std(logret[i - 20:i]) * np.sqrt(252))
        if not np.isfinite(iv) or iv <= 0.01:
            continue
        S0 = closes[i]
        for strat in strategies:
            credit = strat == "Bear Call"
            try:
                v0 = _spread_value(strat, S0, dte / 365.0, iv, S0)
            except Exception:
                continue
            if v0 <= 0.02:
                continue
            stats[strat]["trades"] += 1
            hit = None
            for d in range(1, dte + 1):
                S = closes[i + d]; T = max(dte - d, 0) / 365.0
                try:
                    v = _spread_value(strat, S, max(T, 1e-6), iv, S0)
                except Exception:
                    continue
                if credit:   # want value to fall
                    if v <= v0 * (1 - profit_target):
                        hit = "tp"; break
                    if v >= v0 * (1 + loss_threshold):
                        hit = "sl"; break
                else:        # debit: want value to rise
                    if v >= v0 * (1 + profit_target):
                        hit = "tp"; break
                    if v <= v0 * (1 - loss_threshold):
                        hit = "sl"; break
            if hit == "tp":
                stats[strat]["tp"] += 1
            elif hit == "sl":
                stats[strat]["sl"] += 1
    res = []
    for s in strategies:
        t = stats[s]["trades"]
        if t == 0:
            continue
        res.append({"Strategy": s, "Trades": t,
                    "TP hit %": round(stats[s]["tp"] / t * 100, 1),
                    "SL hit %": round(stats[s]["sl"] / t * 100, 1),
                    "Neither %": round((t - stats[s]["tp"] - stats[s]["sl"]) / t * 100, 1)})
    return {"ticker": ticker.upper(), "dte": dte, "pt": profit_target, "lt": loss_threshold,
            "from": dates[start], "to": dates[min(n - dte - 1, n - 1)], "rows": res}


@st.cache_data(ttl=600, show_spinner=False)
def _smartmoney_screen():
    """Per-ticker option-flow metrics from the latest options_change snapshot:
    call/put OI & ΔOI, call turnover (speculation), call/put vol ratio, LEAPS call OI (>300 DTE)."""
    import datetime as _dt
    sk = "trade_date_now"
    with get_conn() as c:
        row = c.execute(f"SELECT trade_date_now FROM options_change ORDER BY {sk} DESC LIMIT 1").fetchone()
        if not row:
            return {}
        d0 = row[0]
        df = pd.read_sql("SELECT ticker,expiry_date,openInt_Call_now,change_OI_Call,vol_Call_now,"
                         "openInt_Put_now,vol_Put_now,change_OI_Put FROM options_change WHERE trade_date_now=?",
                         c, params=(d0,))
    if df.empty:
        return {}
    df = df[~df["ticker"].astype(str).str.startswith("^")]
    for col in df.columns:
        if col not in ("ticker", "expiry_date"):
            df[col] = pd.to_numeric(df[col], errors="coerce").fillna(0)

    def _dte(e):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%m-%d-%Y", "%Y/%m/%d"):
            try:
                return (_dt.datetime.strptime(str(e), fmt).date() - _dt.date.today()).days
            except Exception:
                pass
        return None

    df["dte"] = df["expiry_date"].map(_dte)
    g = df.groupby("ticker")
    agg = g.agg(call_oi=("openInt_Call_now", "sum"), put_oi=("openInt_Put_now", "sum"),
                call_chg=("change_OI_Call", "sum"), put_chg=("change_OI_Put", "sum"),
                call_vol=("vol_Call_now", "sum"), put_vol=("vol_Put_now", "sum")).reset_index()
    agg["pcr_oi"] = agg["put_oi"] / agg["call_oi"].replace(0, np.nan)
    agg["call_turnover"] = agg["call_vol"] / agg["call_oi"].replace(0, np.nan)
    agg["cpv"] = agg["call_vol"] / agg["put_vol"].replace(0, np.nan)
    leaps = df[df["dte"] > 300].groupby("ticker")["openInt_Call_now"].sum().reset_index()
    leaps.columns = ["ticker", "leaps_call_oi"]
    agg = agg.merge(leaps, on="ticker", how="left")
    agg["leaps_call_oi"] = agg["leaps_call_oi"].fillna(0)
    return {"date": d0, "agg": agg}


@st.cache_data(ttl=600, show_spinner=False)
def _accumulation_screen():
    """Volume+price proxy from stock_daily (US has no delivery %): latest volume vs 20d avg,
    1d/5d/20d returns. Split-aware: stock_daily rows are never back-adjusted, so a >40%
    overnight 'move' whose ratio is ~integer (2:1..10:1, forward or reverse) is treated as an
    unadjusted split and older closes/volumes are rescaled (CRWD 4:1 on 07-02-2026 read as −74%)."""
    rows = []
    with get_conn() as c:
        tks = [r[0] for r in c.execute("SELECT DISTINCT ticker FROM stock_daily").fetchall()]
        for t in tks:
            try:
                df = pd.read_sql("SELECT close,volume FROM stock_daily WHERE ticker=? "
                                 "ORDER BY trade_date DESC LIMIT 25", c, params=(t,))
                cl = pd.to_numeric(df["close"], errors="coerce")
                vol = pd.to_numeric(df["volume"], errors="coerce")
                keep = cl.notna() & (cl > 0) & vol.notna()
                cl = cl[keep].to_numpy(dtype=float); vol = vol[keep].to_numpy(dtype=float)  # newest→oldest
                if len(cl) < 10:
                    continue
                split = False
                for i in range(len(cl) - 1):                     # i = newer day, i+1 = older
                    ratio = cl[i + 1] / cl[i]
                    if not (0.6 < ratio < 1.67):                 # >40% overnight jump
                        k = ratio if ratio > 1 else 1.0 / ratio
                        kr = round(k)
                        if kr >= 2 and abs(k - kr) <= 0.1 * kr:  # ~integer ratio → split, not a crash
                            f = float(kr) if ratio > 1 else 1.0 / kr
                            cl[i + 1:] /= f                      # bring pre-split closes to post-split scale
                            vol[i + 1:] *= f                     # …and share-count-scaled volume
                            split = True
                vavg = vol[1:21].mean()
                if not vavg or len(cl) < 6:
                    continue
                rows.append({"ticker": t, "vol_x": vol[0] / vavg, "split": split,
                             "r1": (cl[0] / cl[1] - 1) * 100,
                             "r5": (cl[0] / cl[5] - 1) * 100,
                             "r20": (cl[0] / cl[min(len(cl) - 1, 20)] - 1) * 100})
            except Exception:
                continue
    return pd.DataFrame(rows)


@st.cache_data(ttl=3600, show_spinner=False)
def _leaps_screen(tickers):
    """Long-dated call positioning pulled live from yfinance (your OI snapshot only keeps near-term)."""
    import datetime as _dt
    out = []
    for tk in tickers:
        try:
            t = yf.Ticker(tk)
            best = None; bdte = 0
            for e in (t.options or []):
                try:
                    d = (_dt.datetime.strptime(e, "%Y-%m-%d").date() - _dt.date.today()).days
                except Exception:
                    continue
                if d > bdte:
                    bdte, best = d, e
            if not best or bdte < 200:
                continue
            calls = t.option_chain(best).calls
            ois = pd.to_numeric(calls["openInterest"], errors="coerce").fillna(0)
            coi = float(ois.sum())
            cvol = float(pd.to_numeric(calls["volume"], errors="coerce").fillna(0).sum())
            top_s = "—"
            if len(ois) and ois.max() > 0:
                _bi = ois.idxmax()
                _K = float(calls.loc[_bi, "strike"])
                _lp = float(pd.to_numeric(calls.loc[_bi].get("lastPrice"), errors="coerce") or 0)
                top_s = f"${_K:g}C @ ${_lp:.2f} (OI {int(ois.loc[_bi]):,})"
            out.append({"Ticker": tk, "Longest expiry": best, "DTE": bdte,
                        "Top strike (where)": top_s,
                        "LEAPS call OI": int(coi), "Call vol": int(cvol)})
        except Exception:
            continue
    return pd.DataFrame(out).sort_values("LEAPS call OI", ascending=False) if out else pd.DataFrame()




