# ── Macro Dashboard data (keyless BLS + market yields + optional AlphaVantage) ──
@st.cache_data(ttl=21600, show_spinner=False)
def _macro_bls_full():
    """BLS monthly series (oldest→newest) for CPI, Core CPI, Unemployment, Nonfarm Payrolls.
    Keyless; cached 6h."""
    import urllib.request as _u, json as _j, datetime as _dt
    names = {"CUUR0000SA0": "CPI", "CUUR0000SA0L1E": "Core CPI",
             "LNS14000000": "Unemployment", "CES0000000001": "Nonfarm Payrolls",
             "WPSFD49207": "PPI", "CES0500000003": "Avg Hourly Earnings",
             "JTS000000000000000JOL": "Job Openings"}
    yr = _dt.datetime.now().year
    _payload = {"seriesid": list(names), "startyear": str(yr - 3), "endyear": str(yr)}
    _key = os.environ.get("BLS_API_KEY", "")
    if _key:
        _payload["registrationkey"] = _key   # v2 = 500 requests/day (vs 25 keyless)
    _ver = "v2" if _key else "v1"
    body = _j.dumps(_payload).encode()
    req = _u.Request(f"https://api.bls.gov/publicAPI/{_ver}/timeseries/data/", data=body,
                     headers={"Content-Type": "application/json", "User-Agent": "nyse-data/1.0"})
    raw = _j.load(_u.urlopen(req, timeout=20))
    out = {}
    for s in raw.get("Results", {}).get("series", []):
        pts = []
        for d in s.get("data", []):
            if str(d.get("period", "")).startswith("M"):
                try:
                    pts.append((int(d["year"]), int(d["period"][1:]), float(d["value"])))
                except Exception:
                    pass
        pts.sort()
        out[names[s["seriesID"]]] = pts
    return out


@st.cache_data(ttl=3600, show_spinner=False)
def _macro_yields_full():
    """Full Treasury par yield curve (keyless, official) incl. 2Y for the 2s10s spread.
    Returns {tenor: {last, prev}} (+ '_date'); yfinance fallback if Treasury is unreachable."""
    import urllib.request as _u, csv as _csv, io as _io, datetime as _dt
    want = [("3 Mo", "3M"), ("2 Yr", "2Y"), ("5 Yr", "5Y"), ("10 Yr", "10Y"), ("30 Yr", "30Y")]
    out = {}
    try:
        yr = _dt.datetime.now().year
        url = (f"https://home.treasury.gov/resource-center/data-chart-center/interest-rates/"
               f"daily-treasury-rates.csv/{yr}/all?type=daily_treasury_yield_curve"
               f"&field_tdr_date_value={yr}&page&_format=csv")
        req = _u.Request(url, headers={"User-Agent": "Mozilla/5.0 nyse-data/1.0"})
        rows = list(_csv.DictReader(_io.StringIO(_u.urlopen(req, timeout=20).read().decode("utf-8", "ignore"))))
        if rows:
            cur = rows[0]; prev = rows[1] if len(rows) > 1 else rows[0]
            for col, label in want:
                try:
                    out[label] = {"last": float(cur[col]), "prev": float(prev[col])}
                except Exception:
                    pass
            out["_date"] = cur.get("Date")
    except Exception:
        out = {}
    if not any(k for k in out if k != "_date"):   # fallback: yfinance (no 2Y)
        import yfinance as _yf
        for sym, name in [("^IRX", "3M"), ("^FVX", "5Y"), ("^TNX", "10Y"), ("^TYX", "30Y")]:
            try:
                h = _yf.Ticker(sym).history(period="1mo")["Close"].dropna()
                if len(h):
                    out[name] = {"last": float(h.iloc[-1]),
                                 "prev": float(h.iloc[-2]) if len(h) > 1 else float(h.iloc[-1])}
            except Exception:
                pass
    return out


@st.cache_data(ttl=86400, show_spinner=False)
def _macro_av_full():
    """AlphaVantage economic indicators (latest + prev + year-ago). Daily-cached to respect the
    free tier (25/day, 1/sec). Returns {name: {latest,date,prev,yago,unit}}."""
    key = os.environ.get("ALPHAVANTAGE_KEY", "")
    if not key:
        return {}
    import urllib.request as _u, json as _j, time as _t
    out = {}
    series = [("REAL_GDP", "Real GDP", "&interval=quarterly", "$B", 4),
              ("INFLATION", "Inflation (annual)", "", "%", 1),
              ("RETAIL_SALES", "Retail Sales", "", "$M", 12),
              ("DURABLES", "Durable Goods", "", "$M", 12),
              ("FEDERAL_FUNDS_RATE", "Fed Funds", "&interval=monthly", "%", 12)]
    for fn, name, extra, unit, step in series:
        try:
            url = f"https://www.alphavantage.co/query?function={fn}&apikey={key}{extra}"
            d = _j.loads(_u.urlopen(url, timeout=12).read().decode())
            data = d.get("data", [])
            if data:
                latest = float(data[0]["value"])
                prev = float(data[1]["value"]) if len(data) > 1 else latest
                yago = float(data[step]["value"]) if len(data) > step else None
                out[name] = {"latest": latest, "date": data[0]["date"], "prev": prev,
                             "yago": yago, "unit": unit}
            _t.sleep(1.3)
        except Exception:
            continue
    return out


@st.cache_data(ttl=43200, show_spinner=False)
def _fed_soma():
    """Fed balance sheet via the keyless NY Fed SOMA API (securities holdings = asset side that
    drives system liquidity). Returns total, Treasuries, MBS + 4wk/13wk/1yr change."""
    import urllib.request as _u, json as _j
    UA = {"User-Agent": "Mozilla/5.0 nyse-data/1.0"}
    s = _j.loads(_u.urlopen(_u.Request("https://markets.newyorkfed.org/api/soma/summary.json",
                                       headers=UA), timeout=20).read().decode())
    rows = s["soma"]["summary"]

    def _f(r, k):
        try:
            return float(r.get(k, 0) or 0)
        except Exception:
            return 0.0

    cur = rows[-1]
    out = {"date": cur["asOfDate"], "total": float(cur["total"]),
           "mbs": _f(cur, "mbs") + _f(cur, "cmbs"),
           "treasuries": _f(cur, "notesbonds") + _f(cur, "bills") + _f(cur, "tips") + _f(cur, "frn"),
           "chg": {}}
    n = len(rows)
    for back, lbl in [(4, "4wk"), (13, "13wk"), (52, "1yr")]:
        if n > back:
            out["chg"][lbl] = float(rows[-1]["total"]) - float(rows[-1 - back]["total"])
    out["hist"] = [(r["asOfDate"], float(r["total"])) for r in rows[-156:]]   # ~3y weekly for the chart
    return out


@st.cache_data(ttl=86400, show_spinner=False)
def _jpm_collar(n=4):
    """JPMorgan Hedged Equity Fund (JHEQX) quarterly SPX collar from SEC N-PORT filings.
    Returns newest-first list of {period, short_put, long_put, short_call}. Keyless.
    Reported quarterly with a ~60-day lag — newest row is the latest disclosed collar."""
    import urllib.request as _u, re as _re, time as _t
    UA = {"User-Agent": "nyse-data research srinivas.analystsas@gmail.com"}

    def _g(url):
        return _u.urlopen(_u.Request(url, headers=UA), timeout=30).read().decode("utf-8", "ignore")

    out = []
    try:
        feed = _g("https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=S000043249"
                  "&type=NPORT-P&count=8&output=atom")
        accs = _re.findall(r"<accession-number>(.*?)</accession-number>", feed)[:n]
        for acc in accs:
            try:
                x = _g(f"https://www.sec.gov/Archives/edgar/data/1217286/{acc.replace('-', '')}/primary_doc.xml")
            except Exception:
                continue
            per = _re.search(r"<repPdDate>(.*?)</repPdDate>", x)
            legs = {}
            for b in x.split("<invstOrSec>"):
                if "optionSwaption" not in b or not any(s in b for s in ("S&P 500", "SPX", "S&amp;P 500")):
                    continue
                pc = _re.search(r"<putOrCall>(.*?)</putOrCall>", b)
                wp = _re.search(r"<writtenOrPur>(.*?)</writtenOrPur>", b)
                ep = _re.search(r"<exercisePrice>(.*?)</exercisePrice>", b)
                if pc and wp and ep:
                    legs[f"{wp.group(1)} {pc.group(1)}"] = round(float(ep.group(1)))
            if legs:
                out.append({"period": per.group(1) if per else "?",
                            "short_put": legs.get("Written Put"),
                            "long_put": legs.get("Purchased Put"),
                            "short_call": legs.get("Written Call")})
            _t.sleep(0.3)
    except Exception:
        pass
    return out


def _macro_playbook(slope2s10s, infl_dir, fed_dir):
    """Rule-based macro regime → events to watch + impacted assets + trade leans.
    Driven by the live readings (curve, inflation trend, Fed liquidity). Educational, not advice."""
    import datetime as _dt
    today = _dt.date.today()

    def _next_wd(wd):
        d = today + _dt.timedelta(days=1)
        while d.weekday() != wd:
            d += _dt.timedelta(days=1)
        return d

    def _first_fri(y, m):
        d = _dt.date(y, m, 1)
        while d.weekday() != 4:
            d += _dt.timedelta(days=1)
        return d

    nfp = _first_fri(today.year, today.month)
    if nfp < today:
        ny, nm = (today.year + (today.month == 12), 1 if today.month == 12 else today.month + 1)
        nfp = _first_fri(ny, nm)
    events = [
        {"Event": "Jobs report / NFP", "When": nfp.strftime("%b %d"), "Moves": "rates, USD, SPX, gold",
         "Why": "labor strength sets the Fed path"},
        {"Event": "CPI inflation", "When": "~10th–13th, monthly", "Moves": "bonds, gold, USD, rate-sensitive",
         "Why": "core driver of Fed policy"},
        {"Event": "PCE (Fed's gauge)", "When": "~end of month", "Moves": "rates, growth stocks",
         "Why": "Fed's preferred inflation metric"},
        {"Event": "FOMC decision", "When": "8×/yr (~6–7 wks apart)", "Moves": "everything",
         "Why": "rate path + QT/QE guidance"},
        {"Event": "Jobless claims", "When": _next_wd(3).strftime("%b %d") + " (weekly)", "Moves": "short-term risk tone",
         "Why": "high-frequency labor read"},
        {"Event": "ISM PMIs", "When": "~1st–3rd business day", "Moves": "cyclicals, commodities",
         "Why": "growth pulse"},
        {"Event": "Retail sales", "When": "~15th–17th, monthly", "Moves": "consumer / discretionary",
         "Why": "consumer health"},
    ]
    ideas = []
    if slope2s10s is not None:
        if slope2s10s < 0:
            ideas.append({"Theme": "Inverted curve / late-cycle", "Tailwind": "Defensives XLP/XLU/XLV, quality, TLT",
                          "Headwind": "Small caps IWM, banks XLF, cyclicals", "Lean": "Defensive tilt + recession hedges"})
        elif slope2s10s > 40:
            ideas.append({"Theme": "Steep curve / re-steepening", "Tailwind": "Banks XLF, small caps IWM, industrials XLI",
                          "Headwind": "Long-duration bonds TLT", "Lean": "Cyclical / value tilt"})
        else:
            ideas.append({"Theme": "Flat curve", "Tailwind": "Quality large-cap", "Headwind": "Leveraged cyclicals",
                          "Lean": "Neutral / stock-pick"})
    if infl_dir == "hot":
        ideas.append({"Theme": "Inflation re-accelerating", "Tailwind": "Energy XLE, commodities (oil/DBC), TIPS, materials XLB",
                      "Headwind": "Long bonds TLT, growth/tech, utilities", "Lean": "Real assets / value, short duration"})
    elif infl_dir == "cooling":
        ideas.append({"Theme": "Inflation cooling", "Tailwind": "Growth/tech QQQ, semis SMH, long bonds TLT, gold",
                      "Headwind": "Energy, cash", "Lean": "Add duration & growth"})
    if fed_dir == "expanding":
        ideas.append({"Theme": "Fed adding liquidity (no QT)", "Tailwind": "Risk-on: QQQ, semis, gold, crypto, high-beta",
                      "Headwind": "USD", "Lean": "Risk-on, buy dips"})
    elif fed_dir == "qt":
        ideas.append({"Theme": "QT draining liquidity", "Tailwind": "USD, cash, quality",
                      "Headwind": "High-beta, small caps, crypto, long duration", "Lean": "De-risk / hedge"})
    bits = []
    if slope2s10s is not None:
        bits.append("curve " + ("inverted" if slope2s10s < 0 else "steep" if slope2s10s > 40 else "flat"))
    if infl_dir:
        bits.append("inflation " + infl_dir)
    if fed_dir:
        bits.append("Fed " + {"expanding": "adding liquidity", "qt": "in QT", "flat": "on hold"}.get(fed_dir, fed_dir))
    return " · ".join(bits), events, ideas


