if page == "👀 Watchlist":
    _page_header("👀 Watchlist", _PAGE_HELP["👀 Watchlist"])

    _WL_CLASSES = ["Stock", "ETF", "Bond", "Commodity"]

    def _wl_setup(conn):
        conn.execute(
            "CREATE TABLE IF NOT EXISTS watchlist (id INTEGER PRIMARY KEY AUTOINCREMENT, "
            "ticker TEXT, target_price REAL, note TEXT, added_date TEXT, status TEXT DEFAULT 'ACTIVE')")
        conn.commit()
        # asset_class added 2026-07-23 (user: subsection by Stock/ETF/Bond/Commodity) —
        # ALTER is a no-op once the column exists, so this stays safe to re-run every load.
        try:
            conn.execute("ALTER TABLE watchlist ADD COLUMN asset_class TEXT DEFAULT 'Stock'")
            conn.commit()
        except Exception:
            pass

    _wl_conn = get_conn()
    _wl_setup(_wl_conn)

    def _wl_valid_ticker(tk):
        """True if `tk` resolves to a real, currently-quoted symbol (user 2026-07-23:
        a typo'd ticker got added and just showed dashes everywhere)."""
        try:
        # FastInfo keys are camelCase ("lastPrice"); .get("last_price") therefore returned
        # None for EVERY ticker, including GOOG, and validation only ever passed via the
        # DB fallback. Anything not already in our DB -- an ADR like KSPI, quoted at $92 --
        # was rejected as "not a valid ticker" (user 2026-08-03). Attribute access works.
            fi = yf.Ticker(tk).fast_info
            px = 0.0
            for _a in ("last_price", "previous_close"):
                try:
                    _v = getattr(fi, _a, None)
                    if _v:
                        px = float(_v); break
                except Exception:
                    pass
            if px <= 0:                       # last resort: a real price series
                _h = yf.Ticker(tk).history(period="5d")
                if _h is not None and len(_h):
                    px = float(_h["Close"].iloc[-1])
            if px > 0:
                return True
        except Exception:
            pass
        return _db_spot(tk) > 0

    @st.cache_data(ttl=86400, show_spinner=False)
    def _wl_company_name(tk):
        """Company/fund name for the ticker (user ask 2026-07-28: 'place the name of the
        stocks' after the ticker). options_change.company_name_now is DB-first but only
        reliable for ETFs/funds -- it stores the bare ticker for individual stocks -- so
        this goes straight to yfinance .info, cached 24h since a name never changes."""
        try:
            info = yf.Ticker(tk).info or {}
            name = info.get("shortName") or info.get("longName")
            if name:
                return name
        except Exception:
            pass
        return tk

    with st.expander("➕ Add a ticker", expanded=True):
        _wa1, _wa2, _wa3, _wa4 = st.columns([1, 1, 1, 2])
        _wa_tk = _wa1.text_input("Ticker", key="wl_add_tk", placeholder="e.g. AAPL, GLD, TLT").strip().upper()
        _wa_class = _wa2.selectbox("Asset class", _WL_CLASSES, key="wl_add_class",
                                   help="Groups the watchlist below into subsections. "
                                        "Commodities: GLD/GC=F gold, USO/CL=F oil. Bonds: TLT/IEF/SHY.")
        _wa_target = _wa3.number_input("Target buy price (optional)", min_value=0.0, step=0.5, key="wl_add_target")
        _wa_note = _wa4.text_input("Note (optional)", key="wl_add_note", placeholder="why you're watching it")
        if st.button("➕ Add to watchlist", key="wl_add_btn"):
            if _wa_tk:
                _dupe = pd.read_sql("SELECT id FROM watchlist WHERE ticker=? AND status='ACTIVE'",
                                     _wl_conn, params=(_wa_tk,))
                if not _dupe.empty:
                    st.warning(f"{_wa_tk} is already on the watchlist.")
                elif not _wl_valid_ticker(_wa_tk):
                    st.error(f"⚠️ {_wa_tk} doesn't look like a valid/quoted ticker — not added.")
                else:
                    _wl_conn.execute(
                        "INSERT INTO watchlist (ticker, target_price, note, added_date, status, asset_class) "
                        "VALUES (?, ?, ?, ?, 'ACTIVE', ?)",
                        (_wa_tk, (_wa_target or None), (_wa_note or None),
                         datetime.now().strftime("%Y-%m-%d"), _wa_class))
                    _wl_conn.commit()
                    st.success(f"Added {_wa_tk} ({_wa_class})."); st.rerun()
            else:
                st.error("Need a ticker.")

    # Ordered by ticker_interest (PLAN.md "Adjacent-framework ideas", 2026-07-24 -- hermes-
    # agent-style preference memory: /debate logs a +1 each time you actively evaluate a
    # ticker, so the ones you actually check most surface first here instead of plain
    # insertion order). Table may not exist yet if /debate has never run -- created here too.
    _wl_conn.execute("CREATE TABLE IF NOT EXISTS ticker_interest "
                     "(ticker TEXT PRIMARY KEY, views INTEGER DEFAULT 0, last_viewed TEXT)")
    _wl_df = pd.read_sql(
        "SELECT w.* FROM watchlist w LEFT JOIN ticker_interest ti ON ti.ticker = w.ticker "
        "WHERE w.status='ACTIVE' ORDER BY COALESCE(ti.views, 0) DESC, w.id DESC", _wl_conn)
    if _wl_df.empty:
        st.info("Nothing on your watchlist yet — add a ticker above to start tracking it.")
    else:
        st.caption(f"Tracking **{len(_wl_df)}** ticker(s), ordered by how often you check each one "
                   "via /debate (most-checked first). Live spot, distance to target, earnings/ex-div, "
                   "short interest, PCR, and RSI/MACD/BB technicals — refreshed with the sidebar's Live/AH toggle.")
        try:
            import pandas_ta as _wl_pta
        except Exception:
            _wl_pta = None

        _wl_rows = []
        for _, _wr in _wl_df.iterrows():
            _wtk = str(_wr["ticker"]).upper()
            try:
                _weod = _db_spot(_wtk)
                _wspot = _cached_price(_wtk) if st.session_state.get("use_ah", True) else _weod
                _wspot = _wspot or _weod
                if not _wspot:
                    _wl_rows.append({"id": int(_wr["id"]), "Class": _wr.get("asset_class") or "Stock",
                                      "Ticker": _wtk, "Name": _wl_company_name(_wtk),
                                      "Spot": None, "Note": "no price data"})
                    continue
                _wsrc = "EOD"
                if _weod and abs(_wspot - _weod) > 1e-9:
                    try:
                        _wsrc = (_get_ah_price(_wtk) or {}).get("label") or "Live"
                    except Exception:
                        _wsrc = "Live"
                _whist = _hist_for(_wtk)          # alias-aware: a bare NSE name still resolves
                _wchg = None
                if _whist is not None and len(_whist) >= 2:
                    _wprev = float(_whist["Close"].iloc[-2])
                    _wchg = (_wspot - _wprev) / _wprev * 100 if _wprev else None
                _wtarget = _wr.get("target_price")
                _wdist = (((_wspot - _wtarget) / _wtarget * 100) if _wtarget else None)
                _wearn, _wdiv = _next_events(_wtk)
                _wsi = _si_cells(_wtk)
                _wpcr = None
                try:
                    _wpcr_row = pd.read_sql(
                        "SELECT pcr_oi FROM stock_daily WHERE ticker=? AND pcr_oi IS NOT NULL "
                        "ORDER BY trade_date DESC LIMIT 1", _wl_conn, params=(_wtk,))
                    if not _wpcr_row.empty:
                        _wpcr = float(_wpcr_row.iloc[0]["pcr_oi"])
                except Exception:
                    pass
                _wsig, _wrsi = "—", None
                if _wl_pta is not None and _whist is not None and len(_whist) >= 26:
                    _wclose = _whist["Close"]
                    _wrsi_s = _wl_pta.rsi(_wclose, length=14)
                    _wrsi = float(_wrsi_s.iloc[-1]) if _wrsi_s is not None and not _wrsi_s.empty else None
                    _wmacd_df = _wl_pta.macd(_wclose, fast=12, slow=26, signal=9)
                    _wmacd_up = True
                    if _wmacd_df is not None and not _wmacd_df.empty:
                        _wmc = _wmacd_df.columns.tolist()
                        _wmacd_col = next((c for c in _wmc if c.startswith("MACD_")), _wmc[0])
                        _wsigs_col = next((c for c in _wmc if c.startswith("MACDs_")), _wmc[2])
                        _wmacd_up = float(_wmacd_df[_wmacd_col].iloc[-1]) > float(_wmacd_df[_wsigs_col].iloc[-1])
                    _wema_s = _wl_pta.ema(_wclose, length=20)
                    _wabove_ema = (_wspot > float(_wema_s.iloc[-1])) if _wema_s is not None and not _wema_s.empty else True
                    _wpts = sum([(_wrsi or 50) < 70, (_wrsi or 50) > 50, _wmacd_up, _wabove_ema])
                    _wsig = ("🟢 BULL" if _wpts >= 3 else ("🔴 BEAR" if _wpts <= 1 else "🟡 NEUT"))
                # 52-week hi/lo + today's hi/lo, straight from stock_daily (same source as
                # everywhere else in the dashboard — no extra yfinance round trip).
                _w52hi = _w52lo = _wdh = _wdl = None
                try:
                    _wrng = pd.read_sql(
                        "SELECT MAX(high) AS hi, MIN(low) AS lo FROM (SELECT high, low FROM stock_daily "
                        "WHERE ticker=? ORDER BY trade_date DESC LIMIT 252)", _wl_conn, params=(_wtk,))
                    if not _wrng.empty and _wrng.iloc[0]["hi"] is not None:
                        _w52hi = float(_wrng.iloc[0]["hi"]); _w52lo = float(_wrng.iloc[0]["lo"])
                    _wtoday = pd.read_sql(
                        "SELECT high, low FROM stock_daily WHERE ticker=? ORDER BY trade_date DESC LIMIT 1",
                        _wl_conn, params=(_wtk,))
                    if not _wtoday.empty:
                        _wdh = float(_wtoday.iloc[0]["high"] or 0) or None
                        _wdl = float(_wtoday.iloc[0]["low"] or 0) or None
                except Exception:
                    pass
                # Call/put GEX walls, nearest liquid expiry — same engine as GEX Profile page
                _wcw = _wpw = None
                if _TB_ENGINE is not None:
                    try:
                        _wg = _TB_ENGINE._compute_gex(_wtk, _wl_conn, _wspot)
                        _wcw = _wg.get("call_wall"); _wpw = _wg.get("put_wall")
                    except Exception:
                        pass
                _wl_rows.append({
                    "id": int(_wr["id"]), "Class": _wr.get("asset_class") or "Stock",
                    "Ticker": _wtk, "Name": _wl_company_name(_wtk), "Spot": round(_wspot, 2), "Src": _wsrc,
                    "Day%": (round(_wchg, 2) if _wchg is not None else None),
                    "Day L-H": (f"${_wdl:,.2f}-${_wdh:,.2f}" if (_wdh and _wdl) else "—"),
                    "52w L-H": (f"${_w52lo:,.2f}-${_w52hi:,.2f}" if (_w52hi and _w52lo) else "—"),
                    # PERCENT of the way up the range: 0 = on the 52w low, 100 = on the high.
                    # Stored 0-100, NOT 0-1 (ID 251). ProgressColumn's `format` is printf on the
                    # RAW value and does not multiply by 100, so a 0-1 fraction under "%.0f%%"
                    # could only ever print 0% or 1% -- 0.55 rendered as "1%". Paper Trading
                    # stored the same fraction but formatted it "%.2f", which is why the two
                    # grids disagreed (1% vs 0.55) for identical underlying data.
                    "52w Pos": (round(max(0.0, min(1.0, (_wspot - _w52lo) / (_w52hi - _w52lo))) * 100, 1)
                                if (_w52hi and _w52lo and _w52hi > _w52lo and _wspot) else None),
                    # same idea on TODAY's range: 0 = printed the day's low, 100 = the day's high
                    "Day Pos": (round(max(0.0, min(1.0, (_wspot - _wdl) / (_wdh - _wdl))) * 100, 1)
                                if (_wdh and _wdl and _wdh > _wdl and _wspot) else None),
                    "Day line": None,          # filled after the intraday map is built
                    "Call Wall": (f"${_wcw:,.0f}" if _wcw else "—"),
                    "Put Wall": (f"${_wpw:,.0f}" if _wpw else "—"),
                    "Target": (round(_wtarget, 2) if _wtarget else None),
                    "Dist to Target": (f"{_wdist:+.1f}%" if _wdist is not None else "—"),
                    "Earnings": _wearn, "Ex-Div": _wdiv,
                    "SI %": _wsi[0], "DTC": _wsi[1], "Shorts": _wsi[2],
                    "PCR(OI)": (round(_wpcr, 2) if _wpcr is not None else None),
                    "RSI(14)": (round(_wrsi, 1) if _wrsi is not None else None),
                    "Signal": _wsig,
                    "Note": _wr.get("note") or "",
                    "Added": _wr.get("added_date"),
                    "_52hi": _w52hi, "_52lo": _w52lo, "_hist": _whist,
                })
            except Exception as _e:
                _wl_rows.append({"id": int(_wr["id"]), "Class": _wr.get("asset_class") or "Stock",
                                  "Ticker": _wtk, "Name": _wtk, "Spot": None, "Note": f"error: {_e}"})

        # Intraday path per ticker for the in-cell day line (ID 111, a REPEAT ask). One
        # query for the whole watchlist, from US_intraday.db (1m bars, ~31 tickers). Names
        # outside the intraday lane simply get no line rather than a fabricated one.
        _wl_paths = {}
        try:
            import sqlite3 as _sq3, os as _os3
            _ip = _os3.path.join(os.path.dirname(DB_PATH), "US_intraday.db")
            if _os3.path.exists(_ip):
                _ic = _sq3.connect(_ip, timeout=10)
                _iday = _ic.execute("SELECT MAX(trade_date) FROM intraday_bars").fetchone()[0]
                if _iday:
                    _ib = pd.read_sql(
                        "SELECT ticker, ts, close FROM intraday_bars WHERE trade_date=? "
                        "ORDER BY ticker, ts", _ic, params=(_iday,))
                    for _tkk, _g in _ib.groupby("ticker"):
                        _ser = [float(x) for x in _g["close"].tolist() if x == x]
                        if len(_ser) >= 5:
                            _wl_paths[str(_tkk).upper()] = _ser[-120:]   # last ~2h of 1m bars
                _ic.close()
        except Exception:
            _wl_paths = {}

        _WL_ICON = {"Stock": "📈", "ETF": "🧺", "Bond": "🏦", "Commodity": "🛢️"}
        _WL_PLURAL = {"Stock": "Stocks", "ETF": "ETFs", "Bond": "Bonds", "Commodity": "Commodities"}
        for _wcls in _WL_CLASSES:
            _cls_rows = [r for r in _wl_rows if r.get("Class", "Stock") == _wcls]
            if not _cls_rows:
                continue
            st.markdown(f"### {_WL_ICON.get(_wcls, '•')} {_WL_PLURAL.get(_wcls, _wcls)} ({len(_cls_rows)})")
            for _r0 in _cls_rows:
                _r0["Day line"] = _wl_paths.get(str(_r0.get("Ticker") or "").upper())
                # One box per session, green up / red down (user 2026-08-12). Built from
                # the 90d daily history already fetched for this row — no extra request.
                _r0["1W"], _r0["1M"], _r0["3M"] = _updown_pair(_r0.get("_hist"))
            _cls_show = _with_flag(pd.DataFrame(_cls_rows), at=1)   # 🌍 sits next to Ticker
            # Ticker / Name / Spot stay put when the table is scrolled right (pinned=True,
            # Streamlit >=1.42) and every header carries a hover explanation, so the
            # abbreviations do not have to be guessed at (user 2026-08-03).
            _wl_cfg = {
                "Ticker": st.column_config.TextColumn("Ticker", pinned=True, width="small",
                    help="Exchange symbol. Pinned — stays visible while you scroll right."),
                "🌍": st.column_config.ImageColumn("🌍", pinned=True, width="small",
                    help="Country the instrument belongs to. Resolved from the exchange "
                         "suffix (.NS = India) or a curated ADR/ETF map — 🇺🇸 by default, "
                         "since an unsuffixed symbol is a US listing."),
                "Name": st.column_config.TextColumn("Company", pinned=True, width="medium",
                    help="Company / instrument name."),
                "Spot": st.column_config.NumberColumn("Spot $", pinned=True, format="$%.2f",
                    help="Latest price. Live during market hours, else the last close."),
                "Src": st.column_config.TextColumn("Source",
                    help="Where the price came from: live quote, after-hours, or DB close."),
                "Day%": st.column_config.NumberColumn("Day %", format="%.2f%%",
                    help="Change vs the previous close."),
                "Day L-H": st.column_config.TextColumn("Day low–high",
                    help="Today's trading range (low to high)."),
                "Day line": st.column_config.LineChartColumn(
                    "Day path", width="small",
                    help="Today's actual intraday price path from 1-minute bars — the shape "
                         "behind the low-high range, not just its endpoints. Blank when the "
                         "ticker is outside the intraday lane (~31 names)."),
                "1W": st.column_config.ImageColumn(
                    "1W", width="medium",
                    help="One box per session for the last trading WEEK — green closed up, "
                         "red closed down. Shade carries size: pale under 1%, mid 1-3%, "
                         "deep 3%+. Drawn as a picture so it scales to the row height and "
                         "never makes the row taller."),
                "1M": st.column_config.LineChartColumn(
                    "1M", width="small",
                    help="Closing price over the last 21 sessions (a trading month). A line, "
                         "not boxes — past a couple of weeks the per-day boxes are too thin "
                         "to read and shape is the thing worth seeing."),
                "3M": st.column_config.LineChartColumn(
                    "3M", width="small",
                    help="Closing price over the last 63 sessions (a trading quarter)."),
                "Day Pos": st.column_config.ProgressColumn("Day position", min_value=0.0,
                    max_value=100.0, format="%.0f%%",
                    help="Where the current price sits inside TODAY's low-high range. "
                         "0%% = trading at the session low, 100%% = at the session high. "
                         "Closing near the high or low is what the number is telling you."),
                "52w L-H": st.column_config.TextColumn("52-week low–high",
                    help="Lowest and highest price over the past 252 trading days."),
                "52w Pos": st.column_config.ProgressColumn("52w position", min_value=0.0,
                    max_value=100.0, format="%.0f%%",
                    help="Percent of the way UP the 52-week range, not a return. "
                         "0%% = trading at the 52-week LOW, 50%% = exactly midway between "
                         "low and high, 100%% = at the 52-week HIGH. "
                         "Formula: (price - 52w low) / (52w high - 52w low)."),
                "Call Wall": st.column_config.TextColumn("Call wall",
                    help="Strike with the heaviest call open interest — acts as resistance "
                         "while price is below it. Structure, not a forecast."),
                "Put Wall": st.column_config.TextColumn("Put wall",
                    help="Strike with the heaviest put open interest — acts as a support "
                         "shelf while price is above it."),
                "Target": st.column_config.NumberColumn("Your target $", format="$%.2f",
                    help="Target price you set in the edit panel below."),
                "Dist to Target": st.column_config.TextColumn("To target %",
                    help="How far spot is from your target, in percent."),
                "Earnings": st.column_config.TextColumn("Next earnings",
                    help="Next scheduled earnings date — options get expensive into it."),
                "Ex-Div": st.column_config.TextColumn("Ex-dividend",
                    help="Ex-dividend date. Buy before it to receive the dividend; early "
                         "assignment risk rises on short calls."),
                "SI %": st.column_config.TextColumn("Short interest %",
                    help="Percent of float sold short. High = crowded short, squeeze fuel."),
                "DTC": st.column_config.TextColumn("Days to cover",
                    help="Short interest divided by average daily volume — how many days "
                         "shorts would need to buy back. Higher = more squeeze potential."),
                "Shorts": st.column_config.TextColumn("Shares short",
                    help="Total shares held short."),
                "PCR(OI)": st.column_config.NumberColumn("Put/call OI", format="%.2f",
                    help="Put open interest / call open interest. >1 = more puts. On index "
                         "ETFs this spikes at expiry and is not a signal."),
                "RSI(14)": st.column_config.NumberColumn("RSI (14d)", format="%.1f",
                    help="Relative Strength Index, 14 days. >70 conventionally overbought, "
                         "<30 oversold — descriptive, not validated here."),
                "Signal": st.column_config.TextColumn("Signal",
                    help="Composite read from the scanners. Context, not advice."),
                "Note": st.column_config.TextColumn("Your note", width="medium",
                    help="Free text you set in the edit panel below."),
                "Added": st.column_config.TextColumn("Added on",
                    help="Date this ticker was added to the watchlist."),
            }
            _wl_order = ["Ticker", "🌍", "Name", "Spot", "Day%", "1W", "1M", "3M",
                         "Day line", "Day Pos", "52w Pos",
                         "52w L-H", "Day L-H",
                         "Call Wall", "Put Wall", "Target", "Dist to Target", "RSI(14)",
                         "PCR(OI)", "SI %", "DTC", "Shorts", "Earnings", "Ex-Div",
                         "Signal", "Src", "Note", "Added"]
            _wl_disp = _cls_show.drop(columns=["id", "Class", "_52hi", "_52lo", "_hist"],
                                      errors="ignore")
            _pinned_df(_wl_disp, use_container_width=True, hide_index=True,
                         column_config=_wl_cfg,
                         column_order=[c for c in _wl_order if c in _wl_disp.columns])
            st.caption("↔️ Ticker, Company and Spot stay pinned when you scroll right · "
                       "hover any column header for what it means · **52w position** bar: "
                       "empty = at the 52-week low, full = at the high.")

            _cls_chart_rows = [r for r in _cls_rows
                               if r.get("_52hi") and r.get("_52lo") and r.get("_hist") is not None]
            if _cls_chart_rows:
                # Price SINCE ADDED (ID 254). One range selector drives every chart in the
                # section -- a per-chart control would mean a dozen widgets doing the same job.
                _wl_rng = st.radio("Chart range", list(_ADDED_RANGES), horizontal=True,
                                   index=0, key=f"wl_rng_{_wcls}",
                                   help="'Since added' starts each chart the day you put the "
                                        "ticker on the watchlist; the fixed windows compare "
                                        "names added years apart on the same footing.")
                _wl_chart_cols = st.columns(min(len(_cls_chart_rows), 3) or 1)
                for _wi, _wrow in enumerate(_cls_chart_rows):
                    with _wl_chart_cols[_wi % len(_wl_chart_cols)]:
                        _wl_nm = str(_wrow.get("Name") or _wrow["Ticker"])
                        _wl_nm = (_wl_nm[:20] + "…") if len(_wl_nm) > 21 else _wl_nm
                        _wfig = _added_price_chart(
                            _wrow["Ticker"], _wrow.get("Added"), spot=_wrow.get("Spot"),
                            ccy=_ccy_sym_of(_wrow["Ticker"]), rng=_wl_rng,
                            title=f"{_wrow['Ticker']} · {_wl_nm}")
                        _wl_since = _wfig is not None
                        if not _wl_since:
                            # No add date or no history -- fall back to the old undated line
                            # rather than dropping the ticker's chart entirely.
                            _wfig = go.Figure()
                            _wfig.add_trace(go.Scatter(y=_wrow["_hist"]["Close"], mode="lines",
                                                       line=dict(width=1.5), showlegend=False))
                        _wl_ccy = _ccy_sym_of(_wrow["Ticker"])
                        # Label the lines with their actual prices. Previously both axes were
                        # hidden, so the chart showed a shape with no numbers on it at all
                        # (user 2026-08-03).
                        _wfig.add_hline(y=_wrow["_52hi"], line_dash="dot", line_color="#e74c3c",
                                        line_width=1, annotation_text=f"52w high {_wl_ccy}{_wrow['_52hi']:,.2f}",
                                        annotation_position="top left",
                                        annotation_font=dict(size=9, color="#e74c3c"))
                        _wfig.add_hline(y=_wrow["_52lo"], line_dash="dot", line_color="#2ecc71",
                                        line_width=1, annotation_text=f"52w low {_wl_ccy}{_wrow['_52lo']:,.2f}",
                                        annotation_position="bottom left",
                                        annotation_font=dict(size=9, color="#2ecc71"))
                        if not _wl_since:
                            # The since-added chart already draws its own "now" line, axes and
                            # performance-coloured title -- only the fallback needs them here.
                            if _wrow.get("Spot"):
                                _wfig.add_hline(y=float(_wrow["Spot"]), line_dash="solid",
                                                line_color="#3498db", line_width=1.2,
                                                annotation_text=f"now {_wl_ccy}{float(_wrow['Spot']):,.2f}",
                                                annotation_position="top right",
                                                annotation_font=dict(size=9, color="#3498db"))
                            _wt_vals = sorted({round(float(_wrow["_52lo"]), 2),
                                               round(float(_wrow["Spot"] or _wrow["_52lo"]), 2),
                                               round(float(_wrow["_52hi"]), 2)})
                            _wfig.update_layout(height=210, margin=dict(l=4, r=4, t=26, b=20),
                                                title=dict(text=f"{_wrow['Ticker']} · {_wl_nm}  {_wl_ccy}{_wrow['Spot']:,.2f}",
                                                           font=dict(size=11)),
                                                xaxis=dict(visible=True, showticklabels=False,
                                                           showgrid=False, title=None, ticks=""),
                                                yaxis=dict(visible=True, side="right",
                                                           tickmode="array", tickvals=_wt_vals,
                                                           ticktext=[f"{_wl_ccy}{v:,.2f}" for v in _wt_vals],
                                                           tickfont=dict(size=9), showgrid=False),
                                                hovermode="x unified",
                                                paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)")
                        st.plotly_chart(_wfig, use_container_width=True, config={"displayModeBar": False},
                                        key=f"wl_chart_{_wrow['Ticker']}_{_wrow.get('id', _wi)}")
                        _wl_add_txt = (f" · added {_wrow.get('Added')}" if (_wl_since and _wrow.get("Added"))
                                       else " · no add date on file")
                        st.caption(f"52w {_wl_ccy}{_wrow['_52lo']:,.0f}–{_wl_ccy}{_wrow['_52hi']:,.0f}{_wl_add_txt}")
            st.markdown("---")

        with st.expander("✏️ Edit a ticker (asset class / target price / note)"):
            _wl_emap = {f"{r['Ticker']} · {r.get('Class','Stock')} (id {r['id']})": r["id"]
                       for r in _wl_rows if "id" in r}
            if _wl_emap:
                _wl_ed_pick = st.selectbox("Ticker", list(_wl_emap), key="wl_edit_pick")
                _wl_ed_id = _wl_emap[_wl_ed_pick]
                _wl_ed_row = pd.read_sql("SELECT * FROM watchlist WHERE id=?", _wl_conn, params=(_wl_ed_id,)).iloc[0]
                _we1, _we2, _we3 = st.columns([1, 1, 2])
                _we_class = _we1.selectbox("Asset class", _WL_CLASSES,
                    index=_WL_CLASSES.index(_wl_ed_row["asset_class"])
                          if _wl_ed_row.get("asset_class") in _WL_CLASSES else 0,
                    key="wl_edit_class")
                _we_target = _we2.number_input("Target buy price", min_value=0.0, step=0.5,
                    value=float(_wl_ed_row["target_price"] or 0.0), key="wl_edit_target")
                _we_note = _we3.text_input("Note", value=_wl_ed_row.get("note") or "", key="wl_edit_note")
                if st.button("💾 Save changes", key="wl_edit_save"):
                    _wl_conn.execute(
                        "UPDATE watchlist SET asset_class=?, target_price=?, note=? WHERE id=?",
                        (_we_class, (_we_target or None), (_we_note or None), _wl_ed_id))
                    _wl_conn.commit()
                    st.success(f"Updated {_wl_ed_pick.split(' ·')[0]}."); st.rerun()
            else:
                st.caption("Nothing to edit yet.")

        st.markdown("**Remove a ticker** (bought it, or lost interest)")
        _wl_map = {f"{r['Ticker']} · {r.get('Class','Stock')} (id {r['id']})": r["id"]
                   for r in _wl_rows if "id" in r}
        if _wl_map:
            _wl_rm_pick = st.selectbox("Ticker", list(_wl_map), key="wl_rm_pick")
            if st.button("🗑️ Remove", key="wl_rm_btn"):
                _wl_conn.execute("UPDATE watchlist SET status='REMOVED' WHERE id=?", (_wl_map[_wl_rm_pick],))
                _wl_conn.commit()
                st.success("Removed."); st.rerun()

# ===================================================================
# ──  PAGE: PAPER TRADING — demo positions, isolated from the real book
# ===================================================================
if page == "📝 Paper Trading":
    _page_header("📝 Paper Trading", _PAGE_HELP["📝 Paper Trading"])
    st.caption("Its own `paper_trades` table — separate from your real Portfolio, the tax "
               "clock, and Exit Planner. Safe to experiment: 'what if I took this trade?' "
               "Mirrored in Telegram via `/paper` (same table, either place shows up in both).")

    def _pt_setup(conn):
        conn.execute(
            "CREATE TABLE IF NOT EXISTS paper_trades (trade_id INTEGER PRIMARY KEY AUTOINCREMENT, "
            "ticker TEXT, option_type TEXT, strike REAL, expiry TEXT, entry_price REAL, quantity INTEGER, "
            "entry_date TEXT, status TEXT DEFAULT 'OPEN', exit_price REAL, exit_date TEXT, notes TEXT)")
        conn.commit()

    _pt_conn = get_conn()
    _pt_setup(_pt_conn)

    def _pt_mark(row):
        """Current mark: live stock price, or a live option-chain mid/last.

        Expired options (user 2026-07-24: "options in paper trading is not bringing mark
        price") get a real settlement value -- intrinsic value from the stock's close on
        the expiry date -- instead of silently falling back to entry_price (which was
        masking a real settled P&L as $0, since yfinance has no live chain for a date
        that's already passed)."""
        tk = str(row["ticker"]).upper()
        typ = str(row["option_type"]).upper()
        if typ == "STOCK":
            return _cached_price(tk) or 0.0
        _expired = False
        try:
            _expired = datetime.strptime(str(row["expiry"]), "%Y-%m-%d").date() < datetime.now().date()
        except Exception:
            pass
        if _expired:
            try:
                _settle = pd.read_sql(
                    "SELECT close FROM stock_daily WHERE ticker=? AND trade_date<=? "
                    "ORDER BY trade_date DESC LIMIT 1", _pt_conn, params=(tk, str(row["expiry"])))
                if not _settle.empty:
                    _settle_px = float(_settle.iloc[0]["close"])
                    _strike = float(row["strike"])
                    return (max(_settle_px - _strike, 0.0) if typ == "CALL"
                            else max(_strike - _settle_px, 0.0))
            except Exception:
                pass
            return float(row["entry_price"] or 0)
        try:
            oc = _cached_option_chain(tk, str(row["expiry"]))
            if oc is None:
                return float(row["entry_price"] or 0)
            side = oc.calls if typ == "CALL" else oc.puts
            if side is None or side.empty:
                return float(row["entry_price"] or 0)
            m = side[side["strike"] == float(row["strike"])]
            if m.empty:
                side = side.copy(); side["_d"] = (side["strike"] - float(row["strike"])).abs()
                m = side.nsmallest(1, "_d")
            r = m.iloc[0]
            bid, ask, last = float(r.get("bid", 0) or 0), float(r.get("ask", 0) or 0), float(r.get("lastPrice", 0) or 0)
            if bid > 0 and ask > 0:
                return (bid + ask) / 2.0
            return last or float(row["entry_price"] or 0)
        except Exception:
            return float(row["entry_price"] or 0)

    # Always starts collapsed (user 2026-08-12) — the book is what you come here to read;
    # the add form is an occasional action and was pushing the table below the fold.
    with st.expander("➕ Add a demo position", expanded=False):
        _pa1, _pa2, _pa3, _pa4 = st.columns(4)
        _pa_tk = _pa1.text_input("Ticker", key="pt_add_tk", placeholder="e.g. AAPL").strip().upper()
        _pa_typ = _pa2.selectbox("Type", ["Stock", "Call", "Put"], key="pt_add_typ")
        # Stock qty allows fractions (fractional-share investing is real, user 2026-07-24);
        # option qty is always whole contracts, so the step differs by type.
        _pa_qty = _pa3.number_input("Qty (− = short; shares if Stock, contracts if option)",
                                    step=(0.001 if _pa_typ == "Stock" else 1.0),
                                    value=1.0, format=("%.4f" if _pa_typ == "Stock" else "%.0f"),
                                    key="pt_add_qty")
        _pa_px = _pa4.number_input("Entry price (0 = use live mark)", min_value=0.0, step=0.5, key="pt_add_px")
        if _pa_typ != "Stock":
            _pa5, _pa6 = st.columns(2)
            _pa_strike = _pa5.number_input("Strike", min_value=0.0, step=0.5, key="pt_add_strike")
            _pa_exp = _pa6.text_input("Expiry (YYYY-MM-DD)", key="pt_add_exp", placeholder="2026-08-21")
        else:
            _pa_strike, _pa_exp = 0.0, ""
        _pa_c1, _pa_c2 = st.columns(2)
        _pa_entry_date = _pa_c1.date_input("Entry date", value=datetime.now().date(), key="pt_add_date")
        _pa_note = _pa_c2.text_input("Note (optional)", key="pt_add_note")
        if st.button("➕ Add demo position", key="pt_add_btn"):
            _ok = bool(_pa_tk) and float(_pa_qty) != 0
            if _ok and _pa_typ != "Stock":
                try:
                    datetime.strptime(_pa_exp, "%Y-%m-%d")
                    _ok = _pa_strike > 0
                except Exception:
                    _ok = False
            if not _ok:
                st.error("Need a ticker + non-zero qty (and strike/expiry YYYY-MM-DD for options).")
            else:
                _entry_px = _pa_px
                if not _entry_px:
                    _entry_px = (_cached_price(_pa_tk) if _pa_typ == "Stock"
                                 else _pt_mark({"ticker": _pa_tk, "option_type": _pa_typ.upper(),
                                               "strike": _pa_strike, "expiry": _pa_exp, "entry_price": 0}))
                if not _entry_px:
                    st.error("Couldn't get a live price — enter one manually.")
                else:
                    _pt_conn.execute(
                        "INSERT INTO paper_trades (ticker, option_type, strike, expiry, entry_price, "
                        "quantity, entry_date, status, notes) VALUES (?,?,?,?,?,?,?, 'OPEN', ?)",
                        (_pa_tk, _pa_typ.upper(), _pa_strike, _pa_exp, float(_entry_px),
                         float(_pa_qty) if _pa_typ == "Stock" else int(_pa_qty),
                         _pa_entry_date.strftime("%Y-%m-%d"), _pa_note or None))
                    _pt_conn.commit()
                    st.success(f"Added demo {_pa_tk} {_pa_qty:+g} @ ${_entry_px:.2f}."); st.rerun()

    _pt_df = pd.read_sql("SELECT * FROM paper_trades WHERE status='OPEN' ORDER BY trade_id DESC", _pt_conn)
    if _pt_df.empty:
        st.info("No demo positions yet — add one above to see 'what if I took this trade?'")
    else:
        # Consolidate multiple STOCK buys of the SAME ticker into ONE position with a
        # weighted-average cost basis (user 2026-07-24: "GOOGL +1sh / GOOGL +100sh shows
        # as two different [rows] ... like a proper stock platform Robinhood/Fidelity" --
        # those show one consolidated position per symbol, not a row per lot). Options
        # stay one row per contract: a 340C and a 345C are genuinely different instruments,
        # not fungible the way shares of the same stock are.
        _pt_rows = []
        _pt_expired = 0          # expired legs held back from the live grid, counted not lost
        _pt_stock = _pt_df[_pt_df["option_type"].astype(str).str.upper() == "STOCK"]
        _pt_opts = _pt_df[_pt_df["option_type"].astype(str).str.upper() != "STOCK"]
        def _pt_52w(ticker):
            """52-week hi/lo from stock_daily (user 2026-07-24: missing entirely from
            Paper Trading, same fix already in Watchlist) -- (lo, hi) or (None, None)."""
            try:
                _rng = pd.read_sql(
                    "SELECT MAX(high) AS hi, MIN(low) AS lo FROM (SELECT high, low FROM stock_daily "
                    "WHERE ticker=? ORDER BY trade_date DESC LIMIT 252)", _pt_conn, params=(ticker,))
                if not _rng.empty and _rng.iloc[0]["hi"] is not None:
                    return float(_rng.iloc[0]["lo"]), float(_rng.iloc[0]["hi"])
            except Exception:
                pass
            # stock_daily only carries the OPTIONS universe, so a broad ETF like VGT — or any
            # foreign listing — had no row and the cell just showed a dash (user 2026-08-10).
            # Price history has it, and the bare-symbol alias covers MOTHERSON-style entries.
            try:
                _sym = ticker
                if _TB_ENGINE:
                    _sym = _TB_ENGINE._yf_alias(ticker) or ticker
                _h = _cached_history(_sym, period="1y")
                if _h is not None and len(_h) > 5:
                    _hi = float(_h["High"].max() if "High" in _h else _h["Close"].max())
                    _lo = float(_h["Low"].min() if "Low" in _h else _h["Close"].min())
                    if _hi > 0:
                        return _lo, _hi
            except Exception:
                pass
            return None, None

        def _xirr(cashflows):
            """Annualized IRR for irregularly-dated cash flows (user 2026-07-24: XIRR per
            stock position). cashflows = [(date, amount), ...], amount<0 = money out (buy),
            amount>0 = money in (current value, as if sold today). Bisection on NPV=0 --
            no scipy/numpy_financial dependency needed for a single well-behaved sign change
            (one or more negative cash flows followed by one final positive one)."""
            if len(cashflows) < 2:
                return None
            t0 = min(d for d, _ in cashflows)
            def npv(rate):
                return sum(amt / (1 + rate) ** ((d - t0).days / 365.0) for d, amt in cashflows)
            lo, hi = -0.9999, 10.0   # -99.99%/yr .. +1000%/yr covers any realistic case
            f_lo, f_hi = npv(lo), npv(hi)
            if f_lo * f_hi > 0:
                return None   # no sign change in range -- can't solve (shouldn't happen for buy+current-value)
            for _ in range(100):
                mid = (lo + hi) / 2
                f_mid = npv(mid)
                if abs(f_mid) < 1e-6:
                    return mid
                if f_lo * f_mid < 0:
                    hi = mid
                else:
                    lo, f_lo = mid, f_mid
            return (lo + hi) / 2

        for _ptk, _grp in _pt_stock.groupby(_pt_stock["ticker"].str.upper()):
            _pqty = float(_grp["quantity"].sum())   # fractional shares allowed
            if _pqty == 0:
                continue
            _pentry = float((_grp["entry_price"] * _grp["quantity"]).sum() / _pqty)   # weighted avg cost
            try:
                _pmark = _cached_price(_ptk) or _pentry
            except Exception:
                _pmark = _pentry
            _ppnl = (_pmark - _pentry) * _pqty
            _ppnl_pct = _ppnl / (abs(_pentry * _pqty) or 1.0) * 100
            _pearliest = _grp["entry_date"].min()
            try:
                _pdays_held = (datetime.now().date() - datetime.strptime(str(_pearliest), "%Y-%m-%d").date()).days
            except Exception:
                _pdays_held = None
            _pearn, _pdiv = _next_events(_ptk)
            _pnotes = "; ".join(n for n in _grp["notes"].dropna().unique() if n) or ""
            _p52lo, _p52hi = _pt_52w(_ptk)
            _pcfs = [(datetime.strptime(str(_r["entry_date"]), "%Y-%m-%d"),
                      -float(_r["entry_price"]) * float(_r["quantity"])) for _, _r in _grp.iterrows()]
            _pcfs.append((datetime.now(), _pmark * _pqty))
            try:
                _pxirr = _xirr(_pcfs)
            except Exception:
                _pxirr = None
            # A non-US listing is quoted in its own currency (MOTHERSON on the NSE is in
            # rupees). Carry it per row so the column can never imply dollars it isn't.
            try:
                _pccy = _TB_ENGINE._ccy_of(_ptk)[0] if _TB_ENGINE else "USD"
            except Exception:
                _pccy = "USD"
            _pt_rows.append({"id": tuple(int(x) for x in _grp["trade_id"]),
                             "Ticker": _ptk, "Type": "Stock", "Ccy": _pccy,
                             "Qty": _pqty, "Lots": len(_grp), "Status": "🟢 Live",
                             "Entry": round(_pentry, 2), "Current Price": round(_pmark, 2),
                             "52w L-H": (f"{_p52lo:,.2f}-{_p52hi:,.2f}" if _p52hi else "—"),
                             # 0-100 and CLAMPED, matching the Watchlist grid (ID 251). Was a
                             # raw 0-1 fraction, so the same holding read "0.55" here and "1%"
                             # there. Unclamped it could also exceed 1 on a fresh 52w high and
                             # overflow the bar.
                             "52w Pos": (round(max(0.0, min(1.0, (_pmark - _p52lo) / (_p52hi - _p52lo))) * 100, 1)
                                         if _p52hi and _p52hi > _p52lo else None),
                             # Capital at risk, carried so the TOTAL row can show a REAL
                             # blended return instead of a blank (user 2026-08-10). Averaging
                             # the per-row percentages would weight a 1-share lot like a
                             # 3,000-share one; P&L over cost is the only honest total.
                             "_cost": abs(_pentry * _pqty),
                             "P&L": round(_ppnl), "P&L %": round(_ppnl_pct, 2),
                             "XIRR %": (round(_pxirr * 100, 2) if _pxirr is not None else None),
                             "Entry Date": _pearliest, "Days Held": _pdays_held,
                             "DTE": None, "Earnings": _pearn, "Ex-Div": _pdiv, "Note": _pnotes})
        for _, _pr in _pt_opts.iterrows():
            _ptk = str(_pr["ticker"]).upper()
            _ptyp = str(_pr["option_type"]).upper()
            _pqty = int(_pr["quantity"])
            _pentry = float(_pr["entry_price"] or 0)
            try:
                _pmark = _pt_mark(_pr)
            except Exception:
                _pmark = _pentry
            _ppnl = (_pmark - _pentry) * _pqty * 100
            _ppnl_pct = _ppnl / (abs(_pentry * _pqty * 100) or 1.0) * 100
            try:
                _pdays_held = (datetime.now().date() - datetime.strptime(str(_pr["entry_date"]), "%Y-%m-%d").date()).days
            except Exception:
                _pdays_held = None
            try:
                _pdte = (datetime.strptime(str(_pr["expiry"]), "%Y-%m-%d").date() - datetime.now().date()).days
            except Exception:
                _pdte = None
            # Expired legs are OUT of the live grid (user 2026-08-10). Hidden, not deleted:
            # the row stays OPEN in paper_trades, so nothing is destroyed and the count below
            # says how many are being held back. They also stop polluting the net P&L metric.
            if _pdte is not None and _pdte < 0:
                _pt_expired += 1
                continue
            _pearn, _pdiv = _next_events(_ptk)
            _p52lo, _p52hi = _pt_52w(_ptk)
            try:
                _pspot = _cached_price(_ptk) or 0.0
            except Exception:
                _pspot = 0.0
            _pstatus = "🟢 Live"
            _pt_rows.append({"id": (int(_pr["trade_id"]),),
                             "Ticker": _ptk, "Type": f"${_pr['strike']:.0f}{_ptyp[0]} exp {_pr['expiry']}",
                             "Ccy": "USD",          # listed options in this book are US
                             "Qty": _pqty, "Lots": 1, "Status": _pstatus,
                             "Entry": round(_pentry, 2), "Current Price": round(_pmark, 2),
                             "Spot": (round(_pspot, 2) if _pspot else None),
                             "52w L-H": (f"{_p52lo:,.2f}-{_p52hi:,.2f}" if _p52hi else "—"),
                             "52w Pos": (round(max(0.0, min(1.0, (_pspot - _p52lo) / (_p52hi - _p52lo))) * 100, 1)
                                         if _p52hi and _pspot and _p52hi > _p52lo else None),
                             "_cost": abs(_pentry * _pqty * 100),   # options: 100x multiplier
                             "P&L": round(_ppnl), "P&L %": round(_ppnl_pct, 2),
                             "Entry Date": _pr["entry_date"], "Days Held": _pdays_held,
                             "DTE": _pdte, "Earnings": _pearn, "Ex-Div": _pdiv,
                             "Note": _pr.get("notes") or ""})
        if not _pt_rows:
            st.info(f"No live demo positions" +
                    (f" — {_pt_expired} expired leg(s) are hidden." if _pt_expired else "."))
            st.stop()
        _pt_show = _with_flag(pd.DataFrame(_pt_rows), at=1)
        # Up/down strips for the underlying (user 2026-08-12). Fetched once per distinct
        # ticker, not once per leg — a two-leg spread on one name is one history call.
        try:
            _pt_strip, _pt_hist = {}, {}
            for _utk in {str(t).upper() for t in _pt_show["Ticker"].dropna()}:
                _pt_hist[_utk] = _hist_for(_utk)          # alias-aware: MOTHERSON -> .NS
                _pt_strip[_utk] = _updown_pair(_pt_hist[_utk])
            # Anchor on whichever price column this book actually has. An all-stock book
            # has no "Spot" column at all, and get_loc("Spot") then raised into the except
            # below — the strips were built and silently thrown away.
            _anchor = next((c for c in ("Spot", "Current Price", "Entry")
                            if c in _pt_show.columns), None)
            _at = (_pt_show.columns.get_loc(_anchor) + 1) if _anchor else len(_pt_show.columns)
            for _off, _col in enumerate(("1W", "1M", "3M")):
                _pt_show.insert(_at + _off, _col, _pt_show["Ticker"].map(
                    lambda t, _k=_off: _pt_strip.get(str(t).upper(),
                                                     (None, None, None))[_k]))
        except Exception as _spe:
            _pt_hist = {}
            st.caption(f"trend strips unavailable: {_spe}")
        # Week / month profit for the tiles (user 2026-08-12, ID 220).
        try:
            _pnl_1w, _opt_sk, _nh_sk = _period_pnl(_pt_rows, _pt_hist, 5)
            _pnl_1m, _, _ = _period_pnl(_pt_rows, _pt_hist, 21)
        except Exception:
            _pnl_1w = _pnl_1m = _opt_sk = _nh_sk = {}
        # One headline PER CURRENCY. There is no FX rate anywhere in this project, so adding
        # a rupee to a dollar would simply be a wrong number (user 2026-08-10 added an NSE
        # stock, whose Rs 194,340 gain would otherwise have inflated a USD total).
        _net_by = _pt_show.groupby("Ccy")["P&L"].sum().to_dict()
        _sym = {"USD": "$", "INR": "₹", "EUR": "€", "GBp": "p", "JPY": "¥", "HKD": "HK$",
                "CAD": "C$", "AUD": "A$", "SGD": "S$", "CHF": "CHF", "BRL": "R$"}
        # XIRR per currency, shown INSIDE the same tile (user 2026-08-12). Annualising is
        # only meaningful once a holding has run a while, so the bot's 30-day floor is
        # reused here rather than invented: a 3-day +2% would annualise to a fantasy.
        _pt_xirr = {}
        try:
            from datetime import date as _date
            _today = _date.today()
            _flows_by = {}
            for _r in _pt_rows:
                _cost, _pnl = float(_r.get("_cost") or 0), float(_r.get("P&L") or 0)
                _ed = pd.to_datetime(_r.get("Entry Date"), errors="coerce")
                if _cost <= 0 or pd.isna(_ed):
                    continue
                _flows_by.setdefault(_r.get("Ccy", "USD"), []).extend(
                    [(_ed.date(), -_cost), (_today, _cost + _pnl)])
            for _cy2, _fl in _flows_by.items():
                _span = (_today - min(d for d, _a in _fl)).days
                if _span < 30:
                    continue
                _fl = [(pd.Timestamp(d).to_pydatetime(), a) for d, a in _fl]
                _r2 = _TB_ENGINE._xirr(_fl) if _TB_ENGINE else None
                if _r2 is not None and abs(_r2) < 100:
                    _pt_xirr[_cy2] = _r2
        except Exception:
            _pt_xirr = {}

        _mc = st.columns(max(len(_net_by), 1))
        for _i, (_cy, _v) in enumerate(sorted(_net_by.items())):
            # st.metric owns the box and the big number — hand-rolling it in markdown lost
            # both, and st.markdown's sanitizer strips <img src="data:…"> so the flag came
            # out as its alt text ("INNET DEMO P&L"). st.html is not sanitized that way, so
            # the picture goes there, immediately above the untouched native metric.
            with _mc[_i]:
                try:
                    # Sized to the metric card, not to the text (user 2026-08-10) — this is
                    # the headline number for a whole market, so its flag reads as a banner.
                    st.html(_flag_html(_CCY_CC.get(_cy, "US"), 58))
                except Exception:
                    pass
                st.metric(f"Net demo P&L ({_cy})", f"{_sym.get(_cy, '')}{_v:+,.0f}")
                # Pulled up under the number so it reads as part of the same card rather
                # than a stray caption; red as asked, and always red so it is a label you
                # look for, not a sign indicator that would contradict a positive XIRR.
                _x = _pt_xirr.get(_cy)
                _cur = _sym.get(_cy, "")
                _wk, _mo = _pnl_1w.get(_cy), _pnl_1m.get(_cy)
                _amt = lambda v: (f"{_cur}{v:+,.0f}" if v is not None else "—")
                _col = lambda v: ("#2e7d32" if (v or 0) > 0 else
                                  "#c62828" if (v or 0) < 0 else "#78909c")
                # Name the reason. Lumping these together produced "3 option leg(s)
                # excluded" for a book whose three INR rows are all SHARES — the real
                # problem was that no history came back for them.
                _no = [f"{_opt_sk.get(_cy, 0)} option leg(s)"] if _opt_sk.get(_cy) else []
                if _nh_sk.get(_cy):
                    _no.append(f"{_nh_sk[_cy]} with no price history")
                _miss = " · ".join(_no)
                st.html(
                    "<div style='margin-top:-1.15rem;color:#e53935;font-weight:700;"
                    "font-size:0.95rem;letter-spacing:.2px'>XIRR "
                    + (f"{_x * 100:+,.2f}%" if _x is not None else "—")
                    + "</div>"
                    # Week/month profit sits with the headline number rather than in its own
                    # tile, so one card answers "how much, and how fast did it get there".
                    + "<div>"
                    + f"1W {_amt(_wk)}"
                    + " &nbsp;·&nbsp; "
                    + f"1M {_amt(_mo)}</div>"
                    + (f"<div>excludes {_miss}"
                       "</div>" if _miss else ""))
        if len(_net_by) > 1:
            st.caption("💱 Totals are shown **per currency and never converted** — the book "
                       "holds no FX rate, so a blended number would be false.")
        _net = _net_by.get("USD", 0)
        if _pt_expired:
            st.caption(f"⚫ {_pt_expired} expired leg(s) hidden — they still exist in "
                       "`paper_trades`, they are just out of the live view and out of the "
                       "net P&L above. Close them with **/paper close ID**.")
        # ONE TABLE PER CURRENCY (user 2026-08-10). A single grid with a single TOTAL row
        # implies a common unit, and there isn't one: entry, mark and P&L for an NSE holding
        # are rupees. Splitting also makes each TOTAL a real number instead of a sum of
        # unlike things. US first, then everything else alphabetically.
        _CCY_LABEL = {"USD": "United States (USD)", "INR": "India — NSE (INR)",
                      "EUR": "Euro area (EUR)", "GBp": "United Kingdom (GBp)",
                      "JPY": "Japan (JPY)", "HKD": "Hong Kong (HKD)",
                      "CAD": "Canada (CAD)", "AUD": "Australia (AUD)"}
        _order = (["USD"] if "USD" in _net_by else []) + sorted(
            c for c in _net_by if c != "USD")
        for _cy in _order:
            _grpdf = _pt_show[_pt_show["Ccy"] == _cy].copy()
            if _grpdf.empty:
                continue
            _cs = _sym.get(_cy, "")
            if len(_order) > 1:
                # st.html, not st.markdown — the markdown sanitizer drops <img src="data:…">
                # and the heading came out showing the alt text instead of the flag.
                try:
                    st.html(f'<h5>{_flag_html(_CCY_CC.get(_cy, "US"), 20)}&nbsp;'
                            f'{_CCY_LABEL.get(_cy, _cy)} &mdash; {len(_grpdf)} position(s), '
                            f'net {_cs}{_grpdf["P&L"].sum():+,.0f}</h5>')
                except Exception:
                    st.markdown(f"##### {_CCY_LABEL.get(_cy, _cy)} — {len(_grpdf)} "
                                f"position(s), net {_cs}{_grpdf['P&L'].sum():+,.0f}")
            # Numeric columns get None, not "" — an empty string turns the column to object
            # dtype and ProgressColumn silently stops drawing its bar.
            _tot = {c: (None if pd.api.types.is_numeric_dtype(_grpdf[c]) else "")
                    for c in _grpdf.columns}
            _tot["Ticker"] = "TOTAL"
            _tot["Ccy"] = _cy
            # A TOTAL row has no trend to draw. The two column types disagree about how to
            # say "nothing": LineChartColumn wants None (an empty string is not a series),
            # while ImageColumn renders None as the literal text "None" and wants "".
            for _tc in ("1M", "3M", "Day line"):
                if _tc in _tot:
                    _tot[_tc] = None
            if "1W" in _tot:
                _tot["1W"] = ""
            _tot["P&L"] = round(_grpdf["P&L"].sum())
            # Blended return on the capital actually deployed — P&L over cost, NOT the mean
            # of the per-row percentages (that would give a 1-share lot the same weight as a
            # 3,000-share one).
            _cost_sum = float(_grpdf["_cost"].sum()) if "_cost" in _grpdf.columns else 0.0
            if _cost_sum > 0:
                _tot["P&L %"] = round(_grpdf["P&L"].sum() / _cost_sum * 100, 2)
            _grpdf = pd.concat([_grpdf, pd.DataFrame([_tot])], ignore_index=True)
            # Coerce by NAME, not by current dtype. A column holding even one None (XIRR on
            # an option leg, DTE on a stock) is already `object` before the TOTAL row is
            # added, so a dtype-based sweep skipped exactly the columns that then printed the
            # literal "None". As float64 the same gaps render as blank cells and the
            # ProgressColumns still draw.
            for _nc in ("Qty", "Lots", "Entry", "Current Price", "Spot", "52w Pos",
                        "P&L", "P&L %", "XIRR %", "Days Held", "DTE"):
                if _nc in _grpdf.columns:
                    _grpdf[_nc] = pd.to_numeric(_grpdf[_nc], errors="coerce")
            # Streamlit's grid prints the literal word "None" for an empty numeric cell, and
            # it does so for float64 NaN and nullable Float64 alike — the TOTAL row was a row
            # of "None"s with two real numbers in it. So every column that has nothing to say
            # on the TOTAL row becomes a preformatted 2dp STRING, where blank really is blank.
            # The three columns that must stay numeric are the ones carrying meaning there:
            # P&L, P&L % and 52w Pos (the last two draw bars, which need real numbers).
            for _nc in ("Qty", "Lots", "Entry", "Current Price", "Spot", "XIRR %",
                        "Days Held", "DTE"):
                if _nc in _grpdf.columns:
                    _dec = 0 if _nc in ("Lots", "Days Held", "DTE") else 2
                    _grpdf[_nc] = _grpdf[_nc].map(
                        lambda v, _d=_dec: "" if pd.isna(v) else f"{float(v):,.{_d}f}")
            _grpdf = _grpdf.drop(columns=["id", "Ccy", "_cost"], errors="ignore")
            # Bars, not bare numbers (user asked for this and it had not reached this grid).
            # P&L% spans -100 (wiped out) to +100 (doubled); anything beyond still prints its
            # true figure in the label, the bar just pins full. 52w Pos is where the current
            # price sits inside its own yearly range: empty = at the low, full = at the high.
            _pcfg = {}
            try:
                _pcfg["P&L %"] = st.column_config.ProgressColumn(
                    "P&L %", format="%.2f%%", min_value=-100, max_value=100,
                    help="Return on the capital this position tied up. Bar spans -100% to +100%.")
                if "52w Pos" in _grpdf.columns:
                    _pcfg["52w Pos"] = st.column_config.ProgressColumn(
                        "52w position", format="%.0f%%", min_value=0.0, max_value=100.0,
                        help="Percent of the way UP the 52-week range, not a return. "
                             "0% = at the 52-week LOW, 50% = midway, 100% = at the HIGH. "
                             "Same definition and scale as the Watchlist column.")
                # Thousands separators on the money column. "localized" is newer Streamlit;
                # fall back to a plain integer format rather than lose the column.
                try:
                    _pcfg["P&L"] = st.column_config.NumberColumn("P&L", format="localized")
                except Exception:
                    _pcfg["P&L"] = st.column_config.NumberColumn("P&L", format="%d")
                if "1W" in _grpdf.columns:
                    _pcfg["1W"] = st.column_config.ImageColumn(
                        "1W", width="medium",
                        help="One box per session for the last trading week of the "
                             "UNDERLYING — green closed up, red down, shade by size. "
                             "Scales to the row height, so it never makes the row taller.")
                for _sp, _n in (("1M", 21), ("3M", 63)):
                    if _sp in _grpdf.columns:
                        _pcfg[_sp] = st.column_config.LineChartColumn(
                            _sp, width="small",
                            help=f"Underlying close over the last {_n} sessions.")
            except Exception:
                _pcfg = {}
            try:
                # A bare Styler falls back to pandas' display.precision of 6, which is how
                # this grid showed "101.000000" — the values were rounded at source, the
                # DISPLAY was not (2dp rule, user 2026-08-08). _pinned_df now caps it
                # centrally; set_properties only carries the bold mark column.
                # ProgressColumn needs a real numeric column, which a Styler's TOTAL row
                # (blank strings) breaks — so the bars go on the plain DataFrame and the
                # bold-mark styling is dropped rather than losing the bars the user asked for.
                _pinned_df(_grpdf, use_container_width=True, hide_index=True,
                           column_config=_pcfg)
            except Exception:
                _pinned_df(_grpdf, use_container_width=True, hide_index=True)
            st.caption(f"Prices and P&L in **{_cy}** ({_cs or _cy}).")

        # ── Price SINCE ADDED, per position (ID 254) ────────────────────────────────────
        # Same helper and the same range control as the Watchlist, anchored on entry_date so
        # the line starts the day the lot was opened. For a STOCK the entry price is drawn,
        # which makes the gap between the line and that level the P&L itself. For an OPTION
        # it is not: the entry there is a premium and the chart is the UNDERLYING, so drawing
        # it would put two different quantities on one axis.
        _pt_chart_rows = [r for r in _pt_rows if r.get("Entry Date")]
        if _pt_chart_rows:
            st.markdown("#### 📈 Price since you added each position")
            _pt_rng = st.radio("Chart range", list(_ADDED_RANGES), horizontal=True, index=0,
                               key="pt_rng",
                               help="'Since added' starts each chart on that lot's entry date; "
                                    "the fixed windows compare positions opened years apart.")
            _pt_cols = st.columns(min(len(_pt_chart_rows), 3) or 1)
            for _pi, _pr in enumerate(_pt_chart_rows):
                with _pt_cols[_pi % len(_pt_cols)]:
                    _p_stock = str(_pr.get("Type", "")).strip().lower() == "stock"
                    _p_fig = _added_price_chart(
                        _pr["Ticker"], _pr.get("Entry Date"),
                        spot=(_pr.get("Current Price") if _p_stock else _pr.get("Spot")),
                        entry=(_pr.get("Entry") if _p_stock else None),
                        ccy=_ccy_sym_of(_pr["Ticker"]), rng=_pt_rng,
                        title=f"{_pr['Ticker']} · {_pr.get('Type', '')}")
                    if _p_fig is None:
                        st.caption(f"{_pr['Ticker']} — no price history for this range.")
                        continue
                    st.plotly_chart(_p_fig, use_container_width=True,
                                    config={"displayModeBar": False},
                                    key=f"pt_chart_{_pr['Ticker']}_{_pi}")
                    st.caption(f"added {_pr.get('Entry Date')}" if _p_stock else
                               f"added {_pr.get('Entry Date')} · underlying price; entry line "
                               f"omitted (entry was a premium, not a share price)")

        st.markdown("---")
        st.markdown("**Close a demo position** (closing a multi-lot stock position closes ALL its lots)")
        _pt_map = {f"{r['Ticker']} {r['Type']} {r['Qty']:+g} (id {r['id']})": r["id"] for r in _pt_rows}
        _pc1, _pc2 = st.columns([3, 1])
        _pt_pick = _pc1.selectbox("Position", list(_pt_map), key="pt_close_pick")
        _pt_exit_px = _pc2.number_input("Exit price (0 = live mark)", min_value=0.0, step=0.5, key="pt_close_px")
        if st.button("✖️ Close demo position", key="pt_close_btn"):
            _pids = _pt_map[_pt_pick]
            _pnl_total = 0.0
            for _pid in _pids:
                _prow = _pt_df[_pt_df["trade_id"] == _pid].iloc[0]
                _pexit = _pt_exit_px or _pt_mark(_prow)
                _pqty2 = float(_prow["quantity"]) if str(_prow["option_type"]).upper() == "STOCK" else int(_prow["quantity"])
                _pmult2 = 1 if str(_prow["option_type"]).upper() == "STOCK" else 100
                _pnl_total += (_pexit - float(_prow["entry_price"] or 0)) * _pqty2 * _pmult2
                _pt_conn.execute(
                    "UPDATE paper_trades SET status='CLOSED', exit_price=?, exit_date=? WHERE trade_id=?",
                    (_pexit, datetime.now().strftime("%Y-%m-%d"), int(_pid)))
            _pt_conn.commit()
            _lots_txt = f" across {len(_pids)} lots" if len(_pids) > 1 else ""
            st.success(f"Closed{_lots_txt} — P&L ${_pnl_total:+,.0f}."); st.rerun()
